/* DAWAH X — ahmad, অধ্যায় 107 · খণ্ড 107 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][107]=[[21201,21201,"","আমরা আমার বাবার ব্যাপারে সব থেকে ভালো কথা বলেছি। বাবা বলেছেন আমি বাবাকে জানালার জন্য প্রার্থনা করবো। আমার প্রভু তার জন্য প্রার্থনা করলেন এবং একটি ছেলেকে উদ্ধার করলেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏عَنْ ‏ ‏النَّافِلَةِ ‏ ‏فَقَالَ ‏ ‏كَانَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَافِلَةً ‏ ‏وَلَكُمْ فَضِيلَةً ‏","","",""],[21202,21202,"","আমরা কয়েকদিনের কথা বলেছি, আমরা বলতে চাই যে আমি আমার জীবন হারিয়েছি, আমি তোমাকে বলতে চাই যে, এটা পড়ে যায় না। ঈশ্বর আদেশ দিয়েছেন এবং তিনি ঈশ্বরের করুণায় সফল হননি। তার উপর আপনার শান্তি প্রার্থনা করেছি, আমি আমার বাবার জন্য ক্ষমা প্রার্থনা করছি, তার জন্য, এবং আমি আমার জন্য কেবল প্রতিজ্ঞা করেছি. আমি ঈশ্বরের কাছে যেতে বলা হয় যে আমি আমার মায়ের একটি কাগজ লিখি। এটা একটা খেলা, তারপর তারা বানর হয় এবং ঘুরে ঘুরে যায় এবং এটি খেলতে যায়। আর তাদেরকে পর্দার দিকে নিয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏فَرْقَدًا ‏ ‏يَوْمًا فَوَجَدْتُهُ خَالِيًا فَقُلْتُ يَا ‏ ‏ابْنَ أُمِّ فَرْقَدٍ ‏ ‏لَأَسْأَلَنَّكَ الْيَوْمَ عَنْ هَذَا الْحَدِيثِ فَقُلْتُ أَخْبِرْنِي عَنْ قَوْلِكَ فِي ‏ ‏الْخَسْفِ ‏ ‏وَالْقَذْفِ أَشَيْءٌ تَقُولُهُ أَنْتَ أَوْ تَأْثُرُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا بَلْ آثُرُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ وَمَنْ حَدَّثَكَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ عَمْرٍو الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهِ ‏ ‏إِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَبِيتُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى أَكْلٍ وَشُرْبٍ وَلَهْوٍ وَلَعِبٍ ثُمَّ يُصْبِحُونَ قِرَدَةً وَخَنَازِيرَ فَيُبْعَثُ عَلَى أَحْيَاءٍ مِنْ أَحْيَائِهِمْ رِيحٌ فَتَنْسِفُهُمْ كَمَا نَسَفَتْ مَنْ كَانَ قَبْلَهُمْ بِاسْتِحْلَالِهِمْ الْخُمُورَ وَضَرْبِهِمْ بِالدُّفُوفِ وَاتِّخَاذِهِمْ ‏ ‏الْقَيْنَاتِ ‏","","",""],[21203,21203,"","আমরা আরোগ্যের গৌরবে বসে ছিলাম, সাথে সাথে শহরের ঋণের কারণে, এটা জীবনের চেয়ে ভালো ছেলে হবার জন্য যথেষ্ট আমি ঈশ্বরের কাছে প্রার্থনা করেছি তিনি যেতে হবে এবং তিনি অপরাধ ছেড়ে যেতে হবে. আমি পাগলের মন পাঠ করতে আরও সময় ব্যয় করব এবং মানুষ আমাকে বলা হয় হয় হয় হয় হয় গান হয়. এরপর আমরা একটা দরজার মধ্যে একটা দরজার বাইরে যাই আর আমার কাছে প্রেম ছিল । আমার মায়ের মুখের সব মুখ এক সারিতে ফিরে এসেছে, সে আমার মায়ের আনন্দ নিয়ে এক কঠিন অনুভূতি তৈরি করে, আর হঠাৎ করে তারা তার প্রলোভনের কাছে পৌঁছে যায়। আমি ক্ষমা করে দিব, ঈশ্বরের আছে যিনি আপনার সাথে ঠিক কাজ করেছেন, আমি ভেবেছিলাম আমি কখনও তোমার দিকে তাকানা। আমি দেখছি।","‏ ‏حَدَّثَنَا ‏ ‏الْهُذَيْلُ بْنُ مَيْمُونٍ الْكُوفِيُّ الْجُعْفِيُّ ‏ ‏كَانَ يَجْلِسُ فِي مَسْجِدِ ‏ ‏الْمَدِينَةِ ‏ ‏يَعْنِي مَدِينَةَ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏هَذَا شَيْخٌ قَدِيمٌ كُوفِيٌّ ‏ ‏عَنْ ‏ ‏مُطَّرِحِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ فِيهَا ‏ ‏خَشْفَةً ‏ ‏بَيْنَ يَدَيَّ فَقُلْتُ مَا هَذَا قَالَ ‏ ‏بِلَالٌ ‏ ‏قَالَ فَمَضَيْتُ فَإِذَا أَكْثَرُ أَهْلِ الْجَنَّةِ فُقَرَاءُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَذَرَارِيُّ ‏ ‏الْمُسْلِمِينَ وَلَمْ أَرَ أَحَدًا أَقَلَّ مِنْ الْأَغْنِيَاءِ وَالنِّسَاءِ قِيلَ لِي أَمَّا الْأَغْنِيَاءُ فَهُمْ هَاهُنَا بِالْبَابِ يُحَاسَبُونَ ‏ ‏وَيُمَحَّصُونَ ‏ ‏وَأَمَّا النِّسَاءُ فَأَلْهَاهُنَّ الْأَحْمَرَانِ الذَّهَبُ وَالْحَرِيرُ قَالَ ثُمَّ خَرَجْنَا مِنْ أَحَدِ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ فَلَمَّا كُنْتُ عِنْدَ الْبَابِ أُتِيتُ بِكِفَّةٍ فَوُضِعْتُ فِيهَا وَوُضِعَتْ أُمَّتِي فِي كِفَّةٍ فَرَجَحْتُ بِهَا ثُمَّ أُتِيَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَوُضِعَ فِي كِفَّةٍ وَجِيءَ بِجَمِيعِ أُمَّتِي فِي كِفَّةٍ فَوُضِعُوا فَرَجَحَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَجِيءَ ‏ ‏بِعُمَرَ ‏ ‏فَوُضِعَ فِي كِفَّةٍ وَجِيءَ بِجَمِيعِ أُمَّتِي فَوُضِعُوا فَرَجَحَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَعُرِضَتْ أُمَّتِي رَجُلًا رَجُلًا فَجَعَلُوا يَمُرُّونَ ‏ ‏فَاسْتَبْطَأْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏ثُمَّ جَاءَ بَعْدَ ‏ ‏الْإِيَاسِ ‏ ‏فَقُلْتُ ‏ ‏عَبْدُ الرُّحْمَنِ ‏ ‏فَقَالَ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا خَلَصْتُ إِلَيْكَ حَتَّى ظَنَنْتُ أَنِّي لَا أَنْظُرُ إِلَيْكَ أَبَدًا إِلَّا بَعْدَ ‏ ‏الْمُشِيبَاتِ ‏ ‏قَالَ وَمَا ذَاكَ قَالَ مِنْ كَثْرَةِ مَالِي أُحَاسَبُ ‏ ‏وَأُمَحَّصُ ‏","","",""],[21204,21204,"","আমি আমার শোকের পর্দা নিয়ে কথা বলেছি, কিন্তু আমি নিশ্চিত যে আমি এটা শুনতে পেরে খুশি। আমার বাবা বললেন, তিনি স্বর্গে আত্মসমর্পণ করেছেন, তাই আমি ঈশ্বরকে ভালবাসি। আমি তাকে বলতে চাই, তিনি আসলে কে? এই গর্ভপাতের সময় হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ السِّيلَحِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ الشَّامِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمِقَةُ ‏ ‏فِي السَّمَاءِ فَإِذَا أَحَبَّ اللَّهُ عَبْدًا قَالَ ‏ ‏إِنِّي أَحْبَبْتُ فُلَانًا فَأَحِبُّوهُ قَالَ فَتَنْزِلُ لَهُ ‏ ‏الْمِقَةُ ‏ ‏فِي أَهْلِ الْأَرْضِ ‏","","",""],[21205,21205,"","আমরা এমন একটা ছেলের কথা বলেছি যে অতীতের অনুগ্রহের জন্য এসেছে। আমি বলছি, আমি ঈশ্বরের ইচ্ছার পথে এসেছি এবং সে হবে। শক্তি দ্বারা উদ্ধার, আমি এটা কখনোই করতে হবে না একবারও করতে হবে, সে করেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ السِّيلَحِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَتَحْتَ رَاحِلَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ فَقَالَ قَوْلًا حَسَنًا جَمِيلًا وَكَانَ فِيمَا قَالَ ‏ ‏مَنْ أَسْلَمَ مِنْ أَهْلِ الْكِتَابَيْنِ فَلَهُ أَجْرُهُ مَرَّتَيْنِ وَلَهُ مَا لَنَا وَعَلَيْهِ مَا عَلَيْنَا وَمَنْ أَسْلَمَ مِنْ الْمُشْرِكِينَ فَلَهُ أَجْرُهُ وَلَهُ مَا لَنَا وَعَلَيْهِ مَا عَلَيْنَا ‏","","",""],[21206,21206,"","আমরা পুত্রদের কথা বলেছি আমরা ঈশ্বরের প্রতি ভালোবাসা নিয়ে আপনাদের সাহায্য করার চেষ্টা করেছি। আমার বাবার শপথ আছে, সে বেনকে এক বছর হিসেবে শাস্তি দিতে বলেছে, \"ঈশ্বর, ঈশ্বর, বেঁচে থাকা তোমার।\" আর তোমার বাবার পরিকল্পনায় তোমার সাহায্য করবে না।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا النَّجَاةُ قَالَ ‏ ‏أَمْلِكْ عَلَيْكَ لِسَانَكَ وَلْيَسَعْكَ بَيْتُكَ وَابْكِ عَلَى خَطِيئَتِكَ ‏","","",""],[21207,21207,"","আমরা যে ছেলেদের কথা বলেছিলাম, যখন আপনি আমাকে বলেছিলেন যে আপনার প্রয়োজন আছে, ঈশ্বরের দোহাই আমার বাবার কাছে প্রার্থনা করা থেকে ভাল। তুমি তার মুখে অথবা হাতে তার হাত দিয়ে তার মৃত্যু হবে.","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ تَمَامِ ‏ ‏عِيَادَةِ ‏ ‏الْمَرِيضِ أَنْ يَضَعَ أَحَدُكُمْ يَدَهُ عَلَى جَبْهَتِهِ ‏ ‏أَوْ يَدِهِ ‏ ‏فَيَسْأَلُهُ كَيْفَ هُوَ وَتَمَامُ تَحِيَّاتِكُمْ بَيْنَكُمْ الْمُصَافَحَةُ ‏","","",""],[21208,21208,"","আমরা একটা স্মৃতি নিয়ে কথা বলেছিলাম যখন আমরা স্বামী বাবার সাথে কথা বলেছিলাম। বাবা বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন যেন তিনি শপথ করে শান্তি থেকে আত্মসমর্পণ করেন। এটা আরও ভাল আলো এবং ভাল আলো। এটা আমাদের কাছের ব্যাপার। আমি মনে করি, আমি আমার বাবা, আমি যখন স্বামী-বাবার বাবা তার বাবার সাথে কথা বলেছি, আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কাছে প্রার্থনা করি, আমি আমার বাবা তার কাছে প্রার্থনা করি, আমি আমার বাবার কাছে প্রার্থনা করি, আমি তাকে বলেছিলাম, প্রার্থনা করা ভালো হবে যে ঈশ্বর কখনো এরকম কিছু করেননি। চলে যাওয়াটাই ভাল।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّصَافَةِ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏بَاهِلَةَ ‏ ‏أَعْرَابِيٌّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرِئٍ مُسْلِمٍ تَحْضُرُهُ صَلَاةٌ مَكْتُوبَةٌ فَيَقُومُ فَيَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ وَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غَفَرَ اللَّهُ لَهُ بِهَا مَا كَانَ بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ثُمَّ يَحْضُرُ صَلَاةً مَكْتُوبَةً فَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ثُمَّ يَحْضُرُ صَلَاةً مَكْتُوبَةً فَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ‏","","",""],[21209,21209,"","আমরা ভালবাসার কথা বলেছি, আমাকে বলা হয়েছে যে আমার সাথে কথা বলার জন্য একটা কোভেনের ছেলে। ঈশ্বরের ইচ্ছা তার কাছে প্রার্থনা করবে এবং যমজদের সমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ ‏","","",""],[21210,21210,"","আমরা একজন যাজকের ছেলের সাথে কথা বলেছি যে আমাকে বিক্রি করতে বলেছে। সালাম তার ভাই, আমার বাবা অনেক চিন্তিত যে, নবী এসেছেন। আল্লাহকে হারানোর অধিকার, আল্লাহকে ছেড়ে দাও। আর আমরা যদি আমাদের মধ্যে থেকে কিছু বলার চেষ্টা করি, তাহলে আমরা এর থেকে ভালো কিছু পাব। আমার বাবা আছে যে আমি কথা বলতে চাই। পবিত্র পিতা.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ بِهَا النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ ‏ ‏قَضِيبًا ‏ ‏مِنْ أَرَاكٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏أَحَدِ ‏ ‏بَنِي حَارِثَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا ‏ ‏أَبُو أُمَامَةَ الْحَارِثِيُّ ‏ ‏وَلَيْسَ هُوَ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏","","",""],[21211,21211,"","আমরা ভালোবাসার কথা বলেছি, একটি ভালো ছেলের সাথে আমার ভালো ছেলের সাথে ভ্রমণ করতে চেষ্টা করে। আমার বাবার কষ্ট, ভবিষ্যদ্বাণী ঈশ্বরের ইচ্ছাতে পৌঁছেছে এবং সে আছে। তিনি বলেছিলেন যে, তিনি শুধু প্রার্থনাই করতে পারবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏السَّفْرُ بْنُ نُسَيْرٍ الْأَزْدِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَأْتِي أَحَدُكُمْ الصَّلَاةَ وَهُوَ ‏ ‏حَاقِنٌ ‏ ‏وَلَا يَؤُمَّنَّ أَحَدُكُمْ فَيَخُصَّ نَفْسَهُ بِالدُّعَاءِ دُونَهُمْ فَمَنْ فَعَلَ فَقَدْ خَانَهُمْ ‏","","",""],[21212,21212,"","আমরা এমন এক শিকারীর সাথে কথা বলেছি যে আমার সাথে কথা বলেছে, আমি বলবো তুমি সব কিছু গুনছো আর চলে যাও, পেপার গোলাপ।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَقْعُدُ الْمَلَائِكَةُ عَلَى أَبْوَابِ الْمَسَاجِدِ يَوْمَ الْجُمُعَةِ فَيَكْتُبُونَ الْأَوَّلَ وَالثَّانِيَ وَالثَّالِثَ حَتَّى إِذَا خَرَجَ الْإِمَامُ رُفِعَتْ الصُّحُفُ ‏","","",""],[21213,21213,"","আমরা প্রেমের কথা বলেছি, আমরা যা করেছি তার সব থেকে ভালো বিচার করার জন্য। আল্লাহ তাঁর কাছে প্রার্থনা করেছেন এবং ভালো কিছু খোঁজার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو غَالِبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّفْلُ فِي الْمَسْجِدِ سَيِّئَةٌ وَدَفْنُهُ حَسَنَةٌ ‏","","",""],[21214,21214,"","আমরা সেই দিন বোমা বিস্ফোরণের বছর সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَأَبُو الْمُغِيرَةِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ الْخَبَائِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ يَفْضُلُ مِنْ أَهْلِ بَيْتِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُبْزُ الشَّعِيرِ ‏","","",""],[21215,21215,"","আমরা একটি জীবন নিয়ে জন্মগ্রহণ করেছি, যা আমরা কথা বলেছি, ফাদার বাগ মানে একটি ছেলে খুঁজে বের করা যে একটি ছেলে আছে তার জন্য যার একটি মেয়ে আছে তার বাবার আছে যে বাবা মা তার বাবার পিতা, তার পিতা পিতা পিতা, তার বাবা বাবা আছে, যে তার পিতা পিতা পিতা রয়েছে, সে তার বাবা বাবা। আর তিনি আপন হৃদয় দ্বারা আমার দ্বারা প্রভাবিত হইবেন, এবং তিনি তাহার সমস্ত অর্ধ অর্ধ অর্ধাঙ্গের সন্ধান করিবেন ।","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنِ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُصَلُّوا عِنْدَ طُلُوعِ الشَّمْسِ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا كُلُّ كَافِرٍ وَلَا عِنْدَ غُرُوبِهَا فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا كُلُّ كَافِرٍ وَلَا نِصْفَ النَّهَارِ فَإِنَّهُ عِنْدَ ‏ ‏سَجْرِ ‏ ‏جَهَنَّمَ ‏","","",""],[21216,21216,"","আমি আমার বাবা বধিরদের কথা বলেছিলাম। লর্ড তার কাছে প্রার্থনা করল এবং তিনি শপথের পর তাদেরকে উদ্ধার করতেন এবং অসিসে পড়ে যেতেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّيهِمَا بَعْدَ ‏ ‏الْوِتْرِ ‏ ‏وَهُوَ جَالِسٌ يَقْرَأُ فِيهِمَا ‏ ‏إِذَا زُلْزِلَتْ الْأَرْضُ ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏","","",""],[21217,21217,"","আমি আমার বাবার মায়ের কথা বলেছি, আমি বলতে চাই যে সে তাদেরকে যুদ্ধের পর গুনতে শিখিয়েছে। তার গলায়.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَرْبَعَةٌ ‏ ‏تَجْرِي عَلَيْهِمْ أُجُورُهُمْ بَعْدَ الْمَوْتِ ‏ ‏مُرَابِطٌ ‏ ‏فِي سَبِيلِ اللَّهِ وَمَنْ عَمِلَ عَمَلًا أُجْرِيَ لَهُ مِثْلُ مَا عَمِلَ وَرَجُلٌ ‏ ‏تَصَدَّقَ ‏ ‏بِصَدَقَةٍ ‏ ‏فَأَجْرُهَا لَهُ مَا جَرَتْ وَرَجُلٌ تَرَكَ وَلَدًا صَالِحًا فَهُوَ يَدْعُو لَهُ ‏","","",""],[21218,21218,"","আমরা জানতে চেষ্টা করেছি যে আমরা একটি ছেলে কথা বলেছি এবং আমাকে ঈশ্বরের সমুদ্র পার হতে বলেছেন. ডার্ক লর্ডের দয়া আছে, ঈশ্বর তাকে আদেশ করেছেন এবং তিনি যেন হবেন তার কথা শুনতে পারেন ঈশ্বর অন্য দিন, সে মুক্ত নয়, আর সে তার বিদায় জানাতে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ حَرِيرًا وَلَا ذَهَبًا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ بْنِ مَعْرُوفٍ ‏","","",""],[21219,21219,"","আমরা শুধু একটা ছেলের জন্য আমার সংবাদ চুরি করার চেষ্টা করেছি, যার কোন ধারনা নেই যে ঈশ্বরের সেরা সন্তান আছে। আমি শুনেছি নবী তার কাছে প্রার্থনা করেছেন যে সে ঈশ্বরের উপর বিশ্বাস করবে। অবশ্যই.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ حَرِيرًا وَلَا ذَهَبًا ‏","","",""],[21220,21220,"","আমরা আমাদের গোপন বিষয় নিয়ে কথা বলেছি, একমাত্র মানুষের সুনাম একজন বা অন্য কারো মত ভালো না, একজন ব্যথাখোর, আমি যা বলছি তা হচ্ছে, আমি যা বলছি তা হচ্ছে,","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ الرَّجُلِ الْوَاحِدِ لَيْسَ بِنَبِيٍّ مِثْلُ الْحَيَّيْنِ ‏ ‏أَوْ أَحَدِ الْحَيَّيْنِ ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏ ‏قَالَ قَائِلٌ يَا رَسُولَ اللَّهِ أَوَمَا ‏ ‏رَبِيعَةُ ‏ ‏مِنْ ‏ ‏مُضَرَ ‏ ‏قَالَ إِنَّمَا أَقُولُ مَا أُقَوَّلُ ‏","","",""],[21221,21221,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে আমাদের সাথে কথা বলেছে, যখন থেকে আল্লাহ্‌র কাছে কথা বলেছে, আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন যে তার প্রতি দয়া করেছে, মহান ঈশ্বরের উপর।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَفَعَ لِأَحَدٍ شَفَاعَةً فَأَهْدَى لَهُ هَدِيَّةً فَقَبِلَهَا فَقَدْ أَتَى بَابًا عَظِيمًا مِنْ الرِّبَا ‏","","",""],[21222,21222,"","আমরা আমাদের জীবনের সবচেয়ে ভাল অর্থ নিয়ে কথা বলেছি... ...আমার বাবার টাক-চাঁড় প্রেম নিয়ে একটা ছেলে, আমার বাবার কাছে কসম করে বলছি, সে কে?","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ وَبِرَسُولِهِ ‏","","",""],[21223,21223,"","আমরা এক মাসের জন্য ভালবাসার জন্য যে আবেগ নিয়ে প্রার্থনা করেছি, তা আমরা পেয়েছি। তিনি তার জন্য প্রার্থনা করেন এবং বলেন, আলোকটি গ্রহণ করার মত যথেষ্ট হবে এবং তারপর তা গ্রহণ করার জন্য প্রার্থনা সংক্ষিপ্ত হবে, তুমি তাকে ঈশ্বরের অনুগ্রহ থেকে শুনতে, ঈশ্বর তাকে একটি ভাল স্বপ্ন সৃষ্টি করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْحِمْصِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْوُضُوءَ يُكَفِّرُ مَا قَبْلَهُ ثُمَّ تَصِيرُ الصَّلَاةُ ‏ ‏نَافِلَةً ‏ ‏قَالَ فَقِيلَ لَهُ أَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ وَلَا ثَلَاثٍ وَلَا أَرْبَعٍ وَلَا خَمْسٍ ‏","","",""],[21224,21224,"","আমরা আমার বাবার মৃত্যুর খবর নিয়ে কথা বলেছি, ঈশ্বরের ইচ্ছা হবে তার কাছে প্রার্থনা করবে এবং তাকে আত্মসমর্পণ করবে, যে তোমাকে স্পর্শ করবে এবং বলে ঈশ্বর তাঁর কাছে এসেছে। আমি জানি, আমার বাবা আমার বাবার মৃত্যুর কথা শুনেছেন। সামনে গিয়ে সূর্য চুরি করতে চাই, আমি রিং করছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْجَعْدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏قَاصٍّ ‏ ‏يَقُصُّ فَأَمْسَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُصَّ فَلَأَنْ أَقْعُدَ غُدْوَةً إِلَى أَنْ تُشْرِقَ الشَّمْسُ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ ‏","","",""],[21225,21225,"","আমি আমার বিশ্বাসের সর্বোচ্চ কথা বলেছি মন্দ থেকে ভালোর চেয়ে ভালো। আমি ঈশ্বরের কাছে প্রেরণ করতে পারি না। তার শান্তি এবং তার নাম তোমার দ্বারা নিশ্চিত না হওয়ার জন্য। প্রার্থনা করছি, এমন কিছু নিয়ে... ...যদি সে কিছু না করে, তাহলে আমি তাকে খুন করতে চাই.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏السَّفْرِ بْنِ نُسَيْرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْتِ أَحَدُكُمْ الصَّلَاةَ وَهُوَ ‏ ‏حَاقِنٌ ‏ ‏وَلَا يَخُصَّ نَفْسَهُ بِشَيْءٍ دُونَ أَصْحَابِهِ وَلَا يُدْخِلْ عَيْنَيْهِ بَيْتًا حَتَّى يَسْتَأْذِنَ ‏ ‏فَقَالَ ‏ ‏شَيْخٌ ‏ ‏لَمَّا ‏ ‏حَدَّثَهُ ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ بِهَذَا الْحَدِيثِ ‏","","",""],[21226,21226,"","আমরা একটা কুত্তার বাচ্চাের সাথে কথা বলেছি, সে খারাপ লোকের সাথে কথা বলছে, আমি কখনো আমার নিজের কোন কাজ করিনি, ভুল হচ্ছে, কিন্তু লর্ডের কাছে প্রার্থনা করতে শুনেছি যে ঈশ্বরের কাছে প্রার্থনা করতে হবে। তিনি আমার মন পরিবর্তন করেন এবং কখনো গান গাইতেন না ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ جَشِيبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏قَالَ ‏ ‏حَضَرْنَا صَنِيعًا ‏ ‏لِعَبْدِ الْأَعْلَى بْنِ هِلَالٍ ‏ ‏فَلَمَّا فَرَغْنَا مِنْ الطَّعَامِ قَامَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏فَقَالَ لَقَدْ قُمْتُ مَقَامِي هَذَا وَمَا أَنَا بِخَطِيبٍ وَمَا أُرِيدُ الْخُطْبَةَ وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عِنْدَ انْقِضَاءِ الطَّعَامِ ‏ ‏الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ قَالَ فَلَمْ يَزَلْ يُرَدِّدُهُنَّ عَلَيْنَا حَتَّى حَفِظْنَاهُنَّ ‏","","",""],[21227,21227,"","আমি দেখেছি, আমি কার মুখ দেখতে পাইনি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي عُتْبَةَ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أُمَّتِي أَحَدٌ إِلَّا وَأَنَا أَعْرِفُهُ يَوْمَ الْقِيَامَةِ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏مَنْ رَأَيْتَ وَمَنْ لَمْ تَرَ قَالَ مَنْ رَأَيْتُ وَمَنْ لَمْ أَرَ غُرًّا مُحَجَّلِينَ مِنْ أَثَرِ الطُّهُورِ ‏","","",""],[21228,21228,"","আমি যা করেছি, তা শোনার মাধ্যমে আমি আমার জীবনকে রক্ষা করার বিষয়ে কথা বলেছিলাম । আমি তোমার মত কাউকে বলতে পারবো না, ঈশ্বর এমন হবেন না যে... যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে হবে পুরুষ হবে নিরাপদ , রাজা হবে সে, সে হবে সেই রাজা, তারা তোমার পাছা উড়িয়ে দিবে আর আমি তোমাকে একটা ছেলের মত যেতে দিতে পারবো না। দুই বছর আমি ওকে ঈশ্বরের কাছে নিয়ে যাচ্ছি। দয়া করো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ الْكَلَاعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَوْمَئِذٍ عَلَى ‏ ‏الْجَدْعَاءِ ‏ ‏وَاضِعٌ رِجْلَيْهِ فِي ‏ ‏الْغَرْزِ ‏ ‏يَتَطَاوَلُ يُسْمِعُ النَّاسَ فَقَالَ بِأَعْلَى صَوْتِهِ أَلَا تَسْمَعُونَ فَقَالَ رَجُلٌ مِنْ طَوَائِفِ النَّاسِ يَا رَسُولَ اللَّهِ مَاذَا تَعْهَدُ إِلَيْنَا قَالَ ‏ ‏اعْبَدُوا رَبَّكُمْ وَصَلُّوا خَمْسَكُمْ وَصُومُوا شَهْرَكُمْ وَأَطِيعُوا ذَا أَمْرِكُمْ تَدْخُلُوا جَنَّةَ رَبِّكُمْ فَقُلْتُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏مِثْلُ مَنْ أَنْتَ يَوْمَئِذٍ قَالَ أَنَا يَوْمَئِذٍ ابْنُ ثَلَاثِينَ سَنَةً أُزَاحِمُ الْبَعِيرَ أُزَحْزِحُهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21229,21229,"","আমরা আমার বাবার সাথে কথা বলেছিলাম আমি আমার ভালবাসার কথা বলতে পারি। সে আমাদের কাছে পৌঁছে দিয়েছিল যে সে ছিল তার হৃদয়ে একজন মানুষ এবং সে ছিল কাঠবিড়াল, অথবা তুমি সাদা এবং কালো। মুখ বন্ধ রাখো.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ‏} ‏قَالَ هُمْ ‏ ‏الْخَوَارِجُ ‏ ‏وَفِي قَوْلِهِ ‏ { ‏يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ‏} ‏قَالَ هُمْ ‏ ‏الْخَوَارِجُ ‏","","",""],[21230,21230,"","আমরা আমাদের বাবার সাথে কথা বলেছি আমরা যখন লর্ডকে বিয়ে করেছিলাম, ঈশ্বর তাকে এটা করতে বলেছেন আর সে তা করবে না। তুমি আমাকে আর দেখতে পাবে না। আমরা যা করি, তা হলো তারা তোমার পঞ্চম জনের কাছে এসে তোমার বিখ্যাত আর সম্পূর্ণ বিখ্যাত হয়ে উঠবে, তুমি তোমার ঈশ্বরের শেষকৃত্যে প্রবেশ করবে, আর হ্যাঁ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏حَجَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّةَ الْوَدَاعِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا فَقَامَ رَجُلٌ طَوِيلٌ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ فَمَا الَّذِي نَفْعَلُ فَقَالَ ‏ ‏اعْبُدُوا رَبَّكُمْ وَصَلُّوا خَمْسَكُمْ وَصُومُوا شَهْرَكُمْ وَحُجُّوا بَيْتَكُمْ وَأَدُّوا زَكَاتَكُمْ طَيِّبَةً بِهَا أَنْفُسُكُمْ تَدْخُلُوا جَنَّةَ رَبِّكُمْ عَزَّ وَجَلَّ ‏","","",""],[21231,21231,"","বাবা মারা যাওয়ার পর আমি প্রথমে বাবাকে আশীর্বাদ করার জন্য এবং মাকে দেখার জন্য আমার মাকে বলি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ بْنُ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا نَبِيَّ اللَّهِ مَا كَانَ أَوَّلُ بَدْءِ أَمْرِكَ قَالَ ‏ ‏دَعْوَةُ أَبِي ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبُشْرَى ‏ ‏عِيسَى ‏ ‏وَرَأَتْ أُمِّي أَنَّهُ يَخْرُجُ مِنْهَا نُورٌ أَضَاءَتْ مِنْهَا قُصُورُ ‏ ‏الشَّامِ ‏","","",""],[21232,21232,"","আমরা আমার বাবার সাথে কথা বলেছি ঈশ্বর তাকে পেতে, তাকে মৃত্যুর পর মৃত আত্মাদের আত্মার মরণের জন্য উদ্ধার করা হবে আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার বিরুদ্ধে আকর্ষণ করে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجٌ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِ عَوَامِرِ الْبُيُوتِ إِلَّا مِنْ ذِي الطُّفْيَتَيْنِ وَالْأَبْتَرِ فَإِنَّهُمَا ‏ ‏يُكْمِهَانِ الْأَبْصَارَ وَتَخْدِجُ مِنْهُنَّ النِّسَاءُ ‏","","",""],[21233,21233,"","ঈশ্বর প্রথম বার বলেছিলেন, “ঈশ্বর আমাদের পক্ষে আছেন, ” তারা প্রথমে বলেছিল । দ্বিতীয়টি বলছে, \"দ্বিতীয়টি ঈশ্বর বলেছেন, আল্লাহ এটা করেছেন এবং হবেন সেই ব্যক্তি যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি । যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে ব ্ যক ্ তি হবে নিরাপদ , সে-ই হবে ক ্ ষমতার লোক , আর সে হবে একজন যে ব ্ যক ্ তি । রাজা যিনি রাজা হবেন, তিনি হবেন রাজা । \"যে রাজা আমার হাতে তোমার সাথে বিশ্বাসঘাতকতা করেছে এবং শপথ করেছে সে","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجٌ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ قَالُوا يَا رَسُولَ اللَّهِ وَعَلَى الثَّانِي قَالَ إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ قَالُوا يَا رَسُولَ اللَّهِ وَعَلَى الثَّانِي قَالَ وَعَلَى الثَّانِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ وَحَاذُوا بَيْنَ مَنَاكِبِكُمْ وَلِينُوا فِي أَيْدِي إِخْوَانِكُمْ وَسُدُّوا الْخَلَلَ فَإِنَّ الشَّيْطَانَ يَدْخُلُ بَيْنَكُمْ بِمَنْزِلَةِ الْحَذَفِ ‏ ‏يَعْنِي أَوْلَادَ الضَّأْنِ الصِّغَارَ ‏","","",""],[21234,21234,"","আমরা বাবা - মায়ের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجِيفُوا أَبْوَابَكُمْ وَأَكْفِئُوا آنِيَتَكُمْ ‏ ‏وَأَوْكِئُوا أَسْقِيَتَكُمْ وَأَطْفِئُوا سُرُجَكُمْ فَإِنَّهُ لَنْ يُؤْذَنَ لَهُمْ بِالتَّسَوُّرِ عَلَيْكُمْ ‏","","",""],[21235,21235,"","আমরা বাবার কথা বলেছিলাম যে আমার বাবা একবার শাসন করার চেষ্টা করেছেন বলে, ঈশ্বরের নাম শুনেছি সে আমাকে বলল যে সে আমাকে বলছে সে আমাকে বলছে. তুমি বল তুমি বল. নিজের জন্য খারাপ আর তুমি দোষ দাও না, শুধু হাত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْتُ أَبِي غَيْرَ مَرَّةٍ يَقُولُ وَحِدْثنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏إِنَّكَ إِنْ تَبْذُلْ الْخَيْرَ خَيْرٌ لَكَ وَإِنْ تُمْسِكْهُ شَرٌّ لَكَ وَلَا تُلَامُ عَلَى الْكَفَافِ وَابْدَأْ بِمَنْ تَعُولُ وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[21236,21236,"","আমরা কথা বলেছিলাম, নোয়া কিভাবে ভয় পেয়েছিল যে আমরা জানি বাবা বলেছে যে আমি ঈশ্বর ঈশ্বরের কাছে এসেছি আর তিনি ঈশ্বরের কাছে এসেছেন। আমি ইতিমধ্যে এটা করেছি যে তিনি করেছেন, ঈশ্বর লর্ড তার জন্য প্রার্থনা করেছেন এবং আমি তার মুখে ফিরে আসবো। প্রার্থনা হচ্ছে ঈশ্বরের কাছে প্রার্থনা করা, তার প্রার্থনা করা, তার কাছে আত্মসমর্পণ করা হবে এবং তাকে বরখাস্ত করা হবে যদি সে তার মৃত্যু লিখিত হয়। শিকার নিশ্চয়ই তার আলোচনায় হতে হবে, আমি লর্ড ঈশ্বরের ইচ্ছার সাথে থাকব এবং মানুষ তাকে অনুসরণ করবে। ঈশ্বর, আমি কি এত ভদ্র ছিলাম যে, ঈশ্বর... তিনি বলেছিলেন যে বধিররা তার কথাবার্তার সময় ব্যয় করেছিল । ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏وَقَالَ ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏أَتَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ قَالَ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ عَادَ فَقَالَ لَهُ مَرَّةً أُخْرَى ثُمَّ أُقِيمَتْ الصَّلَاةُ فَصَلَّى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ انْصَرَفَ قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏فَاتَّبَعَهُ الرَّجُلُ قَالَ وَتَبِعْتُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏فَانْصَرَفْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالرَّجُلُ يَتْبَعُهُ لِأَعْلَمَ مَا يَقُولُ لَهُ قَالَ فَقَالَ لَهُ الرَّجُلُ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ قَالَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ قَدْ تَوَضَّأْتَ قَبْلَ أَنْ تَخْرُجَ مِنْ مَنْزِلِكَ فَأَحْسَنْتَ الْوُضُوءَ ثُمَّ صَلَّيْتَ مَعَنَا قَالَ بَلَى قَالَ فَإِنَّ اللَّهَ قَدْ غَفَرَ لَكَ حَدَّكَ ‏ ‏أَوْ ذَنْبَكَ شَكَّ فِيهِ ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ فَانْصَرَفْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّبَعَهُ الرَّجُلُ ‏","","",""],[21237,21237,"","আমরা একটা ভাল কাঠের ওপর নজর রাখার মাধ্যমে আমার সর্বোত্তম মঙ্গলের কথা বলেছিলাম । তারপর তার ভাগ্য ব্যর্থ হল. তার মা বলেছিলেন যে, তিনি তাকে বড় করেছেন এবং পরে তিনি চলে যান ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ قَامَ إِلَى وَضُوئِهِ يُرِيدُ الصَّلَاةَ ثُمَّ غَسَلَ كَفَّيْهِ نَزَلَتْ خَطِيئَتُهُ مِنْ كَفَّيْهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا مَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ نَزَلَتْ خَطِيئَتُهُ مِنْ لِسَانِهِ وَشَفَتَيْهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا غَسَلَ وَجْهَهُ نَزَلَتْ خَطِيئَتُهُ مِنْ سَمْعِهِ وَبَصَرِهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا غَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ وَرِجْلَيْهِ إِلَى الْكَعْبَيْنِ سَلِمَ مِنْ كُلِّ ذَنْبٍ هُوَ لَهُ وَمِنْ كُلِّ خَطِيئَةٍ كَهَيْئَتِهِ يَوْمَ وَلَدَتْهُ أُمُّهُ قَالَ فَإِذَا قَامَ إِلَى الصَّلَاةِ رَفَعَ اللَّهُ بِهَا دَرَجَتَهُ وَإِنْ قَعَدَ قَعَدَ سَالِمًا ‏","","",""],[21238,21238,"","আমি বাবার সঙ্গে তার মায়ের কথা বলেছিলাম । বাবা, তুমি ভিড় থেকে বের হয়ে আসার পর আসতে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكٌ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقْعُدُ الْمَلَائِكَةُ يَوْمَ الْجُمُعَةِ عَلَى أَبْوَابِ الْمَسْجِدِ مَعَهُمْ الصُّحُفُ يَكْتُبُونَ النَّاسَ فَإِذَا خَرَجَ الْإِمَامُ طُوِيَتْ الصُّحُفُ قُلْتُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏لَيْسَ لِمَنْ جَاءَ بَعْدَ خُرُوجِ الْإِمَامِ جُمُعَةٌ قَالَ بَلَى وَلَكِنْ لَيْسَ مِمَّنْ يُكْتَبُ فِي الصُّحُفِ ‏","","",""],[21239,21239,"","আমরা এটা জেনে খুশি হয়েছি যে, ঈশ্বরের সামনে আমরা কথা বলেছি, ঈশ্বরের প্রেমে বাস করতে যাচ্ছি। আমি আমার বাবা তার ইচ্ছার চেয়েও বেশি কিছু করতে চাচ্ছি এবং সে যা এসেছে তা নিয়ে বলবে। আমি হয়তো আমার নিয়তিকে রক্ষা করার জন্য ভয় পেতাম ।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَطُّ إِلَّا أَمَرَنِي بِالسِّوَاكِ لَقَدْ خَشِيتُ أَنْ أُحْفِيَ مُقَدَّمَ ‏ ‏فِيَّ ‏","","",""],[21240,21240,"","আমরা একটা নির্দিষ্ট ছেলের কথা বলেছি যে আমার বাবার জন্য খুশি হবে। ঈশ্বর তার কাছে প্রার্থনা করেছেন আর ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করেছেন। আমি আমার মুখের উপর শক্ত হয়ে বলতে চাই যে আল্লাহ জিতেছে আর আমাকে ভালবাসেন না। তিনি হয়তো এমন একটা মোটেলে বলতে পারেন যে সে তিক্ত হয়ে পড়বে আর পরে গ্যাব্রিয়েলের কাছে শপথ নেয়াটা হবে। আমার বাবা - মা আমাদের বলেছিলেন যে, আমার প্রতিবেশীর মধ্যে কিছুটা স্নায়ু রয়েছে । ছেলেটা এটা তার মত করে নিতে পারতো।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمِقَةَ مِنْ اللَّهِ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏هِيَ الْمَحَبَّةُ ‏ ‏وَأُلْقِيَتْ مِنْ السَّمَاءِ فَإِذَا أَحَبَّ اللَّهُ عَبْدًا قَالَ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَمِقُ ‏ ‏يَعْنِي يُحِبُّ ‏ ‏فُلَانًا فَأَحِبُّوهُ ‏ ‏أَرَى ‏ ‏شَرِيكًا ‏ ‏قَدْ قَالَ فَيُنْزِلُ لَهُ الْمَحَبَّةَ فِي الْأَرْضِ ‏ ‏وَإِذَا أَبْغَضَ عَبْدًا قَالَ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ قَالَ فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏إِنَّ رَبَّكُمْ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ قَالَ ‏ ‏أَرَى ‏ ‏شَرِيكًا ‏ ‏قَدْ قَالَ ‏ ‏فَيَجْرِي لَهُ الْبُغْضُ فِي الْأَرْضِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[21241,21241,"","আমি আমার বাবাকে রক্ষা করার কথা বলেছিলাম। আমার বাবাকে রক্ষা করা হয়েছে। সে একটা ছেলে যে একটা স্বপ্নের ছেলে ছিল। সে আমাকে মেরে ফেলবে যদি আমি বলি \"হে\" নাকি আমি তাকে মেরে ফেলব। তিনি তার লোকেদের সঙ্গে কথা বলেছিলেন, তার মন্দতাকে তিনি ভুলে গিয়েছিলেন, তার মন্দতাকে তিনি ভুলে গিয়েছিলেন, যিনি তার প্রাণ হারিয়ে ফেলেছিলেন । আর ঈশ্বর হয়তো আমার ভবিষ্যদ্‌বাণী থেকে তাকে শুনতে পারেন আর ঈশ্বর তার কাছে প্রার্থনা করেছেন যেন তিনি খুশি হন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُسْلِمٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏وَهُوَ ‏ ‏يَتَفَلَّى فِي الْمَسْجِدِ وَيَدْفِنُ الْقَمْلَ فِي الْحَصَى فَقُلْتُ لَهُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏إِنَّ رَجُلًا حَدَّثَنِي عَنْكَ أَنَّكَ قُلْتَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ فَغَسَلَ يَدَيْهِ وَوَجْهَهُ وَمَسَحَ عَلَى رَأْسِهِ وَأُذُنَيْهِ ثُمَّ قَامَ إِلَى الصَّلَاةِ الْمَفْرُوضَةِ غَفَرَ اللَّهُ لَهُ فِي ذَلِكَ الْيَوْمِ مَا مَشَتْ إِلَيْهِ رِجْلُهُ وَقَبَضَتْ عَلَيْهِ يَدَاهُ وَسَمِعَتْ إِلَيْهِ أُذُنَاهُ وَنَظَرَتْ إِلَيْهِ عَيْنَاهُ وَحَدَّثَ بِهِ نَفْسَهُ مِنْ سُوءٍ قَالَ وَاللَّهِ لَقَدْ سَمِعْتُهُ مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَا ‏ ‏أُحْصِيهِ ‏","","",""],[21242,21242,"","আমরা বাবার জন্য আপনার বাবাকে খোঁজার চেয়ে বেশি প্রশংসা করেছি। তিনি ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং আমার বাবা ও তার প্রার্থনা করেছিলেন। আমি একটা উলকির জন্য প্রার্থনা করছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏دُبُرِ ‏ ‏صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏غَيْرُهُ فِي إِثْرِ صَلَاةٍ ‏ ‏لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي عِلِّيِّينَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قُلْتُ لِأَبِي مِنْ أَيْنَ سَمِعَ ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏قَالَ كَانَ أَصْلُهُ شَامِيًّا سَمِعَ مِنْهُ ‏ ‏بِالشَّامِ ‏","","",""],[21243,21243,"","আমরা একটা পাগল বা অন্যকিছুর কথা বলেছি, আমার বাবা ভালো লর্ড হয়েছে আর অনেক মাংসের চার্জ দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ أَبُو غَسَّانَ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْحَصِينِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحُمَّى كِيرٌ مِنْ جَهَنَّمَ فَمَا أَصَابَ الْمُؤْمِنَ مِنْهَا كَانَ حَظَّهُ مِنْ جَهَنَّمَ ‏","","",""],[21244,21244,"","বাবা বড় মানুষ হয়ে থাকলে আমরা খুশি হব বলে কথা বললাম, এমনকি যখন সে জন্ম নেয় তখনও আমরা জয়ী হতে পারব। আমার বাবা বলেছিলেন যদি আমি ভাববাদীর কথা শুনি না, ঈশ্বরের একটা আছে ঈশ্বর ভাল, সে কখনো বলেনি যে লোকটা এটা কীভাবে শোনে আর চলে যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏لَوْ لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا سَبْعًا ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏إِلَّا سَبْعَ مِرَارٍ ‏ ‏مَا حَدَّثَ بِهِ قَالَ ‏ ‏إِذَا تَوَضَّأَ الرَّجُلُ كَمَا أُمِرَ ذَهَبَ الْإِثْمُ مِنْ سَمْعِهِ وَبَصَرِهِ وَيَدَيْهِ وَرِجْلَيْهِ ‏","","",""],[21245,21245,"","আমরা দুজন সালমন তৈরি করেছি, যা খোদাকে ক্লান্ত করে দিয়েছে কিন্তু আমার বাবা শুনতে যাচ্ছে। আমি বলেছি, ঈশ্বর আমাকে বলছেন যে তিনি আমাকে পাগল করে দিচ্ছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏سَمِعَ ‏ ‏أَبَا نَصْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ قَالَ ‏ ‏عَلَيْكَ بِالصَّوْمِ فَإِنَّهُ لَا عِدْلَ لَهُ ‏ ‏أَوْ قَالَ لَا مِثْلَ لَهُ ‏","","",""],[21246,21246,"","আমরা বধিরদের কথা বলেছি এবং আমাদের প্রথম সাক্ষাৎ হওয়ার পর এটা করার কথা দিয়েছিলাম। ঈশ্বর তাকে আমার আদেশ দিয়েছেন, সে আমাকে আমার কাছে পাঠিয়ে দিতে এবং আমার দৃষ্টি থেকে বিক্রি করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏طُوبَى ‏ ‏لِمَنْ رَآنِي ‏ ‏وَطُوبَى ‏ ‏سَبْعَ مِرَارٍ لِمَنْ آمَنْ بِي وَلَمْ يَرَنِي ‏","","",""],[21247,21247,"","তোমার খেলার ছেলে যখন তোমাকে দেখে আমরা তাদের সাথে কথা বলেছি আমি আমার বাবার থেকে বরং ঈশ্বরের উপাসনা করবো, সে তার সবচেয়ে ভালো কিছু বলবে মানুষ না হলে সে তার আঙ্গুল কামড়াবে.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ هُوَ ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَنْظُرُ إِلَى مَحَاسِنِ امْرَأَةٍ أَوَّلَ مَرَّةٍ ثُمَّ يَغُضُّ بَصَرَهُ إِلَّا أَحْدَثَ اللَّهُ لَهُ عِبَادَةً يَجِدُ حَلَاوَتَهَا ‏","","",""],[21248,21248,"","আমরা একটি সুখী দম্পতিকে লেখার চেষ্টা করেছি, যে কিনা আমাদের এই অনুষ্ঠানের পরিবর্তন করেছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَرْفَعُ الْحَدِيثَ قَالَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21249,21249,"","বাবা বলেছিলেন যে, ঈশ্বর তার জন্য প্রার্থনা করবেন এবং সেই দাসীকে উদ্ধার করবেন, যিনি গায়ককে বিক্রি করবেন না এবং তার মাথা ভেঙে ফেলতে পারবেন না । তাদের সাথে ব্যবসা করে, তারপর যুদ্ধ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الْمُغَنِّيَاتِ وَلَا تَشْتَرُوهُنَّ وَلَا تُعَلِّمُوهُنَّ وَلَا خَيْرَ فِي تِجَارَةٍ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ ‏","","",""],[21250,21250,"","আমরা এক বছর ধরে আমার বাবার দোহাই দিয়ে বিখ্যাত ভালোবাসার সাথে কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করেছে এবং আমি যা বলেছি তাতে তার সাথে কথা বলেছি না বলে তার কাছে আত্মসমর্পণ করতে হবে। এবং আমি তাকে ক্ষমা করে দিয়েছি। তার দৃষ্টি আর পা.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏لَوْ لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا سَبْعَ مِرَارٍ مَا حَدَّثْتُ بِهِ قَالَ ‏ ‏إِذَا تَوَضَّأَ الرَّجُلُ كَمَا أُمِرَ ذَهَبَ الْإِثْمُ مِنْ سَمْعِهِ وَبَصَرِهِ وَيَدَيْهِ وَرِجْلَيْهِ ‏","","",""],[21251,21251,"","আমরা হামাদের কথা বলেছি এক মাসের জন্য যে এক ছেলের জন্ম দিয়েছে তার ছেলে ভালোবাসার জন্য, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং তার মুখটা হারিয়ে গেছে। আমার বাবার কথা অথবা ঈশ্বরের অনুগ্রহের কথা আমি খুব ভালভাবে জানি, তার কাছে আছে এবং তাকে মরতে দেয়া হবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَقَالَ الْأُذُنَانِ مِنْ الرَّأْسِ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏فَلَا أَدْرِي مِنْ قَوْلِ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَوْ مِنْ قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْمُوقَيْنِ ‏","","",""],[21252,21252,"","আমরা শুধু কথা বলেছি আমরা কি বলবো তা শুনতে সক্ষম হয়েছি। ঈশ্বরের কাছে প্রার্থনা করে সে ১০ বছর বয়সী একজন লোককে উদ্ধার করবে। তারা চলে যাবে। আল্লাহ বলে আমি চলে যাবো, আল্লাহ তাকে জিজ্ঞেস করতে হবে আর তুমি প্রার্থনা করবে আর কথা বলবে না। তারা ভয় পায় না আর তার ভয়ে শব্দ ব্যবহার করে। ঈশ্বর আমাকে লিখতে এবং বলতে হবে, আমাকে অবশ্যই লিখতে হবে। ছেলেটা তার নিজের, তারা তোমাকে রক্ষা করবে আর আমাকে লিখতে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ بْنِ زَبْرٍ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مَشْيَخَةٍ مِنْ ‏ ‏الْأَنْصَارٍ ‏ ‏بِيضٌ لِحَاهُمْ فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏حَمِّرُوا وَصَفِّرُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَتَسَرْوَلَونَ وَلَا ‏ ‏يَأْتَزِرُونَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَرْوَلُوا ‏ ‏وَائْتَزِرُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَتَخَفَّفُونَ وَلَا يَنْتَعِلُونَ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَخَفَّفُوا وَانْتَعِلُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَقُصُّونَ ‏ ‏عَثَانِينَهُمْ وَيُوَفِّرُونَ سِبَالَهُمْ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُصُّوا سِبَالَكُمْ وَوَفِّرُوا ‏ ‏عَثَانِينَكُمْ وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏","","",""],[21253,21253,"","আমরা আপনার ছেলেকে নিয়ে কথা বলেছি যখন আমি যা চাই তা নিয়ে কথা বলি। সে কখনো তার প্রতি অনুভূতি প্রকাশ করেনি, তারাই তাকে গুলি করার সিদ্ধান্ত নিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَسَحَ رَأْسَ يَتِيمٍ أَوْ يَتِيمَةٍ لَمْ يَمْسَحْهُ إِلَّا لِلَّهِ كَانَ لَهُ بِكُلِّ شَعْرَةٍ مَرَّتْ عَلَيْهَا يَدُهُ حَسَنَاتٌ وَمَنْ أَحْسَنَ إِلَى يَتِيمَةٍ أَوْ يَتِيمٍ عِنْدَهُ كُنْتُ أَنَا وَهُوَ فِي الْجَنَّةِ كَهَاتَيْنِ وَقَرَنَ بَيْنَ أُصْبُعَيْهِ ‏","","",""],[21254,21254,"","আমরা কথা বলেছিলাম যে ঈশ্বর আমাদের বলেছেন যে, এমন এক ছেলের কথা যাকে হতে হবে যে তার নিজেরই হতে হবে। যে ব ্ যক ্ তি নিজেকে স ্ বীকার করে , তার জন ্ যে রয়েছে সহা-যারা আছে । রাজা হোন, রাজা তাঁর কাছে প্রার্থনা করেছিলেন এবং তাকে তাঁর মুখ থেকে উদ্ধার করেছিলেন এবং তার বাহুর জল থেকে রক্ষা করেছিলেন । তার উচ্চ পদস্থ এবং তার ইচ্ছার দ্বারা পরাজিত হবে। \"তারা কখনোই তাদের গ্রাস করতে পারবে না এবং বলে দেবে না যে আল্লাহ এবং চুপ থাকুন।\"","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ بُسْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَيُسْقَى مِنْ مَاءٍ صَدِيدٍ ‏ ‏يَتَجَرَّعُهُ ‏ } ‏قَالَ يُقَرَّبُ إِلَيْهِ فَيَتَكَرَّهُهُ فَإِذَا دَنَا مِنْهُ شُوِيَ وَجْهُهُ وَوَقَعَتْ فَرْوَةُ رَأْسِهِ وَإِذَا شَرِبَهُ قَطَّعَ أَمْعَاءَهُ حَتَّى خَرَجَ مِنْ ‏ ‏دُبُرِهِ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَسُقُوا مَاءً حَمِيمًا فَقَطَّعَ أَمْعَاءَهُمْ ‏} ‏وَيَقُولُ اللَّهُ ‏ { ‏وَإِنْ يَسْتَغِيثُوا يُغَاثُوا بِمَاءٍ كَالْمُهْلِ ‏ ‏يَشْوِي الْوُجُوهَ بِئْسَ الشَّرَابُ ‏}","","",""],[21255,21255,"","বাবা আমাকে নিয়ে কথা বলার চেষ্টা করে আমি একটা কাজ করার চেষ্টা করেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি ঈশ্বরের জন্য যথেষ্ট হবে তাই আমি নির্ধারণ করেছি যে আমি ইতোমধ্যে সিদ্ধান্ত নিয়েছি। আমি তাকে প্রস্তাব দেব, আর বলবো, আমি কখনোই ভালো থাকবো না। ঈশ্বর তাঁর জন্য প্রার্থনা করলেন এবং তাকে আত্মসমর্পণ করবেন, প্রভু, যদি আমি কখনও এমন হতে পারতাম, আমি তা করতাম, সে বলল। আমরা যখন প্রার্থনা করেছিলাম, তখন আমরা বলেছিলাম, ঈশ্বর যদি আপনাকে কিছু করতে বলেন, তাহলে আমরা চলে যাব ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ شَدَّادٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ ثُمَّ قَالَ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ ثُمَّ قَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ وَأُقِيمَتْ الصَّلَاةُ فَلَمَّا سَلَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَقَالَ ‏ ‏هَلْ تَوَضَّأْتَ حِينَ أَقْبَلْتَ قَالَ نَعَمْ فَقَالَ هَلْ صَلَّيْتَ مَعَنَا حِينَ صَلَّيْنَا قَالَ نَعَمْ قَالَ اذْهَبْ فَإِنَّ اللَّهَ قَدْ عَفَا عَنْكَ ‏","","",""],[21256,21256,"","আমরা কথা বলেছি, কিভাবে আমি আমার মন পরিবর্তন করেছি ঈশ্বরের চেয়ে বেশি বিচার করার জন্য। আমি এটা প্রার্থনা করবো আর সে যখন গরম স্থানে চলে যাবে, তখন সে এটা দিয়ে যাবে। এটা করে, ঈশ্বর বলে, তার কাছে প্রার্থনা করে এবং যদি আপনি জানেন যে তিনি কি করেছেন, তিনি জানেন না কি, আপনি কখনো তার জন্য ঈশ্বরের কাছে প্রার্থনা করতে পারেন নি এবং তাকে উদ্ধার করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا هُوَ يَمْشِي فِي شِدَّةِ حَرٍّ انْقَطَعَ شِسْعُ نَعْلِهِ فَجَاءَهُ رَجُلٌ بِشِسْعٍ فَوَضَعَهُ فِي نَعْلِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُ مَا حَمَلْتَ عَلَيْهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَعْلُ مَا حَمَلْتَ عَلَيْهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21257,21257,"","তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যেন তিনি গৌরবের গৌরব প্রদান করেন এবং তিনি মনে করতেন যে তিনি হবেন । আপনি দোষটা এমন জায়গায় যেতে না বলেছিলেন, যেখানে আমি যেতে পারব বলে দোষ দিয়েছিলেন । আমি বলেছি, আমি তোমাকে অপরাধ দমন করতে নিষেধ করি নি, কিন্তু আমি বলছি, এটা বলার জন্য যে, তুমি আমাকে তার মুখ বন্ধ করতে বলছো, ঈশ্বর। তিনি আপনার কাছে ঈশ্বরের কাছে ক্ষমা চেয়েছিলেন, যাতে তিনি যা বলেন তা ভাল তা বিশ্বকে দেখাতে পারেন । \"ঈশ্বর, আমি যা বলতে চাই তা হলো, ভাগ্যের জন্য গোপন।\" ঈশ্বর আমাদের নাম রাখতে হবে না। আমি বলছি, এটা জীবিত নয়। আমি বলছি, এটা কোন কথা। আমি বলছি, আমি বলছি, আমি বলছি, আমি বলছি, তোমার রক্ত তাকে খুঁজতে বাধ্য হয়েছিল আর আল্লাহ্‌কে বলে আমি বলবো, তিনি কি আমাকে এটা করতে বলেছিলেন? তিনি আমাকে তাঁর প্রভুর নাম শিখিয়েছেন, তারপর তিনি তা নিয়ে নিয়েছেন। তার আনন্দ আর বলেছে যে তার বলার আগে তাকে বলা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ جَالِسًا وَكَانُوا يَظُنُّونَ أَنَّهُ يَنْزِلُ عَلَيْهِ فَأَقْصَرُوا عَنْهُ حَتَّى جَاءَ ‏ ‏أَبُو ذَرٍّ ‏ ‏فَاقْتَحَمَ فَأَتَى فَجَلَسَ إِلَيْهِ فَأَقْبَلَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏هَلْ صَلَّيْتَ الْيَوْمَ قَالَ لَا قَالَ قُمْ فَصَلِّ فَلَمَّا صَلَّى أَرْبَعَ رَكَعَاتٍ الضُّحَى أَقْبَلَ عَلَيْهِ فَقَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏تَعَوَّذْ مِنْ شَرِّ شَيَاطِينِ الْجِنِّ وَالْإِنْسِ قَالَ يَا نَبِيَّ اللَّهِ وَهَلْ لَلْإِنْسِ شَيَاطِينٌ قَالَ نَعَمْ شَيَاطِينُ الْإِنْسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا ثُمَّ قَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏أَلَا أُعَلِّمُكَ مِنْ كَنْزِ الْجَنَّةِ قَالَ بَلَى جَعَلَنِي اللَّهُ فِدَاءَكَ قَالَ قُلْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ فَقُلْتُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ ثُمَّ سَكَتَ عَنِّي فَاسْتَبْطَأْتُ كَلَامَهُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ إِنَّا كُنَّا أَهْلَ جَاهِلِيَّةٍ وَعَبَدَةَ أَوْثَانٍ فَبَعَثَكَ اللَّهُ رَحْمَةً لِلْعَالَمِينَ أَرَأَيْتَ الصَّلَاةَ مَاذَا هِيَ قَالَ خَيْرٌ مَوْضُوعٌ مَنْ شَاءَ اسْتَقَلَّ وَمَنْ شَاءَ اسْتَكْثَرَ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَرَأَيْتَ الصِّيَامَ مَاذَا هُوَ قَالَ فَرْضٌ مُجْزِئٌ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَرَأَيْتَ ‏ ‏الصَّدَقَةَ ‏ ‏مَاذَا هِيَ قَالَ أَضْعَافٌ مُضَاعَفَةٌ وَعِنْدَ اللَّهِ الْمَزِيدُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ سِرٌّ إِلَى فَقِيرٍ ‏ ‏وَجُهْدٌ ‏ ‏مِنْ مُقِلٍّ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَيُّمَا نَزَلَ عَلَيْكَ أَعْظَمُ قَالَ ‏ { ‏اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ‏} ‏آيَةُ الْكُرْسِيِّ ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَيُّ الشُّهَدَاءِ أَفْضَلُ قَالَ مَنْ سُفِكَ دَمُهُ وَعُقِرَ جَوَادُهُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ الرِّقَابِ أَفْضَلُ قَالَ أَغْلَاهَا ثَمَنًا وَأَنْفَسُهَا عِنْدَ أَهْلِهَا قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ الْأَنْبِيَاءِ كَانَ أَوَّلَ قَالَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَوَنَبِيٌّ كَانَ ‏ ‏آدَمُ ‏ ‏قَالَ نَعَمْ نَبِيٌّ مُكَلَّمٌ خَلَقَهُ ‏ ‏اللَّهُ بِيَدِهِ ثُمَّ نَفَخَ فِيهِ رُوحَهُ ثُمَّ قَالَ لَهُ يَا ‏ ‏آدَمُ ‏ ‏قُبْلًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ كَمْ وَفَّى عِدَّةُ الْأَنْبِيَاءِ قَالَ مِائَةُ أَلْفٍ وَأَرْبَعَةٌ وَعِشْرُونَ أَلْفًا الرُّسُلُ مِنْ ذَلِكَ ثَلَاثُ مِائَةٍ وَخَمْسَةَ عَشَرَ جَمًّا غَفِيرًا ‏","","",""],[21258,21258,"","আমি এই বিষয়ে আরও বেশি জানতে চাই যে, ঈশ্বর হলেন ঈশ্বর । ঈশ্বর হলেন ঈশ্বর ঈশ্বর","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ وَهُوَ يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَقَالَ ‏ ‏أَوْجَبَ هَذَا ‏ ‏أَيْ وَجَبَتْ لِهَذَا ‏ ‏الْجَنَّةُ ‏","","",""],[21259,21259,"","আমার সবচেয়ে ভাল বিচার করার সময় আমার মন পরিবর্তন হওয়ার কথা ছিল । বিজ্ঞানের আগে বিজ্ঞান থেকে নেয়া হয়েছে। আমি একটা উপকার চাই। আমি আশা করি আপনি খারাপ কিছু অনুভব করবেন না। আপনি মনে করেন, তিনি এবং ঈশ্বরও একজন তার ছেলে নির্ভীকভাবে ঈশ্বরের কাছে আমাদের কাছে প্রার্থনা করেছিল । আমরা যা শিখেছি এবং আমাদের জীবন হারিয়েছে তা জানতে পেরেছি। সে জানতে পেরেছে যে তার উপস্থিতি একটা পাথর। সে তোমার মাকে মারার জন্য বলেছে, তারা একটা সমস্যায় পড়ে আছে। তাদের মধ্যে যে আবেগ আসে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ ‏ ‏مَوْلَى ‏ ‏بَنِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ فِي حَجَّةِ الْوَدَاعِ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَوْمَئِذٍ مُرْدِفٌ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏عَلَى جَمَلٍ ‏ ‏آدَمَ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏خُذُوا مِنْ الْعِلْمِ قَبْلَ أَنْ يُقْبَضَ الْعِلْمُ وَقَبْلَ أَنْ يُرْفَعَ الْعِلْمُ وَقَدْ كَانَ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِنْ تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ عَفَا اللَّهُ عَنْهَا وَاللَّهُ غَفُورٌ حَلِيمٌ ‏} ‏قَالَ فَكُنَّا قَدْ كَرِهْنَا كَثِيرًا مِنْ مَسْأَلَتِهِ وَاتَّقَيْنَا ذَاكَ حِينَ أَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْنَا أَعْرَابِيًّا فَرَشَوْنَاهُ بِرِدَاءٍ قَالَ فَاعْتَمَّ بِهِ حَتَّى رَأَيْتُ حَاشِيَةَ الْبُرْدِ خَارِجَةً مِنْ حَاجِبِهِ الْأَيْمَنِ قَالَ ثُمَّ قُلْنَا لَهُ سَلْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ يَا نَبِيَّ اللَّهِ كَيْفَ يُرْفَعُ الْعِلْمُ مِنَّا وَبَيْنَ أَظْهُرِنَا الْمَصَاحِفُ وَقَدْ تَعَلَّمْنَا مَا فِيهَا وَعَلَّمْنَا نِسَاءَنَا وَذَرَارِيَّنَا وَخَدَمَنَا قَالَ فَرَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ وَقَدْ عَلَتْ وَجْهَهُ حُمْرَةٌ مِنْ الْغَضَبِ قَالَ فَقَالَ أَيْ ثَكِلَتْكَ أُمُّكَ هَذِهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏بَيْنَ أَظْهُرِهِمْ الْمَصَاحِفُ لَمْ يُصْبِحُوا يَتَعَلَّقُوا بِحَرْفٍ مِمَّا جَاءَتْهُمْ بِهِ أَنْبِيَاؤُهُمْ أَلَا وَإِنَّ مِنْ ذَهَابِ الْعِلْمِ أَنْ يَذْهَبَ حَمَلَتُهُ ثَلَاثَ مِرَارٍ ‏","","",""],[21260,21260,"","আমরা তার লর্ডশিপের সঙ্গে বাইরে গিয়েছিলাম, তার কাছে প্রার্থনা করেছিলাম এবং তার গোপন রহস্য থেকে গোপন তথ্য সংগ্রহ করেছিলাম, তিনি বলেছিলেন । সে তার নিজের লোক ছিল, সে তার সাথে কথা বলেছিল ঐ অন্ধকারে শুয়ে ছিল আর ভয় পেয়ে সে ঈশ্বরের কাছে প্রার্থনা করবে যে সে এটা করেছে আর আমি মনে করতে পারি যে আপনাকে এটা করার অনুমতি আছে। ঈশ্বর আমাকে পানি থেকে মেরে আমাকে খুন করেছে আর আমাকে খুন করেছে এই কারণে যে আমি বাবা হওয়ার ভয়ে দুঃখিত। ঈশ্বর আদেশ দিয়েছেন আর আমি তাই করবো। এই যাদুমন্ত্রের সাথে না, কাল তার হাত দিয়ে বা ঈশ্বরের নামে জয়ের জন্য... ...আর একমাত্র উপায় হল আমি এটা ধ্বংস করতে পারব.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏مِنْ ‏ ‏سَرَايَاهُ ‏ ‏قَالَ فَمَرَّ رَجُلٌ بِغَارٍ فِيهِ شَيْءٌ مِنْ مَاءٍ قَالَ فَحَدَّثَ نَفْسَهُ بِأَنْ يُقِيمَ فِي ذَلِكَ الْغَارِ فَيَقُوتُهُ مَا كَانَ فِيهِ مِنْ مَاءٍ وَيُصِيبُ مَا حَوْلَهُ مِنْ الْبَقْلِ ‏ ‏وَيَتَخَلَّى مِنْ الدُّنْيَا ثُمَّ قَالَ لَوْ أَنِّي أَتَيْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَإِنْ أَذِنَ لِي فَعَلْتُ وَإِلَّا لَمْ أَفْعَلْ فَأَتَاهُ فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي مَرَرْتُ بِغَارٍ فِيهِ مَا يَقُوتُنِي مِنْ الْمَاءِ وَالْبَقْلِ فَحَدَّثَتْنِي نَفْسِي بِأَنْ أُقِيمَ فِيهِ ‏ ‏وَأَتَخَلَّى مِنْ الدُّنْيَا قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَمْ أُبْعَثْ بِالْيَهُودِيَّةِ وَلَا بِالنَّصْرَانِيَّةِ وَلَكِنِّي بُعِثْتُ بِالْحَنِيفِيَّةِ السَّمْحَةِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَغَدْوَةٌ أَوْ رَوْحَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا وَلَمُقَامُ أَحَدِكُمْ فِي الصَّفِّ خَيْرٌ مِنْ صَلَاتِهِ سِتِّينَ سَنَةً ‏","","",""],[21261,21261,"","আমার বাবা ঈশ্বরের কাছে বলা প্রতিজ্ঞার বিষয়ে কথা বলার পর, ঈশ্বর তাকে সেই দিনের জন্য উদ্ধার করেছেন । তিনি যখন সেই দলের সদস্যদের কথা শুনেছিলেন, তখন তিনি তার কথা শুনেছিলেন কিন্তু তার নিজের ভাষায় কেবল তিনিই কাজ করেছিলেন । দুই বার তারা এটা সমাহিত করে যখন তারা মারা গিয়েছিল। তুমি কাকে বলতে চাচ্ছ, প্রভু চলে যাচ্ছে। ঈশ্বর বলেও তাদের একজন হত। আর তারপর সে তার দুটো কবরকে বলে, আর আমি ভয় পেয়েছিলাম যে তারা বলবে, ঈশ্বর বলেছেন যদি তোমরা তোমাদের মুখ ভেঙ্গে ফেলতে না চাও বা তোমাদের উপাসনা করতে না চাও তাহলে... বিশ্বের নাম","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ شَدِيدِ الْحَرِّ نَحْوَ ‏ ‏بَقِيعِ الْغَرْقَدِ ‏ ‏قَالَ فَكَانَ النَّاسُ يَمْشُونَ خَلْفَهُ قَالَ فَلَمَّا سَمِعَ صَوْتَ النِّعَالِ وَقَرَ ذَلِكَ فِي نَفْسِهِ فَجَلَسَ حَتَّى قَدَّمَهُمْ أَمَامَهُ لِئَلَّا يَقَعَ فِي نَفْسِهِ شَيْءٌ مِنْ الْكِبْرِ فَلَمَّا مَرَّ ‏ ‏بِبَقِيعِ الْغَرْقَدِ ‏ ‏إِذَا بِقَبْرَيْنِ قَدْ دَفَنُوا فِيهِمَا رَجُلَيْنِ قَالَ فَوَقَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ دَفَنْتُمْ هَاهُنَا الْيَوْمَ قَالُوا يَا نَبِيَّ اللَّهِ فُلَانٌ وَفُلَانٌ قَالَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ الْآنَ وَيُفْتَنَانِ فِي قَبْرَيْهِمَا قَالُوا يَا رَسُولَ اللَّهِ فِيمَ ذَاكَ قَالَ أَمَّا أَحَدُهُمَا فَكَانَ لَا يَتَنَزَّهُ مِنْ الْبَوْلِ وَأَمَّا الْآخَرُ فَكَانَ يَمْشِي بِالنَّمِيمَةِ وَأَخَذَ جَرِيدَةً رَطْبَةً فَشَقَّهَا ثُمَّ جَعَلَهَا عَلَى الْقَبْرَيْنِ قَالُوا يَا نَبِيَّ اللَّهِ وَلِمَ فَعَلْتَ قَالَ لِيُخَفَّفَنَّ عَنْهُمَا قَالُوا يَا نَبِيَّ اللَّهِ وَحَتَّى مَتَى يُعَذِّبُهُمَا اللَّهُ قَالَ غَيْبٌ لَا يَعْلَمُهُ إِلَّا اللَّهُ قَالَ وَلَوْلَا تَمَزُّعُ قُلُوبِكُمْ أَوْ تَزَيُّدُكُمْ فِي الْحَدِيثِ لَسَمِعْتُمْ مَا أَسْمَعُ ‏","","",""],[21262,21262,"","আমরা কথা বলেছিলাম, কিভাবে আমি ঈশ্বরের থেকে ভালো হতে পারি সে আমাদের প্রভুর সেবায় বসে আছে, আর সে আমাদের নিয়ে এসেছে আর আমরা তোমার মুখে আটকে গেছি \"আমি প্রভুর কাছে মরে গেলাম, আমাকে লর্ডের কাছে যেতে হবে\" একবার তিনি বলেছিলেন, \"হে, তুমি তোমার অন্ত্যেষ্টিক্রিয়ায় আটকে থাকবে, তোমার বয়স বা তোমার নিজের চেয়ে ভালো,","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏جَلَسْنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَّرَنَا وَرَقَّقَنَا فَبَكَى ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏فَأَكْثَرَ الْبُكَاءَ فَقَالَ يَا لَيْتَنِي مِتُّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏سَعْدُ ‏ ‏أَعِنْدِي ‏ ‏تَتَمَنَّى الْمَوْتَ فَرَدَّدَ ذَلِكَ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ يَا ‏ ‏سَعْدُ ‏ ‏إِنْ كُنْتَ خُلِقْتَ لِلْجَنَّةِ فَمَا طَالَ عُمْرُكَ أَوْ حَسُنَ مِنْ عَمَلِكَ فَهُوَ خَيْرٌ لَكَ ‏","","",""],[21263,21263,"","আমরা কিভাবে জাদু করতে চেষ্টা করেছি সে সম্পর্কে কথা বলেছি। আমার বাবা-মা বলেছে, আমি আল্লাহ্‌র প্রার্থনা শুনেছি যে সে প্রতারণার অপরাধে আত্মসমর্পণ করবে। আর বেশ্যার কাছে গিয়ে তাকে খুঁজে বের করার চেষ্টা করো, মহামান্য প্রভু তার প্রাণের অভিশাপ দিয়েছেন, ঈশ্বর বলেছেন, আমি চাই ঈশ্বর আমাদের উদ্ধার করুক প্রভু ঈশ্বরের করুণা হোক। আমি কখনোই স্বপ্নে কথা বলি নি, আমার বাবা একটা ভবিষ্যদ্বাণী করেছেন, যা তার কাছে প্রার্থনা করেছে আর সিঁড়িকে রক্ষা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ بْنُ مُسْلِمٍ الْخَوْلَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خُطْبَتِهِ عَامَّ حَجَّةِ الْوَدَاعِ ‏ ‏إِنَّ اللَّهَ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ فَلَا وَصِيَّةَ لِوَارِثٍ وَالْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏وَحِسَابُهُمْ عَلَى اللَّهِ وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ انْتَمَى إِلَى غَيْرِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ التَّابِعَةُ إِلَى يَوْمِ الْقِيَامَةِ لَا تُنْفِقُ الْمَرْأَةُ شَيْئًا مِنْ بَيْتِهَا إِلَّا بِإِذْنِ زَوْجِهَا فَقِيلَ يَا رَسُولَ اللَّهِ وَلَا الطَّعَامَ قَالَ ذَلِكَ أَفْضَلُ أَمْوَالِنَا قَالَ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَارِيَةُ مُؤَدَّاةٌ وَالْمِنْحَةُ مَرْدُودَةٌ وَالدَّيْنَ مَقْضِيٌّ وَالزَّعِيمُ ‏ ‏غَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الزَّعِيمُ غَارِمٌ ‏","","",""],[21264,21264,"","আমরা সেই বুড়োর কথা বলেছিলাম যে তার কথা শুনতে চেয়েছিল, সে ঈশ্বরের রুটি দিতে চায়নি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ الْخَبَائِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ يَفْضُلُ عَنْ أَهْلِ بَيْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُبْزُ الشَّعِيرِ ‏","","",""],[21265,21265,"","আমরা হৃদয় পরিবর্তন সম্পর্কে কথা বলেছি, কিন্তু আমরা যখন বিশ্বের সেরাদের কথা বলছি, সে বলল ঈশ্বর তার কাছে প্রার্থনা করুক আর সে হবে আমি মানুষের আনন্দের সাথে অভিযুক্ত. আমি বিপথগামীদের এলাকা প্রতিদ্বন্দ্বিতা করা হতে পারে যে সে হয়তো বলতে পারে যখন আমি বলছি আমি যা বলছি,","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَيْسَرَةَ الْحَضْرَمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ الرَّجُلِ الْوَاحِدِ لَيْسَ بِنَبِيٍّ مِثْلُ الْحَيَّيْنِ أَوْ أَحَدِ الْحَيَّيْنِ ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏ ‏فَقَالَ قَائِلٌ إِنَّمَا ‏ ‏رَبِيعَةُ ‏ ‏مِنْ ‏ ‏مُضَرَ ‏ ‏قَالَ إِنَّمَا أَقُولُ مَا أَقُولُ ‏","","",""],[21266,21266,"","আমরা এক দৈত্যের দ্বারা চেষ্টা করেছি যে কিনা প্রভুর বাতিল করে দিয়ে কথা বলতে সক্ষম হয়েছে। আমি শুনেছি তার শান্তি বজায় রাখার জন্য আল্লাহ প্রার্থনা করেছেন। আমি ভেবেছিলাম সে তার সাথে কথা বলবে।","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ الْأَلْهَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوصِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[21267,21267,"","আমরা এত কষ্ট করে কথা বলেছি যে আমাকে মারতে চেষ্টা করে আমাকে পরাজিত করার চেষ্টা করেছি, রাজকুমারী বলেছে আমার হাত নিয়ে ঈশ্বরের কাছে নিয়ে যাও বলতে যে সে কখনই বলবে না যে সে মারা গেছে। তাকে চুমু দিতে.","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةٌ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو رَاشِدٍ الْحُبْرَانِيُّ ‏ ‏قَالَ ‏ ‏أَخَذَ بِيَدِي ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏أَخَذَ بِيَدِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏إِنَّ مِنْ الْمُؤْمِنِينَ مَنْ يَلِينُ لِي قَلْبُهُ ‏","","",""],[21268,21268,"","আমরা আপনাদের টাকাপয়সা এক বছর বেড়ে যাওয়ার বিষয়ে বলেছিলাম । তার নিজের হাত, দাঁত বা তার আংটির মালিক.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏لُقْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ رَجُلٍ يَلِي أَمْرَ عَشَرَةٍ فَمَا فَوْقَ ذَلِكَ إِلَّا أَتَى اللَّهَ عَزَّ وَجَلَّ مَغْلُولًا يَوْمَ الْقِيَامَةِ يَدُهُ إِلَى عُنُقِهِ فَكَّهُ بِرُّهُ أَوْ أَوْبَقَهُ إِثْمُهُ أَوَّلُهَا مَلَامَةٌ وَأَوْسَطُهَا نَدَامَةٌ وَآخِرُهَا خِزْيٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[21269,21269,"","আমরা আমাদের হৃদয় পরিবর্তন করার কথা বলেছিলাম, আমরা একটি ছেলের সাথে ঘুমের ওষুধ খেয়ে ঘুমাতে পেরেছি। সে আমাদের দু:খের জন্য আমাদের দাওয়াত দিয়েছে এবং সে আমাদের সাথে আছে, তাই সে কখনো ক্লান্ত হয় নি অথবা আমি দাঁড়িয়ে থাকি না, যদি আল্লাহ্ আত্মসমর্পণ করেন। তার কাছে তার বধিরতার অনেক স্বাদ আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏السَّرِيُّ بْنُ يَنْعُمَ ‏ ‏حَدَّثَنِي ‏ ‏عَامِرُ بْنُ جَشِيبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏دُعِينَا إِلَى ‏ ‏وَلِيمَةٍ ‏ ‏وَهُوَ مَعَنَا فَلَمَّا شَبِعَ مِنْ الطَّعَامِ قَامَ فَقَالَ أَمَا إِنِّي لَسْتُ أَقُومُ مَقَامِي هَذَا خَطِيبًا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَبِعَ مِنْ الطَّعَامِ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ ‏ ‏مَكْفِيٍّ ‏ ‏وَلَا مُسْتَغْنًى عَنْهُ ‏","","",""],[21270,21270,"","বাবা জন্মগ্রহন মানে আমার ছেলে, ঈশ্বরের দয়া হল বাবা নিজের মায়ের হেফাজতে আছে। শেষ গুটি পর্যন্ত গৌরব বয়ে আনে, আর পরেরটা আমি বলি, মানুষ আর আমার বাবা বলেন, তিনি আমার বাবা বা তার লর্ডশিপকে মুক্ত বললেন, তিনি বললেন ঈশ্বর কখনো তার সাথে নেই। তিনি বলেছিলেন তার একটা মোলায়েম, বাবা আছে। আপনি শুনেছেন যে, ঈশ্বরের অনুগ্রহ থেকে আপনার উপর। আপনি যদি কিছু বলেন, আপনি জানেন, আপনি জানেন যে তিনি কখনও তাঁর বাবা নন। আপনি জানেন, আপনি কি না যে তিনি আপনার বাবা আপনার সাথে আছেন? আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি যদি আপনার বাবা আপনার সাথে আছেন। আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি সত্যিই তিনি আপনার সাথে আছেন। আপনি জানেন, আপনি জানেন, আপনি আপনার বাবা আপনার বাবা আপনার সাথে আছেন। এবং আপনার বাবা আপনার সাথে আছেন। আপনি আপনার বাবা আপনার বাবা আপনার সাথে আছেন। এবং আপনার জন্য। আপনি আপনার বাবা আপনার সাথে আছেন। এবং আপনার বাবা আপনার জন্য। এবং আপনার বাবা আপনার বাবা আপনার সাথে আছেন। এবং আপনার সাথে আপনার বাবা আপনার সাথে আছেন। ঈশ্বরের অনুগ্রহ থেকে এটা শুনেছি, ঈশ্বর এটা করেছেন এবং আমাদের সবাইকে কিছু পথে উদ্ধার করেছেন, যেমনটা আমরা মিথ্যা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ الرَّحَبِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا أُمَامَةَ ‏ ‏دَخَلَ عَلَى ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏فَأَلْقَى لَهُ وَسَادَةً فَظَنَّ ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّهَا حَرِيرٌ فَتَنَحَّى يَمْشِي ‏ ‏الْقَهْقَرَى ‏ ‏حَتَّى بَلَغَ آخِرَ ‏ ‏السِّمَاطِ ‏ ‏وَخَالِدٌ ‏ ‏يُكَلِّمُ رَجُلًا ثُمَّ الْتَفَتَ إِلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏فَقَالَ لَهُ يَا أَخِي مَا ظَنَنْتَ أَظَنَنْتَ أَنَّهَا حَرِيرٌ قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَسْتَمْتِعُ بِالْحَرِيرِ مَنْ يَرْجُو أَيَّامَ اللَّهِ فَقَالَ لَهُ ‏ ‏خَالِدٌ ‏ ‏يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏غُفْرًا أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ كُنَّا فِي قَوْمٍ مَا كَذَبُونَا وَلَا كُذِّبْنَا ‏","","",""],[21271,21271,"","আমরা ঠিক বাবার কথা বলেছিলাম, সে আমার মায়ের সাথে নরকে যাবে, আমি আমার প্রভুর মত কিছু কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَعَدَنِي رَبِّي عَزَّ وَجَلَّ أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا وَثَلَاثَ ‏ ‏حَثَيَاتٍ ‏ ‏مِنْ ‏ ‏حَثَيَاتِ ‏ ‏رَبِّي عَزَّ وَجَلَّ ‏","","",""],[21272,21272,"","আমরা সঠিক কথা বলেছি, কিন্তু আমি ভালবাসাকে ভালোবাসি। একজন ভাববাদী তার কাছে প্রার্থনা করলেন, যিনি একটি ভাঙ্গা নামাজে ঢুকে পড়েছিলেন। আগামীকালের মা এবং Works হল ঈশ্বরের রাতের জন্য এই প্রচেষ্টা ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَشَى إِلَى صَلَاةٍ مَكْتُوبَةٍ وَهُوَ مُتَطَهِّرٌ كَانَ لَهُ كَأَجْرِ الْحَاجِّ الْمُحْرِمِ وَمَنْ مَشَى إِلَى سُبْحَةِ الضُّحَى كَانَ لَهُ كَأَجْرِ الْمُعْتَمِرِ وَصَلَاةٌ عَلَى إِثْرِ صَلَاةٍ لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي ‏ ‏عِلِّيِّينَ ‏ ‏و قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏الْغُدُوُّ ‏ ‏وَالرَّوَاحُ ‏ ‏إِلَى هَذِهِ الْمَسَاجِدِ مِنْ الْجِهَادِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21273,21273,"","আমরা একটি ছেলের কথা বলেছি যে তার প্রিয় ছেলেকে আমার হাতে নিয়ে এসেছে। আমার বাবা তার কাছে প্রার্থনা করতে দেখেছেন। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَمَّنْ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحَ إِلَى ‏ ‏مِنًى ‏ ‏يَوْمَ التَّرْوِيَةِ وَإِلَى جَانِبِهِ ‏ ‏بِلَالٌ ‏ ‏بِيَدِهِ عُودٌ عَلَيْهِ ثَوْبٌ يُظِلُّ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21274,21274,"","আমি যাজকের সাথে কথা বলেছি যে আমার ছেলে খারাপ ছেলে আছে, ঈশ্বর বলেছেন, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং জিজ্ঞেস করেছেন আমার প্রার্থনা করার চেয়ে ভাল কিছু করার অনুমতি আছে। সবসময় তার দোয়ায় ছিল, লর্ড কখনো খেলতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ خُنَيْسٍ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُذِنَ لِعَبْدٍ فِي شَيْءٍ أَفْضَلَ مِنْ رَكْعَتَيْنِ يُصَلِّيهِمَا وَإِنَّ الْبِرَّ لَيُذَرُّ فَوْقَ رَأْسِ الْعَبْدِ مَا دَامَ فِي صَلَاتِهِ وَمَا تَقَرَّبَ الْعِبَادُ إِلَى اللَّهِ تَعَالَى بِمِثْلِ مَا خَرَجَ مِنْهُ ‏ ‏يَعْنِي الْقُرْآنَ ‏","","",""],[21275,21275,"","আমরা শপথ নিয়ে কথা বলেছি, আমি আমার ভালবাসার আনন্দ নিয়ে কথা বলেছি, সে আমার কাছে প্রার্থনা করেছে এবং সে আমাকে ক্ষমা করবে। তার শিকারকে শিকার করা থেকে তার মৃত্যু হবে তার মতো এক রহস্য । ( হিতোপদেশ ১৪: ৩) তার ভয় বা অত্যাচার দ্বারা প্রতারিত হওয়া এবং ভয় দূর করা হবে না ।","‏ ‏حَدَّثَنَا ‏ ‏الْهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ بَعَثَنِي رَحْمَةً لِلْعَالَمِينَ وَهُدًى لِلْعَالَمِينَ وَأَمَرَنِي رَبِّي عَزَّ وَجَلَّ بِمَحْقِ الْمَعَازِفِ وَالْمَزَامِيرِ وَالْأَوْثَانِ وَالصُّلُبِ وَأَمْرِ الْجَاهِلِيَّةِ وَحَلَفَ رَبِّي عَزَّ وَجَلَّ بِعِزَّتِهِ ‏ ‏لَا يَشْرَبُ عَبْدٌ مِنْ عَبِيدِي جَرْعَةً مِنْ خَمْرٍ إِلَّا سَقَيْتُهُ مِنْ الصَّدِيدِ مِثْلَهَا يَوْمَ الْقِيَامَةِ مَغْفُورًا لَهُ أَوْ مُعَذَّبًا وَلَا ‏ ‏يَسْقِيهَا صَبِيًّا صَغِيرًا ضَعِيفًا مُسْلِمًا إِلَّا سَقَيْتُهُ مِنْ الصَّدِيدِ مِثْلَهَا يَوْمَ الْقِيَامَةِ مَغْفُورًا لَهُ أَوْ مُعَذَّبًا وَلَا يَتْرُكُهَا مِنْ مَخَافَتِي إِلَّا سَقَيْتُهُ مِنْ حِيَاضِ الْقُدُسِ يَوْمَ الْقِيَامَةِ وَلَا يَحِلُّ بَيْعُهُنَّ وَلَا شِرَاؤُهُنَّ وَلَا تَعْلِيمُهُنَّ وَلَا تِجَارَةٌ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ ‏ ‏يَعْنِي الضَّارِبَاتِ ‏","","",""],[21276,21276,"","আমরা দুটো প্রশংসার জন্য চেষ্টা করেছি, কিন্তু আমরা কিছু ভালো কাজ করেছি, আমার প্রিয় হাত দিয়ে তাকে শেখাব না... তাদের অপরাধের জন্য বিষ প্রয়োগ করা হবে এবং তাদের পরে তাদের বোঝা হবে যে কারা ক্রয় করবে। তাদের মুখ আর মুখটা ফুলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَطِيَّةَ بْنِ دِلَافٍ الْمُزَنِيِّ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ الدَّابَّةُ فَتَسِمُ النَّاسَ عَلَى خَرَاطِيمِهِمْ ثُمَّ يَغْمُرُونَ فِيكُمْ حَتَّى يَشْتَرِيَ الرَّجُلُ الْبَعِيرَ فَيَقُولُ مِمَّنْ اشْتَرَيْتَهُ فَيَقُولُ اشْتَرَيْتُهُ مِنْ أَحَدِ ‏ ‏الْمُخَطَّمِينَ ‏ ‏و قَالَ ‏ ‏يُونُسُ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏ثُمَّ يَغْمُرُونَ فِيكُمْ وَلَمْ يَشُكَّ قَالَ فَرَفَعَهُ ‏","","",""],[21277,21277,"","আমরা আপনার ছেলেকে বলেছিলাম কিভাবে তাকে বলতে হবে আমার বাবার থেকে ভাল শ্রেণী আছে... ...আমার পালনকর আমার কাছে আল্লাহ্‌র আদেশ করা হয়েছে. তাকে পুরোপুরি একা একা একা রেখে দেওয়া হয়েছে. তাকে শান্তিতে রাখো, তারপর সে বললো এটা ঠিক আছে, সে এটা ডুবে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ يَخُوضُ فِي الرَّحْمَةِ وَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَلَى وَرِكِهِ ثُمَّ قَالَ هَكَذَا مُقْبِلًا وَمُدْبِرًا وَإِذَا جَلَسَ عِنْدَهُ غَمَرَتْهُ الرَّحْمَةُ ‏","","",""],[21278,21278,"","আমরা চার জন বৌদ্ধ সন্ন্যাসীর দ্বারা বাপ্তাইজিত হওয়ার সংবাদ মুছে ফেলার চেষ্টা করেছি, আমি প্রার্থনা করছি ঈশ্বর তাকে উদ্ধার করেছেন এবং তাকে তিন বার আত্মসমর্পণ করেছেন সেই যুবক বলেছিল যে, তার কাছে ভাববাদী প্রার্থনা করছিলেন এবং তাকে সবসময় ও সব কিছুর আগে যেতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرٍ يَعْنِي ابْنَ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ وَكَانَ يَمْسَحُ ‏ ‏الْمَاقَيْنِ ‏ ‏مِنْ الْعَيْنِ قَالَ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ رَأْسَهُ مَرَّةً وَاحِدَةً وَكَانَ يَقُولُ الْأُذُنَانِ مِنْ الرَّأْسِ ‏","","",""],[21279,21279,"","আমরা একজন শিকারীর কথা বলেছি যে আমার বাবার জন্য আমাদের কথা বলেছে, যে ঈশ্বরের কাছে প্রার্থনা করেছে, সে তার নিজের পিতা। যে তাকে ধরে রেখেছে, আর আমি তাকে তার দেখাশোনা করতে বলবো, আর বাচ্চাগুলো যদি অপরাধীতে না যায় তাহলে সে কেমন হবে।","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهَا ابْنَانِ لَهَا وَهِيَ حَامِلٌ فَمَا سَأَلَتْهُ يَوْمَئِذٍ إِلَّا أَعْطَاهَا ثُمَّ قَالَ ‏ ‏حَامِلَاتٌ وَالِدَاتٌ رَحِيمَاتٌ لَوْلَا مَا يَأْتِينَ إِلَى أَزْوَاجِهِنَّ دَخَلْنَ الْجَنَّةَ ‏","","",""],[21280,21280,"","আমরা একটি নির্দিষ্ট ছেলের কথা বলেছি যে কিনা তার কথা পরিবর্তন করেছে একটা পিপাসার্ত ছেলের কথা দিয়ে। লর্ড তার জন্য প্রার্থনা করেছে এবং তার জন্য প্রার্থনা করেছে শুভেচ্ছা এবং দুই অভিশাপ দিয়েছে। বিশ্বাস এবং পিতা থেকে লোকজন, কপট।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَغَيْرُهُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَيَاءُ ‏ ‏وَالْعِيُّ ‏ ‏شُعْبَتَانِ مِنْ الْإِيمَانِ ‏ ‏وَالْبَذَاءُ ‏ ‏وَالْبَيَانُ ‏ ‏شُعْبَتَانِ مِنْ النِّفَاقِ ‏","","",""],[21281,21281,"","আমরা আমার বাবার মায়ের সাথে কথা বলেছি যে ঈশ্বর এটা করতে হবে বলে বলে। এমনকি তিনি আরো বড় হয়ে যান যদি তিনি তাকে রক্ষা করতে আরো বড় হন, অথবা তিনি বেঁচে যান। নিচে এসে বললো, \"হে, কতজন?\"","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ يَعْنِي ابْنَ زَاذَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏بِتِسْعٍ حَتَّى إِذَا بَدَّنَ وَكَثُرَ لَحْمُهُ ‏ ‏أَوْتَرَ ‏ ‏بِسَبْعٍ وَصَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ فَقَرَأَ ‏ ‏بِإِذَا زُلْزِلَتْ ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏","","",""],[21282,21282,"","আমরা কয়েকদিনের কথা বলেছি, শুনেছি ভিতরে আমি মুখ দিয়ে বলছি, নাকি বাবার রক্তের অনুগ্রহ নিয়ে। বাবা, তুমি তোমার দৃষ্টি থেকে এটা বলবে... ...অথবা তাকে বলবে যে সে আমাকে সূর্যের কানে রেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفْوَانَ بْنَ سُلَيْمٍ ‏ ‏يَقُولُ ‏ ‏دَخَلَ ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏دِمَشْقَ ‏ ‏فَرَأَى رُءُوسَ ‏ ‏حَرُورَاءَ ‏ ‏قَدْ نُصِبَتْ فَقَالَ ‏ ‏كِلَابُ النَّارِ كِلَابُ النَّارِ ثَلَاثًا شَرُّ قَتْلَى تَحْتَ ظِلِّ السَّمَاءِ خَيْرُ قَتْلَى مَنْ قَتَلُوا ثُمَّ بَكَى فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏هَذَا الَّذِي تَقُولُ مِنْ رَأْيِكَ أَمْ سَمِعْتَهُ قَالَ إِنِّي إِذًا لَجَرِيءٌ كَيْفَ أَقُولُ هَذَا عَنْ رَأْيٍ قَالَ قَدْ سَمِعْتُهُ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ قَالَ فَمَا ‏ ‏يُبْكِيكَ قَالَ أَبْكِي لِخُرُوجِهِمْ مِنْ الْإِسْلَامِ هَؤُلَاءِ الَّذِينَ تَفَرَّقُوا وَاتَّخَذُوا دِينَهُمْ شِيَعًا ‏","","",""],[21283,21283,"","আমরা একজন ওমাসের কথা বলেছি, যার সাথে তোমার দ্বিতীয় চিন্তার ছেলে বেনের বাবার টাকার চেয়েও বেশি কিছু জন্ম নিয়েছে। তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি এই দুই বছরই আমরা সুখী ছিলাম । আমরা কথা বলছি আর বলছি এরা অনেক লোক।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ الْمَسْجِدَ فَصَلَّى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا رَجُلٌ ‏ ‏يَتَصَدَّقُ ‏ ‏عَلَى هَذَا فَيُصَلِّيَ مَعَهُ قَالَ فَقَامَ رَجُلٌ فَصَلَّى مَعَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَانِ جَمَاعَةٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ وَقَالَ هَذَانِ جَمَاعَةٌ ‏","","",""],[21284,21284,"","আমরা আমার ছেলের চেয়ে ভাল ছেলের কথা বলেছি, যে ওকে রক্ষা করেছে আর তাকে বলে দিয়েছে যে তাকে জিজ্ঞেস করতে হবে। তার পাপ থেকে অপসারিত হওয়ার পর","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ ‏ ‏الْحَسَنُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ عَزَّ وَجَلَّ وَبِرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21285,21285,"","আমার বাবা বলেছিলেন যে, ঈশ্বর তাকে প্রার্থনা করতে শিখিয়েছিলেন যেন তিনি শিক্ষা দেবেন । ঈশ্বর এবং একজন মানুষ যিনি তার মঙ্গলের জন্য জানেন তিনি এটা চেষ্টা এবং একটি ছেলে যে এটা জন্য ছেড়ে. আমি তাকে বলছি ঈশ্বর আদেশ দিয়েছেন এবং তিনি তাকে তার দান করবেন. সে যদি বলে আমি যা করি, তা সে আমাকে শিখিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرْبَعٌ ‏ ‏تَجْرِي عَلَيْهِمْ أُجُورُهُمْ بَعْدَ الْمَوْتِ رَجُلٌ مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ وَرَجُلٌ عَلَّمَ عِلْمًا فَأَجْرُهُ يَجْرِي عَلَيْهِ مَا عَمِلَ بِهِ وَرَجُلٌ أَجْرَى ‏ ‏صَدَقَةً ‏ ‏فَأَجْرُهَا يَجْرِي عَلَيْهِ مَا جَرَتْ عَلَيْهِ وَرَجُلٌ تَرَكَ وَلَدًا صَالِحًا يَدْعُو لَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ وَمَنْ عَلَّمَ عِلْمًا أُجْرِيَ لَهُ مِثْلُ مَا عَلَّمَ ‏","","",""],[21286,21286,"","তিনি বলেছেন আমার বাবা বেঁচে ছিলেন এবং বাবার বইতে তিনি আমাকে এমন একটা লাইন দিয়ে আবিষ্কার করেছিলেন যার ফলে আমি আরও ভালো বোধ করতে শুরু করেছিলাম। সবচেয়ে ছোট যে নাম আমার বাবার বয়স পার হওয়ার কথা। আমি তাকে বললাম, আমার বাবার বয়স যখন প্রথম দিকে। আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কাছে ছিলাম প্রথম সন্তান। আমি জানি, আমি আমার বাবার নাম দিলাম, আমি আমার বাবার কাছে এটা একটা ছোট। আমি জানি না। আমি জানি না যে, আমি আমার বাবার কাছে এটা একটা ছোট। আমি জানি, আমি যদি আমার বাবার মত হয়ে যাই, আমি এটা একটা ছোট ছিলাম। আমি যদি আমার বাবার মত হয়ে যাই, আমি শুধু একটা জিনিস পাই, আমি জানি যে, আমি জানি, আমি তোমার জন্য। আমি জানি না। আমি জানি, আমি এটা একটা জিনিস। কিন্তু আমি জানি যে, আমি যদি তুমি জানো না, আমি আমার বাবার নাম ব্যবহার করতে পারি, আমি এটা একটা ছোট দল, আমি জানি যে, আমি এটা একটা ছোট। ঈশ্বর আমার বাবার দয়া, ঈশ্বর তোমাকে উদ্ধার করতে হবে না, তুমি আমার মায়ের সাথে অতীত জীবনের জন্য লড়াই করবে না, তারা ঈশ্বরের মাধ্যমে যাবে এবং তারা বলবে ঈশ্বর এবং আল্লাহ।","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنِي ‏ ‏مَهْدِيُّ بْنُ جَعْفَرٍ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ وَاسْمُهُ يَحْيَى بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَعَدُوِّهِمْ قَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ إِلَّا مَا أَصَابَهُمْ مِنْ لَأْوَاءَ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ وَهُمْ كَذَلِكَ قَالُوا يَا رَسُولَ اللَّهِ وَأَيْنَ هُمْ قَالَ ‏ ‏بِبَيْتِ الْمَقْدِسِ ‏ ‏وَأَكْنَافِ ‏ ‏بَيْتِ الْمَقْدِسِ ‏","","",""],[21287,21287,"","সে করেছে, আমি বাবার হাতে তার হাতের লেখা বই পেয়েছি আর আমি তাকে শুনতে পাচ্ছি। মনে হয় আমি হয়তো তার বাসাটা সম্পর্কে কথা বলেছি যে আমার চেয়ে বড় ছেলে আছে কিন্তু সে আমার কাছে আছে। আমার বাবার শপথ হচ্ছে যে একজন মানুষ ঈশ্বরের কাছে প্রার্থনা করবে আর তাকে আত্মসমর্পণ করতে বলবে... ...শান্তির শান্তি প্রতিষ্ঠা করতে ব্যর্থ হবে. ঈশ্বরের অনুগ্রহ বা ইচ্ছার শেষ কাজটি করার জন্য, এটাই আছে।","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏وَأَظُنُّ أَنِّي قَدْ ‏ ‏سَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُطَّرِحِ بْنِ يَزِيدَ الْكِنَانِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ ‏ ‏ظِلُّ ‏ ‏فُسْطَاطٍ ‏ ‏فِي سَبِيلِ اللَّهِ أَوْ خِدْمَةُ خَادِمٍ فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏طَرُوقَةُ ‏ ‏فَحْلٍ ‏ ‏فِي سَبِيلِ اللَّهِ ‏ ‏آخِرُ حَدِيثِ ‏ ‏أَبِي أُمَامَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[21288,21288,"","ঈশ্বর তাকে তার কাছে আগুন লাগিয়ে দিয়েছিলেন, যাতে তিনি বলেছিলেন যে, তার একজন মানুষ রয়েছে এবং কিছু একটা ভুল হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السَّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ كَانَ قَضِيبًا مِنْ ‏ ‏أَرَاكٍ ‏","","",""],[21289,21289,"","আমি আমার ছেলের সবচেয়ে ভালো ছেলের ব্যাপারে কথা বলেছি, ঐ অগ্নি রাজকুমারী বললো যে সে ঈশ্বরকে তার শান্তির জন্য প্রার্থনা করবে আর এমানের কাছে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أُمَامَةَ الْحَارِثِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَذَاذَةُ مِنْ الْإِيمَانِ ‏","","",""],[21290,21290,"","আমরা কিভাবে পরাজিত হতে হয়েছে সে সম্পর্কে কথা বলেছি আমার বাবা এখানে আছে... ...যে সে ঈশ্বরের কাছে প্রার্থনা করেছিল আর বলেছিল উপত্যকার জন্য কে প্রার্থনা করেছে. তুমি তাকে নিয়ন্ত্রণ করছ তাকে বিষ প্রয়োগ করা হচ্ছে. প্রদর্শন ও পরিবর্তন","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِي عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مَكْحُولًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو هِنْدٍ الدَّارِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَامَ مَقَامَ ‏ ‏رِيَاءٍ ‏ ‏وَسُمْعَةٍ ‏ ‏رَايَا ‏ ‏اللَّهُ تَعَالَى بِهِ يَوْمَ الْقِيَامَةِ وَسَمَّعَ ‏","","",""],[21291,21291,"","আমরা একটা কঠিন-ওন এর ছেলে যে মানুষ বেঁচে ছিল তার কথা বলছি। লর্ড প্রার্থনা করলেন... ...আর প্রভুর কাছে প্রার্থনা করবেন তাকে ছেড়ে দিয়ে তাকে আত্মসমর্পণ করা হবে। সে বলেছে তার কাছে শপথ আছে... ...তার মানে আমি শপথটা নিয়ে ক্লান্ত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيُفْتَحُ عَلَيْكُمْ ‏ ‏الشَّامُ ‏ ‏وَإِنَّ بِهَا مَكَانًا يُقَالُ لَهُ ‏ ‏الْغُوطَةُ ‏ ‏يَعْنِي ‏ ‏دِمَشْقَ ‏ ‏مِنْ خَيْرِ مَنَازِلِ الْمُسْلِمِينَ ‏ ‏يَعْنِي فِي ‏ ‏الْمَلَاحِمِ ‏","","",""],[21292,21292,"","আমরা আমার সবচেয়ে ভালো ছেলেকে সরিয়ে দেবার চেষ্টা করেছি, সুখ হচ্ছে এমন একজন মানুষ যে তার নিজের প্রাণে ঈশ্বরকে সেবা করেছে। আমরা আমাদের চালগুলো রেখে দিয়েছি, আর তারপর তোমাকে ভিতরে নিয়ে যেতে হবে। ( খ) কেন আমরা বলতে পারি যে, আমরা ঈশ্বরের ওপর নির্ভর করি?","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّعْدِيِّ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي مَالِكِ بْنِ حَنْبَلٍ ‏ ‏أَنَّهُ قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَاسٍ مِنْ أَصْحَابِهِ فَقَالُوا لَهُ احْفَظْ رِحَالَنَا ثُمَّ تَدْخُلُ وَكَانَ أَصْغَرَ الْقَوْمِ فَقَضَى لَهُمْ حَاجَتَهُمْ ثُمَّ قَالُوا لَهُ ادْخُلْ فَدَخَلَ فَقَالَ حَاجَتُكَ قَالَ حَاجَتِي تُحَدِّثُنِي أَنْقَضَتْ الْهِجْرَةُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَتُكَ خَيْرٌ مِنْ حَوَائِجِهِمْ لَا تَنْقَطِعُ الْهِجْرَةُ مَا قُوتِلَ الْعَدُوُّ ‏","","",""],[21293,21293,"","আমরা আমাদের বাবার কষ্ট নিয়ে কথা বলেছি, তিনি শুনেছেন নবী তার কাছে প্রার্থনা করেছেন এবং মানুষকে ডেকেছে তাকে আমার চেহারা বলতে নির্দেশনা দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَنْ ‏ ‏عَجُوزٍ مِنْ بَنِي نُمَيْرٍ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِالنَّاسِ وَوَجْهُهُ إِلَى ‏ ‏الْبَيْتِ ‏ ‏قَالَ فَحَفِظَتْ مِنْهُ ‏ ‏رَبِّ اغْفِرْ لِي خَطَايَايَ وَجَهْلِي ‏","","",""],[21294,21294,"","আমরা বাবার ছেলেকে বাঁচাতে চেষ্টা করেছি। সে দৃশ্যের একজন মহিলা, যে আমরা ঈশ্বরের অনুগ্রহে এসেছি এবং ঈশ্বরের কাছে প্রার্থনা করি। আমি চেষ্টা করব, আমি চেষ্টা করব। আমরা শুধু আলো জ্বালাবো, আর তারা বলেছে আকাশের দিকে আলো জ্বালাতে আর পরিকল্পনা হচ্ছে এটা ঘটতে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنِ ‏ ‏الْمَرْأَةِ مِنَ الْمُبَايِعَاتِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ أَصْحَابُهُ فِي ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَقَرَّبْنَا إِلَيْهِ طَعَامًا فَأَكَلَ وَمَعَهُ أَصْحَابُهُ ثُمَّ قَرَّبْنَا إِلَيْهِ وَضُوءًا فَتَوَضَّأَ ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ أَلَا أُخْبِرُكُمْ بِمُكَفِّرَاتِ الْخَطَايَا قَالُوا بَلَى قَالَ ‏ ‏إِسْبَاغُ الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏ ‏وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ ‏","","",""],[21295,21295,"","আমরা আমাদের কামনার দ্বারা বাপ্তাইজিত হয়েছি, যা আমাদের বাবার কাছে নিয়ে এসেছে। আমি ভবিষ্যদ্বাণীটা দেখেছি তার কাছে প্রার্থনা করতে, আর আমি তাকে ঘুমাতে যাওয়ার সময় দেব। মৃত্যু অথবা আগুনের শিখা নিয়ে যাবার সাহস।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا شَهِدَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ جَمْرَةِ ‏ ‏الْعَقَبَةِ ‏ ‏وَالنَّاسُ يَرْمُونَ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏لَا تَقْتُلُوا ‏ ‏أَوْ لَا تُهْلِكُوا ‏ ‏أَنْفُسَكُمْ وَارْمُوا الْجَمْرَةَ أَوْ الْجَمَرَاتِ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏وَأَشَارَ ‏ ‏شُعْبَةُ ‏ ‏بِطَرَفِ إِصْبَعِهِ السَّبَّابَةِ ‏","","",""],[21296,21296,"","আমি আমার বাবার কথা বলেছিলাম কিন্তু আমার ছেলে আরো ভালো কিছুর চেষ্টা করছে। ঈশ্বর বলেছেন, আপনি আমাকে আমার প্রভুর ইচ্ছার সাথে কথা বলেছেন। আর আমি বলবো যে খালি গাড়ি আপনি আমাকে উদ্বুদ্ধ করেছেন যাতে আমি আমার বাবা হতে উদ্বুদ্ধ হন। ঈশ্বর তাদেরকে একত্রিত করতে দেখেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ يَعْنِي الْمُقْرِي ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عِيسَى الْخُرَاسَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَارَةٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عِنْدَ طُلُوعِ الْفَجْرِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْقَبْرِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏فَقُلْتُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏أَرَأَيْتَ إِنْ جَمَعَهُمَا إِنْسَانٌ قَالَ ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ ‏","","",""],[21297,21297,"","আমি ঈশ্বরের ইচ্ছার জন্য প্রার্থনা করেছিলাম এবং তিনি তাঁর প্রার্থনায় তাঁর কাছে উপস্থিত হতেন। হাঁটু গেড়ে বসো তিন।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنِ ‏ ‏السَّعْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏رَمَقْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاتِهِ فَكَانَ ‏ ‏يَمْكُثُ فِي رُكُوعِهِ وَسُجُودِهِ قَدْرَ مَا يَقُولُ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ ثَلَاثًا ‏","","",""],[21298,21298,"","আমি আমার বাবার কথা বলেছিলাম আমার বাবার হাতের পুতুল হওয়ার কথা। ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমাকে বলেছেন যে তারা ঈশ্বরের কাছে যাবে। আর গোলাপের ওজন বা বৃদ্ধি হয়ত বেড়েই চলেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى الْبَكَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أَصُوغُ ‏ ‏لِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْنَنِي أَنَّهُنَّ لَسَمِعْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَزْنًا بِوَزْنٍ فَمَنْ زَادَ ‏ ‏أَوْ اسْتَزَادَ ‏ ‏فَقَدْ أَرْبَى ‏","","",""],[21299,21299,"","আমরা একটা নির্দিষ্ট মন্দের কথা বলেছিলাম, যখন তিনি মুক্ত ছিলেন । \"ডেলেল\" এর সাথে যুক্ত, যতক্ষণ না আমি খারাপ হয়ে গেছি ততক্ষণ তুমি আর লড়াই করো না যতক্ষণ না আমি তাদের ভুলে যাই.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏قَالَتْ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَاصِبٌ إِصْبَعَهُ مِنْ لَدْغَةِ عَقْرَبٍ فَقَالَ ‏ ‏إِنَّكُمْ تَقُولُونَ لَا عَدُوَّ وَإِنَّكُمْ لَا تَزَالُونَ تُقَاتِلُونَ عَدُوًّا حَتَّى يَأْتِيَ ‏ ‏يَأْجُوجُ ‏ ‏وَمَأْجُوجُ ‏ ‏عِرَاضُ الْوُجُوهِ صِغَارُ الْعُيُونِ ‏ ‏شُهْبُ ‏ ‏الشِّعَافِ ‏ ‏مِنْ كُلِّ ‏ ‏حَدَبٍ ‏ ‏يَنْسِلُونَ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ ‏ ‏الْمُطْرَقَةُ ‏","","",""],[21300,21300,"","আমি যখন পাথর মারার সময় তাঁর মা, তার বাবা বলেন তিনি তার প্রভুর কাছে ঈশ্বরের অনুগ্রহ নিয়ে বের হয়ে গেছেন, তার ছেলে আছে এবং তাকে হস্তান্তর করা হয়েছে। সে ঈশ্বরের কাছে প্রার্থনা করেছিল, তিনি তার প্রাণ হারিয়ে ফেলেছিলেন, এবং তারপর তিনি আমাদের পাঠিয়ে দিতেন। আমরা আকাশের সাথে যুদ্ধ করতে গিয়েছিলাম এবং ভুলে গিয়েছিলাম। ভালো ছেলে আর আমাদের কখনোই যেতে দেয়া হয়নি, যখন ঈশ্বর তাকে শেষ করে দিতে চান, আমাদের মতো আরো অনেক মানুষ আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏رَافِعُ بْنُ سَلَمَةَ الْأَشْجَعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏حَشْرَجُ بْنُ زِيَادٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ أُمِّ أَبِيهِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةِ ‏ ‏خَيْبَرَ ‏ ‏وَأَنَا سَادِسُ سِتِّ نِسْوَةٍ فَبَلَغَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ مَعَهُ نِسَاءً فَأَرْسَلَ إِلَيْنَا فَقَالَ ‏ ‏مَا أَخْرَجَكُنَّ وَبِأَمْرِ مَنْ خَرَجْتُنَّ فَقُلْنَا خَرَجْنَا نُنَاوِلُ السِّهَامَ وَنَسْقِي النَّاسَ السَّوِيقَ وَمَعَنَا مَا نُدَاوِي بِهِ الْجَرْحَى وَنَغْزِلُ الشَّعْرَ وَنُعِينُ بِهِ فِي سَبِيلِ اللَّهِ قَالَ قُمْنَ فَانْصَرِفْنَ فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ ‏ ‏خَيْبَرَ ‏ ‏أَخْرَجَ لَنَا سِهَامًا كَسِهَامِ الرَّجُلِ قُلْتُ يَا جَدَّةُ مَا أَخْرَجَ لَكُنَّ قَالَتْ تَمْرًا ‏","","",""],[21301,21301,"","আমরা সেই বধিরদের কথা বলেছিলাম, যে দিন আমরা বাবার সাথে কথা বলেছিলাম। আমার কিছু ভালো কিছু করার আছে, ভবিষ্যদ্বাণী পাওয়ার জন্য। আমি জানি, কে ঘুমিয়েছিল। আমি যখন প্রথম বার এই ঘটনা ঘটেছে, তখন আমরা একটা ছেলে, যে আমার বাবার সাথে কথা বলেছিলাম, সেই দিন আমি ভেবেছিলাম, সে আমার বাবার সাথে কথা বলেছি। আমি যখন আমি ভেবেছিলাম, আমি ভেবেছিলাম, আমি জানি, আমি জানি, আমি জানি, আমি এটা একটা ভালো জিনিস। আমি যদি আমার কাছে ফিরে যাই, আমি এটা একটা ভালো জিনিস। আমি জানি, আমি যদি আমি এটা করতে পারি, আমি এটা একটা ছোট ছোট ছোট ছেলে। আমি জানি, আমি যদি আমি এটা করি, আমি জানি যে আমি এটা করতে পারি। আমি এটা একটা ছোট ছিলাম, আমি এটা একটা ছেলে, আমি যদি আমি আমার বাবার সাথে কথা বলি, আমি আমার কাছে একটা ছোট ছিলাম, আমি যদি আমি এটা একটা ছোট ছিলাম, আমি আমার বাবা না। আমি আমার ছেলে না। আমি আমার ছেলে না। আমি আমার ছেলে ছিলাম, আমি যদি আমি আমার ছেলে না। আমি জানতাম, আমি আমার ছেলে-মেয়ে হই, আমি আমার ছেলে-মেয়ে। আমি আমার ছেলে-মেয়ে। আমি আমার ছেলে, আমি আমার ছেলে-মানুষ হয়ে যাই। আমি জানি যে আমি এটা একটা ছোট ছিলাম। আমি জানি, আমি যখন আমি এটা একটা ছোট ছিলাম। আমি এটা একটা ছোট তাকে ভাড়া দিতে হয়নি তার পায়ের টাকা হয়তো হাসপাতাল থেকে ছাড়া পাওয়া যেত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَكَانَ عَامِلًا عَلَى ‏ ‏تَوَّجَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ نَامَ عَلَى ‏ ‏إِجَّارٍ ‏ ‏لَيْسَ عَلَيْهِ مَا يَدْفَعُ قَدَمَيْهِ فَخَرَّ فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ وَمَنْ رَكِبَ الْبَحْرَ إِذَا ‏ ‏ارْتَجَّ ‏ ‏فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ ‏","","",""],[21302,21302,"","আমরা হেঁটে যাচ্ছি আর ফিরে এসেছি, আমরা লেক সম্পর্কে কথা বলেছি, একটা মেয়ে আছে যাকে তার কিছু বব বিয়ে থেকে বের করে দেয়া হয়েছে। আর অনুমান করো, প্রতি মাসে শার্ক আর ঘুমোবে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحُرُّ بْنُ الصَّيَّاحِ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏عَنِ ‏ ‏الْحُرِّ ‏ ‏عَنْ ‏ ‏هُنَيْدَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ تِسْعَ ذِي الْحِجَّةِ ‏ ‏وَيَوْمَ عَاشُورَاءَ ‏ ‏وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوَّلَ اثْنَيْنِ مِنْ الشَّهْرِ وَخَمِيسَيْنِ ‏","","",""],[21303,21303,"","আমরা আমার বাবার এত কথা বলেছি যে সে আমাদের সাথে গিয়েছিল, ঈশ্বর প্রার্থনা করেছিলেন তাকে উদ্ধার করতে। রাতে আমার জন্য একটা অতিথি হয়ে এসেছে, যার নাম হলো শেল্র, আর গুজব আর আমি তোমার কাছে ঋণী,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هَمَّامٍ الشَّعْبَانِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ مِنْ خَثْعَمَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَوَقَفَ ذَاتَ لَيْلَةٍ وَاجْتَمَعَ عَلَيْهِ أَصْحَابُهُ فَقَالَ ‏ ‏إِنَّ اللَّهَ أَعْطَانِي اللَّيْلَةَ الْكَنْزَيْنِ كَنْزَ ‏ ‏فَارِسَ ‏ ‏وَالرُّومِ ‏ ‏وَأَمَدَّنِي بِالْمُلُوكِ مُلُوكِ ‏ ‏حِمْيَرَ ‏ ‏إِلَّا الْأَحْمَرَيْنِ وَلَا مُلْكَ إِلَّا لِلَّهِ يَأْتُونَ يَأْخُذُونَ مِنْ مَالِ اللَّهِ وَيُقَاتِلُونَ فِي سَبِيلِ اللَّهِ قَالَهَا ثَلَاثًا ‏","","",""],[21304,21304,"","আমরা একটা রাজধানী সম্পর্কে কথা বলেছিলাম, যেখানে আমার বাবার স্বপ্ন দেখে দুই ঘোড়া তৈরি করেছিলাম যে তাকে হত্যা করেছিল । সে বলেছিল, আংটিটা আমি তাকে বের করে দিয়েছি, যখন তুমি তাকে এটা উপভোগ করতে বলেছিলে আর তাকে মেরে ফেলতে বলেছ.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ خَاتَمٌ مِنْ ذَهَبٍ فَأَخَذَ جَرِيدَةً فَضَرَبَ بِهَا كَفِّي وَقَالَ اطْرَحْهُ قَالَ فَخَرَجْتُ فَطَرَحْتُهُ ثُمَّ عُدْتُ إِلَيْهِ فَقَالَ مَا فَعَلَ الْخَاتَمُ قَالَ قُلْتُ طَرَحْتُهُ قَالَ ‏ ‏إِنَّمَا أَمَرْتُكَ أَنْ تَسْتَمْتِعَ بِهِ وَلَا تَطْرَحَهُ ‏","","",""],[21305,21305,"","আমরা একটা ছেলেকে কথা বলেছিলাম যে আমার সাথে প্রতারণা করছিল। যখন তারা জন্ম নেয়, তারা আবার বেড়ে উঠে। সে আমার পরিতৃপ্তি নিয়ে কথা বলে। আমি যা করেছি, তা নিয়ে কথা বলে আমি এখন আমার পরম খুশি। আমি যদি বলি, আমি তা করি, আমি তো শুধু একটা ছেলে, আমি যদি আমার ছেলের সাথে প্রতারণা করি, আমি কিন্তু আমি যদি আমার জীবনের জন্য না করি, আমি আমার জীবনের জন্য না করি, আমি তো শুধু একটা জিনিসই করি। আমি জানি, আমি কি করি? তার ছেলে তাকে এটা করতে বলেছে, সে চায় না যে তারা কিছু করুক।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏فَدَخَلَ ‏ ‏شَابَّانِ ‏ ‏مِنْ وَلَدِ ‏ ‏عُمَرَ ‏ ‏فَصَلَّيَا رَكْعَتَيْنِ بَعْدَ الْعَصْرِ فَأَرْسَلَ إِلَيْهِمَا فَدَعَاهُمَا فَقَالَ مَا هَذِهِ الصَّلَاةُ الَّتِي صَلَّيْتُمَاهَا وَقَدْ كَانَ أَبُوكُمَا يَنْهَى عَنْهَا قَالَا حَدَّثَتْنَا ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهُمَا عِنْدَهَا فَسَكَتَ وَلَمْ يَرُدَّ عَلَيْهِمَا شَيْئًا ‏","","",""],[21306,21306,"","আমরা দু'জন বাপ্তিস্মের কথা বলেছি, কিন্তু আমরা কথা বলেছি, এটা খুঁজে পাওয়া কঠিন। একজন লোক একজন লোক তার সমস্যা থেকে তাকে বের করে আনতে ভয় পেয়ে যায়। সে শুধু বলেছে চলে গেছে আর আমি চাই তোমার ঘোড়া যেন তোমার সন্দেহ গান গাইতে পারে। সে বলে, যদি সে ঈশ্বরের সাথে খেলতে না পারে, তাহলে সে তাকে কামড় দেয়নি। আগেই করেছি।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏وَكَانَ لِجَدِّهِ صُحْبَةٌ ‏ ‏أَنَّهُ خَرَجَ زَائِرًا لِرَجُلٍ مِنْ إِخْوَانِهِ فَبَلَغَهُ شَكَاتُهُ قَالَ فَدَخَلَ عَلَيْهِ فَقَالَ أَتَيْتُكَ زَائِرًا عَائِدًا وَمُبَشِّرًا قَالَ كَيْفَ جَمَعْتَ هَذَا كُلَّهُ قَالَ خَرَجْتُ وَأَنَا أُرِيدُ زِيَارَتَكَ فَبَلَغَتْنِي شَكَاتُكَ فَكَانَتْ عِيَادَةً وَأُبَشِّرُكَ بِشَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَبَقَتْ لِلْعَبْدِ مِنْ اللَّهِ مَنْزِلَةٌ لَمْ يَبْلُغْهَا بِعَمَلِهِ ابْتَلَاهُ اللَّهُ فِي جَسَدِهِ أَوْ فِي مَالِهِ أَوْ فِي وَلَدِهِ ثُمَّ صَبَّرَهُ حَتَّى يُبْلِغَهُ الْمَنْزِلَةَ الَّتِي سَبَقَتْ لَهُ مِنْهُ ‏","","",""],[21307,21307,"","আমি বাবার সঙ্গে আমার ঘোড়ার সঙ্গে যুদ্ধ করার বিষয়ে কথা বলেছিলাম । ( খ) কেন আমাদের ঈশ্বরের কাছে প্রার্থনা করা উচিত?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أُبْدِعَ ‏ ‏بِي فَاحْمِلْنِي قَالَ فَقَالَ لَيْسَ عِنْدِي قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَفَلَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏","","",""],[21308,21308,"","বাবা আমাকে আমার প্রেমে সাহায্য করার চেষ্টা করেছে। সে ঈশ্বরকে বলে আমি যা পারি তা দিয়ে সবটুকু দিয়ে দেবে। খুব চুপচাপ তার বাড়ি তোমাকে অনুমতিও দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ ضَمْعَجٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ فَأَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَأَكْبَرُهُمْ سِنًّا وَلَا تَؤُمَّنَّ رَجُلًا فِي سُلْطَانِهِ وَلَا تَجْلِسْ عَلَى ‏ ‏تَكْرِمَتِهِ فِي بَيْتِهِ حَتَّى يَأْذَنَ لَكَ ‏","","",""],[21309,21309,"","বেনের সাথে আমরা কথা বলেছি, ডাক্তারকে বলা হয়েছে আর ডাক্তারকে আরো ভাল করে বলব, আমার বাবা হয়তো আমার জন্য সবচেয়ে ভাল একজন সন্তানের জন্য। বাবা, এটা প্রথম রাত থেকে শুরু করে... ...অথবা এর শেষ রাত পর্যন্ত.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُوتِرُ ‏ ‏مِنْ أَوَّلِ اللَّيْلِ وَأَوْسَطِهِ وَآخِرِهِ ‏","","",""],[21310,21310,"","আমরা বাবার মৃত্যুর প্রতিজ্ঞা নিয়ে খুশি। লর্ড তার কাছে প্রার্থনা করল এবং সে তার পাপের জন্য নিজেকে দোষী সাব্যস্ত করবে এবং তার প্রতারণার জন্য, তারপর সে এটা দেখতে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمُسْلِمِ عَلَى الْمُسْلِمِ أَرْبَعُ خِلَالٍ أَنْ يُجِيبَهُ إِذَا دَعَاهُ ‏ ‏وَيُشَمِّتَهُ ‏ ‏إِذَا عَطَسَ وَإِذَا مَرِضَ أَنْ ‏ ‏يَعُودَهُ ‏ ‏وَإِذَا مَاتَ أَنْ يَشْهَدَهُ ‏","","",""],[21311,21311,"","আমরা আমার বাবা ফিরে আসার কথা বলেছি, ঈশ্বরকে বলে আমরা তাঁর কাছে এসেছি। আমাদের যেতে হবে, আমাদের সঠিক প্রকাশ চার বার ইনস্যুরেন্স নষ্ট হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ نَحْوَ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏الْإِيمَانُ هَاهُنَا الْإِيمَانُ هَاهُنَا وَإِنَّ الْقَسْوَةَ وَغِلَظَ الْقُلُوبِ فِي ‏ ‏الْفَدَّادِينَ ‏ ‏عِنْدَ أُصُولِ أَذْنَابِ الْإِبِلِ حَيْثُ يَطْلُعُ قَرْنَا الشَّيْطَانِ فِي ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏","","",""],[21312,21312,"","আমরা বাবাকে সাহায্য করার চেষ্টা করেছি, যাতে আমি বাবাকে সাহায্য করতে পারি। আগামীকাল দর্শন-এর মুখ থেকে, প্রভু তার কাছে প্রার্থনা করলেন এবং আমি তার আত্মার সবচেয়ে ভুলের দিকে পৌঁছে দেবো। আর তারপর সাহস লাগবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسُ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي أَتَأَخَّرُ عَنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مِنْ أَجْلِ فُلَانٍ مِمَّا يُطِيلُ بِنَا فَمَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ غَضَبًا فِي مَوْعِظَةٍ مِنْهُ يَوْمَئِذٍ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ مِنْكُمْ لَمُنَفِّرِينَ فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيَتَجَوَّزْ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[21313,21313,"","আমরা দুই গ্রীষ্মের কথা বলেছি আমার বাবা ঈশ্বরের কাছে ফিরে আসার কথা, তিনি বললেন প্রথম ছাত্র থেকে আপনাকে কি শিখাই, যদি আপনি আপনার পরিচয় না দেন তাহলে আপনি যা করছেন তা করতে পারবেন না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى ‏ ‏إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[21314,21314,"","ডার্ক লেডি বলেছে আপনার ছেলে আমরা ভালোবাসার জন্য সব থেকে ভালো চেষ্টা করেছি। আমার ছেলে আমার বাবার ছেলে, যে ভাববাদীর জন্য খুশি, যে তাকে বলেছে। আমি যখন তোমাকে মানুষ বলি তখন প্রথম বুয় হয়, যদি তুমি যা করতে না পারো","‏ ‏زِيَادَات الْقُطَيْعِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَعْنَبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[21315,21315,"","আমরা বাবার সাথে কথা বলেছি একটা সময়ের রিং বা বাবার ফিরে যাওয়া নিয়ে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং স্বপ্ন এবং আমাদের মধ্যে বন্ধুত্বের আদেশ দেবেন। আমি একটা ভাইকে বলছি যে আমি কে, সে তার শ্বাস নিচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ ‏ ‏بِالصَّدَقَةِ ‏ ‏فَيَنْطَلِقُ أَحَدُنَا فَيُحَامِلُ فَيَجِيءُ ‏ ‏بِالْمُدِّ ‏ ‏وَإِنَّ لِبَعْضِهِمْ الْيَوْمَ مِائَةَ أَلْفٍ ‏ ‏قَالَ ‏ ‏شَقِيقٌ ‏ ‏فَرَأَيْتُ أَنَّهُ يُعَرِّضُ بِنَفْسِهِ ‏","","",""],[21316,21316,"","আমরা একটা নিয়মিত ঈশ্বরের সাহায্য নিয়ে কথা বলেছি, লর্ড তার জন্য প্রার্থনা করেছে এবং লোকটির পিতামাতার কাছে তার বন্ধুত্বের কথা ঘোষণা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفَقَةُ الرَّجُلِ عَلَى أَهْلِهِ يَحْتَسِبُهَا ‏ ‏صَدَقَةٌ ‏","","",""],[21317,21317,"","আমরা অনেক বছর ধরে আমার বাবার পর্দার উপর বসে থাকার কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে পাপকে উদ্ধার করবে আর সে বলেছে যে সে একজন অবিকৃত, তাই সে একটা পাগল। ছেলেরা, ছেলেরা, এমনকি ছয়বার, এমনকি ছয়বার, বলে যে আপনি তা করেন বা আপনি যদি বলেন, তার নামের একজন মুখোশ পরা লোক হয়তো তাকে মুখোশে ঢাকা অবস্থায় দেখে, কিন্তু সে তার সাথে কথা বলে। আমরা বাবার মৃত্যুর কথা বলেছিলাম আর তার বাবার মৃত্যুর বিষয়টা আমাদের কাছে ঘটেছে । আশীর্বাদ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ فِيكُمْ مُنَافِقِينَ فَمَنْ سَمَّيْتُ فَلْيَقُمْ ثُمَّ قَالَ قُمْ يَا فُلَانُ قُمْ يَا فُلَانُ قُمْ يَا فُلَانُ حَتَّى سَمَّى سِتَّةً وَثَلَاثِينَ رَجُلًا ثُمَّ قَالَ إِنَّ فِيكُمْ ‏ ‏أَوْ مِنْكُمْ ‏ ‏فَاتَّقُوا اللَّهَ قَالَ فَمَرَّ ‏ ‏عُمَرُ ‏ ‏عَلَى رَجُلٍ مِمَّنْ سَمَّى مُقَنَّعٍ قَدْ كَانَ يَعْرِفُهُ قَالَ مَا لَكَ قَالَ فَحَدَّثَهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بُعْدًا لَكَ سَائِرَ الْيَوْمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أُرَاهُ ‏ ‏عِيَاضَ بْنَ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[21318,21318,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদেরকে জন্মের অভিশাপ বহন করতে নিয়ে এসেছে। আমি একটা মেঘকে মারছিলাম। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করেছেন, আমি ফাঁসির দিন পার হয়ে যাচ্ছি। আমি এখানে এসেছি। আমি তো বলি, আমি এখানে আছি, আমি এখান থেকে এসেছি। আমি বলছি, আমি আমার জীবনের জন্য। আমি কি বলছি, আমি যদি আমার জীবনের জন্য প্রার্থনা করি, আমি যদি আমার জীবনের জন্য, আমি আমার সৃষ্টিকর্তাকে ক্ষমা করে দেই? তার সাথে ঈশ্বরের কাছে শপথ করে, সে শপথ নিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّهُ كَانَ يَضْرِبُ غُلَامًا لَهُ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ قَالَ يَا نَبِيَّ اللَّهِ فَإِنِّي أُعْتِقُهُ لِوَجْهِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21319,21319,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের আমার ছেলের ইচ্ছা বহন করতে এনেছে। আমি তার কাছে প্রার্থনা করছি এবং তাকে বলছি আমাকে যেন না ছেড়ে না দেওয়া হয়। ভগবান তার কাছে প্রার্থনা করবে আর অন্যদের কাছে আত্মসমর্পণ করবে, যেমন সে ভাড়া করেছে বা তার কাজ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَقَالَ مَا عِنْدِي مَا ‏ ‏أُعْطِيكَ وَلَكِنْ ائْتِ فُلَانًا فَأَتَى الرَّجُلَ فَأَعْطَاهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏ ‏أَوْ عَامِلِهِ ‏","","",""],[21320,21320,"","ঈশ্বর হয়তো দিনের দিন আমার বিজয়কে আমার বিজয় হিসেবে তৈরি করেছেন । আমি প্রার্থনা করে প্রার্থনা করি যেন আমার বাবা তার শান্তির জন্য ঈশ্বরকে জিজ্ঞেস করতে পারেন । ঈশ্বরের অনুগ্রহে আমাকে তোমার কাছে নিয়ে আসা হয়েছে, ঈশ্বর তাকে দাবি করেছেন এবং আশা করেছেন যে তিনি তাকে এই কথা বলতে বলেননি। আপনি তাদের দেখতে এবং আশীর্বাদ করতে প্রার্থনা করেছেন। তুমি ঠিক বলেছ.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏هُوَ الَّذِي كَانَ أُرِيَ النِّدَاءَ بِالصَّلَاةِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَجْلِسِ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ لَهُ ‏ ‏بَشِيرُ بْنُ سَعْدٍ ‏ ‏أَمَرَنَا اللَّهُ أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ فَكَيْفَ نُصَلِّي عَلَيْكَ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ ثُمَّ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ وَالسَّلَامُ كَمَا قَدْ عَلِمْتُمْ ‏","","",""],[21321,21321,"","সে বলেছে, আমি তোমার সবচেয়ে ভালো টাকার কথা পড়েছি, একজন পলাতকের ছেলে যে কিনা শুকরের সন্তান। ঈর্ষাই হল শেষ কথা, আমি শুনতে চাই না যে সিঁড়ি জিতবে। আল্লাহকে রক্ষা করুন, তিনি আদেশ দিয়েছেন এবং আত্মসমর্পণ করেছেন এবং তিনি বলেছেন তিনি এটা করেছেন. তুমি বলেছিলে তুমি জানো আমার বাবার বাবার বাবার ব্যাপারে কথা বলার জন্য আসা মন্দটা।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكُ ابْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏فَأَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ ‏ ‏بِالْكُوفَةِ ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏أَلَيْسَ قَدْ عَلِمْتَ أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بِهَذَا أُمِرْتُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِعُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏اعْلَمْ مَا تُحَدِّثُ بِهِ يَا ‏ ‏عُرْوَةُ ‏ ‏أَوَأَنَّ ‏ ‏جِبْرِيلَ ‏ ‏هُوَ الَّذِي أَقَامَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتَ الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏كَذَلِكَ كَانَ ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏","","",""],[21322,21322,"","আমি আমার বাবার কাছে ফিরে যাওয়ার জন্য বাবার জীবনের সবচেয়ে ভালো দুটো জীবনের কথা বলেছিলাম, আমি আমার মুখে ফিরে গেলে আমি তোমার টাকা মারব। ঈশ্বর তাকে বলতে বলেছেন যে ঈশ্বর এটা করতে হবে। আপনি কি করছেন, আমি তার জন্য কৃতজ্ঞ। আমি আমার বাবার কাছে ফিরে যাচ্ছি? আমি আমার বাবা, আমি আমার বাবার কাছে তোমার টাকা দিয়ে টাকা ধার নিয়েছি, যদি আমি আমার বাবার কাছে ফিরে যাই। আমি যদি আমার মুখে ফিরে যাই, তাহলে আমি তোমার কাছে এটা বিক্রি করি। আর আমি তোমার কাছে এটা একটা জিনিস আছে। আর আমি যদি আমার বাবার কাছে এটা বিক্রি করি, তাহলে তুমি জানো, আমি তোমার জন্য একটা টাকা ধার নিতে পারব। আমি তোমার জন্য যা করতে চাই, আমি তোমার জন্য। আমি তোমার কাছে এটা করতে চাই। আমি তোমার কাছে এটা একটা বিষয় নিয়ে কথা বলেছি। আমি যদি তুমি জানো না, আমি তোমার কাছে এটা করতে চাই, তাহলে তুমি জানো না। আমি তোমার জন্য অনেক ধন্যবাদ দিতে চাই, আমি তোমার জন্য এটা করতে পারি। আমি তোমার জন্য। আমি আমার বাবার কাছে এটা একটা বড় হয়েছি। এটা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَضْرِبُ مَمْلُوكًا لِي إِذَا رَجُلٌ يُنَادِي مِنْ خَلْفِي اعْلَمْ يَا ‏ ‏أَبَا مَسْعُودٍ ‏ ‏اعْلَمْ يَا ‏ ‏أَبَا مَسْعُودٍ ‏ ‏فَالْتَفَتُّ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَاللَّهِ ‏ ‏لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَى هَذَا قَالَ فَحَلَفْتُ لَا أَضْرِبُ مَمْلُوكًا لِي أَبَدًا ‏","","",""],[21323,21323,"","আমরা একটা দুর্বল ছেলেকে নিয়ে কথা বলেছি, আমরা একজন যাজককে ভালবাসি। ঈশ্বর হয়তো আমার বাবার পাপী, যে আমার অতিথি বলে যে, ঈশ্বর প্রার্থনা করেছেন। আমি চলে যাবো না আর তুমি তাকে মেরে ফেলবে। আমাদের কথাবার্তার অত্যাচার হচ্ছে যে আমরা অন্ধ... সে বলেছিল বাবা তার মতই অন্ধ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقُرَيْشٍ ‏ ‏إِنَّ هَذَا الْأَمْرَ لَا يَزَالُ فِيكُمْ وَأَنْتُمْ وُلَاتُهُ حَتَّى تُحْدِثُوا أَعْمَالًا فَإِذَا فَعَلْتُمْ ذَلِكَ سَلَّطَ اللَّهُ عَلَيْكُمْ شِرَارَ خَلْقِهِ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏كَمَا ‏ ‏يُلْتَحَى ‏ ‏الْقَضِيبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏وَكَذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏وَقَالَ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏كَمَا ‏ ‏يُلْتَحَى الْقَضِيبُ ‏","","",""],[21324,21324,"","আমরা আমার বাবার সাথে কথা বলেছিলাম, তুমি প্রভুর প্রভুর লর্ডের লর্ডের লর্ডের উপর বিশ্বাস রাখ, তার শান্তি ও শান্তি আমার কাছে পৌঁছে দিতে পারবে। আমরা দৃঢ়প্রতিজ্ঞ মানুষ হতে দৃঢ়প্রতিজ্ঞ ছিলাম যে... ...আমরা কতবার শুনেছি যে সে আসতে বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا تَصَدَّقَ بِنَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏ ‏فِي سَبِيلِ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْتِيَنَّ ‏ ‏أَوْ لَتَأْتِيَنَّ ‏ ‏بِسَبْعِ مِائَةِ نَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏فَذَكَرَهُ وَلَمْ يَشُكَّ قَالَ لَتَأْتِيَنَّ ‏","","",""],[21325,21325,"","আমি প্রার্থনা করতে পেরে আনন্দিত এবং ঈশ্বর যেমন ভেঙে গিয়েছেন, তাকে না প্রার্থনা করতে বলি । এরপর তিনি তার কাঁধের ওপর তার ভাগ্য ঢুকিয়ে তাকে বলেছিলেন যে, তিনি তার কাঁধে চড়বেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ الْبَرَّادُ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏فَسَأَلْنَاهُ عَنْ الصَّلَاةِ فَقَالَ أَلَا أُصَلِّي بِكُمْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ فَقَامَ ‏ ‏فَكَبَّرَ وَرَفَعَ يَدَيْهِ ثُمَّ رَكَعَ فَوَضَعَ كَفَّيْهِ عَلَى رُكْبَتَيْهِ ‏ ‏وَجَافَى ‏ ‏بَيْنَ إِبْطَيْهِ قَالَ ثُمَّ قَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ سَجَدَ فَوَضَعَ كَفَّيْهِ ‏ ‏وَجَافَى ‏ ‏بَيْنَ إِبِطَيْهِ قَالَ ثُمَّ قَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ صَلَّى أَرْبَعَ رَكَعَاتٍ هَكَذَا ‏","","",""],[21326,21326,"","আমরা আমার বাবা শয়তানকে সাহায্য করার জন্য তার সঙ্গে গিয়েছিলাম । যা কিছু করা হয়েছে, ভাল কাজ করা।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏رَفَعَهُ ‏ ‏وَقَالَ ‏ ‏شَاذَانُ ‏ ‏مَرَّةً عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْتَشَارُ مُؤْتَمَنٌ ‏ ‏وَذَكَرَ ‏ ‏شَاذَانُ ‏ ‏أَيْضًا حَدِيثَ ‏ ‏الدَّالِّ عَلَى الْخَيْرِ كَفَاعِلِهِ ‏","","",""],[21327,21327,"","আমরা আমার বাবার সাথে সমুদ্রের মৌসুমের সময় আমার বাবার ভালবাসার কথা বলেছিলাম। আমার বাবা খুশি যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যেন তিনি তাকে অপসারণ না করেন। আপনি যদি তা করেন, তাহলে আপনি তা না করতেন। ঈশ্বরের শক্তি তাঁর বাক্য এবং আপনার বাক্য","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقُرَيْشٍ ‏ ‏إِنَّ هَذَا الْأَمْرَ لَا يَزَالُ فِيكُمْ وَأَنْتُمْ وُلَاتُهُ مَا لَمْ تُحْدِثُوا فَإِذَا ‏ ‏فَعَلْتُمْ ذَلِكَ سَلَّطَ اللَّهُ عَلَيْكُمْ شِرَارَ خَلْقِهِ ‏ ‏وَالْتَحَوْكُمْ ‏ ‏كَمَا ‏ ‏يُلْتَحَى ‏ ‏الْقَضِيبُ ‏","","",""],[21328,21328,"","আমরা সবাই একটা ছেলের কথা বলেছি যে আমাদের সাথে এমন একটা ছেলে হয়েছে যার কথা আমরা শুনেছি। সে আগে ২ বার আমার বাবার ব্যাপারে কথা বলেছিল, সে ঈশ্বরের কাছে প্রার্থনা করল আর আমি যা চাই তা বলবে, আমার প্রভু, যারা তাদের সম্মান করে তারা ঈশ্বরের মৃত্যু কামনা করবে না। তুমি, ছেলেটি তার কাছে প্রার্থনা করেছে আর আত্মসমর্পণ করেছে, আর তারপর সে বলল, \"আমি ভীত নই\"।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَبِيلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْمُقْرِئَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي قَبِيلٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْجُبْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أُحِبُّ أَنَّ لِي الدُّنْيَا وَمَا فِيهَا بِهَذِهِ الْآيَةِ ‏ { ‏يَا ‏ ‏عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ ‏} ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ فَمَنْ أَشْرَكَ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ إِلَّا مَنْ أَشْرَكَ ثَلَاثَ مَرَّاتِ ‏","","",""],[21329,21329,"","আমি বধিরদের নিয়ম নিয়ে কথা বলেছি যে আমার বাবা মেঘের কথা বলেছেন, ঈশ্বরের প্রভু তার কাছে প্রার্থনা করেছেন আর তাকে ঈশ্বরের প্রভুর কাছে প্রার্থনা করেছেন, ঈশ্বর তার কাছে প্রার্থনা করেছেন। আর খোদা তার শান্তির জন্য ছিলেন, তার কাছে একজন পরিপূর্ণ মানুষ, তাকে ছেড়ে দিতেই হবে। সে মনে করে যে সে চলে যাবে এবং তার চেয়ে ভালো আর ভালো হবে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন, এ ক্ষেত্রে আমি একজন অসভ্য যোদ্ধা। তাদের জীবনের বই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ الشَّامِيُّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْمَنْبِهِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَافَرَ آخِرُ عَهْدِهِ بِإِنْسَانٍ ‏ ‏فَاطِمَةُ ‏ ‏وَأَوَّلُ مَنْ يَدْخُلُ عَلَيْهِ إِذَا قَدِمَ ‏ ‏فَاطِمَةُ ‏ ‏قَالَ فَقَدِمَ مِنْ غَزَاةٍ لَهُ فَأَتَاهَا فَإِذَا هُوَ يَمْسَحُ عَلَى بَابِهَا وَرَأَى عَلَى ‏ ‏الْحَسَنِ ‏ ‏وَالْحُسَيْنِ ‏ ‏قَلْبَيْنِ مِنْ فِضَّةٍ فَرَجَعَ وَلَمْ يَدْخُلْ عَلَيْهَا فَلَمَّا رَأَتْ ذَلِكَ ‏ ‏فَاطِمَةُ ‏ ‏ظَنَّتْ أَنَّهُ لَمْ يَدْخُلْ عَلَيْهَا مِنْ أَجْلِ مَا رَأَى فَهَتَكَتْ السِّتْرَ وَنَزَعَتْ الْقَلْبَيْنِ مِنْ الصَّبِيَّيْنِ فَقَطَعَتْهُمَا فَبَكَى الصَّبِيَّانِ فَقَسَمَتْهُ بَيْنَهُمَا فَانْطَلَقَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمَا يَبْكِيَانِ فَأَخَذَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمَا فَقَالَ يَا ‏ ‏ثَوْبَانُ ‏ ‏اذْهَبْ بِهَذَا إِلَى بَنِي فُلَانٍ أَهْلُ بَيْتٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَاشْتَرِ ‏ ‏لِفَاطِمَةَ ‏ ‏قِلَادَةً مِنْ ‏ ‏عَصَبٍ ‏ ‏وَسِوَارَيْنِ مِنْ عَاجٍ فَإِنَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَلَا أُحِبُّ أَنْ يَأْكُلُوا طَيِّبَاتِهِمْ فِي حَيَاتِهِمْ الدُّنْيَا ‏","","",""],[21330,21330,"","আমরা সঠিক বাবা সম্পর্কে কথা বলেছি, আর এটা হতে যাচ্ছে। আশা করি, আপনি আমার বাবা ঈশ্বরের কাছে প্রার্থনা করছেন যেন তিনি তার শান্তি পাঠান এবং তাকে ঈশ্বরের কাছে বলতে বলেন যে ঈশ্বর আছে তিনি যখন তা গ্রহণ করেছিলেন, তখন ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তার প্রার্থনার জন্য প্রার্থনা করেছিলেন । কারণ কোন অপরাধ তৃতীয় বারের মত সমাধান করা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَأَبُو الْيَمَانِ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ الْأُمْلُوكِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسِيرٍ لَهُ ‏ ‏إِنَّا ‏ ‏مُدْلِجُونَ ‏ ‏فَلَا ‏ ‏يُدْلِجَنَّ ‏ ‏مُصْعِبٌ وَلَا مُضْعِفٌ ‏ ‏فَأَدْلَجَ ‏ ‏رَجُلٌ عَلَى نَاقَةٍ لَهُ صَعْبَةٍ فَسَقَطَ ‏ ‏فَانْدَقَّتْ ‏ ‏فَخِذُهُ فَمَاتَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّلَاةِ عَلَيْهِ ثُمَّ أَمَرَ مُنَادِيًا يُنَادِي فِي النَّاسِ إِنَّ الْجَنَّةَ لَا تَحِلُّ لِعَاصٍ إِنَّ الْجَنَّةَ لَا تَحِلُّ لِعَاصٍ ثَلَاثَ مَرَّاتٍ ‏","","",""],[21331,21331,"","আমি আমার বাবার সঙ্গে এক সেকেন্ডের জন্য আমার প্রেমের জন্য প্রার্থনা করতে চেয়েছিলাম । ( ২ বংশা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَمَّارٍ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنْصَرِفَ مِنْ صَلَاتِهِ اسْتَغْفَرَ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[21332,21332,"","আমরা আমার বাবার কথা বলেছিলাম, সে আমাকে ছেড়ে দিবে, আর আমি যুদ্ধ করব না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يَتَكَفَّلُ لِي بِوَاحِدَةٍ وَأَتَكَفَّلُ لَهُ بِالْجَنَّةِ قَالَ ‏ ‏ثَوْبَانُ ‏ ‏أَنَا قَالَ لَا تَسْأَلْ النَّاسَ ‏ ‏يَعْنِي شَيْئًا ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏فَكَانَ لَا يَسْأَلُ ‏","","",""],[21333,21333,"","আমরা দুজন বাপ্তিস্মের কথা বলেছি... ...যে আমরা ক্যাম্পের কাজ থেকে পলাতকদের জন্য কাজ করেছি, আমি বাবার ভালোবাসার দু:খজনকতার মধ্য দিয়ে এসেছি আর তাকে যেতে হবে আমি দুই ছেলে বলতে শুনেছি যে আমি তার জন্য প্রার্থনা করতে শুনেছি এবং সে বলবে আমার কুত্তা আমার জন্য খুবই খারাপ। আমি আশা করি একজন সাদা ছেলে যে তার খারাপ পথে চলে গেছে। সে মারগারিনদের পড়তে চেয়েছিল এই বলে যে পাপের জন্য ঈশ্বরের দয়াই তার নিজের। মঙ্গলের সেরা না হওয়াই ভালো। হয়তো আমি আমার বেঁচে আছি। ঈশ্বর এবং ঈশ্বর আমাকে রক্ষা করার জন্য জোর করেননি ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ المُهَاجِرِ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ سَالِمٍ اللَّخْمِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏إِلَى ‏ ‏أَبِي سَلَّامٍ الْحَبَشِيِّ ‏ ‏فَحُمِلَ إِلَيْهِ عَلَى الْبَرِيدِ يَسْأَلُهُ عَنْ الْحَوْضِ فَقُدِمَ بِهِ عَلَيْهِ فَسَأَلَهُ فَقَالَ سَمِعْتُ ‏ ‏ثَوْبَانَ ‏ ‏يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ حَوْضِي مِنْ ‏ ‏عَدَنَ ‏ ‏إِلَى ‏ ‏عَمَّانَ الْبَلْقَاءِ ‏ ‏مَاؤُهُ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ ‏ ‏وَأَكَاوِيبُهُ عَدَدُ النُّجُومِ مَنْ شَرِبَ مِنْهُ شَرْبَةً لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا أَوَّلُ النَّاسِ وُرُودًا عَلَيْهِ فُقَرَاءُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏مَنْ هُمْ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ هُمْ ‏ ‏الشُّعْثُ ‏ ‏رُءُوسًا ‏ ‏الدُّنْسُ ‏ ‏ثِيَابًا الَّذِينَ لَا يَنْكِحُونَ ‏ ‏الْمُتَنَعِّمَاتِ ‏ ‏وَلَا تُفْتَحُ لَهُمْ أَبْوَابُ ‏ ‏السُّدَدِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏لَقَدْ نَكَحْتُ ‏ ‏الْمُتَنَعِّمَاتِ ‏ ‏وَفُتِحَتْ لِي ‏ ‏السُّدَدُ ‏ ‏إِلَّا أَنْ يَرْحَمَنِي اللَّهُ وَاللَّهِ لَا جَرَمَ أَنْ لَا أَدْهُنَ رَأْسِي حَتَّى ‏ ‏يَشْعَثَ ‏ ‏وَلَا أَغْسِلَ ثَوْبِي الَّذِي يَلِي جَسَدِي حَتَّى يَتَّسِخَ ‏","","",""],[21334,21334,"","আমরা তার বই নিয়ে কথা বলেছি, সে ঈশ্বরের কাছে প্রার্থনা করবে যে, সে একটা ছেলেকে খুন করেছে বা সে কি বলেছে, একটা ভাঙ্গা গাছ নাকি একটা ব্যাজ দিয়ে গেছে। যথেষ্ট হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَيْخٌ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ صَغِيرًا أَوْ كَبِيرًا أَوْ أَحْرَقَ نَخْلًا أَوْ قَطَعَ شَجَرَةً مُثْمِرَةً أَوْ ذَبَحَ شَاةً لِإِهَابِهَا لَمْ يَرْجِعْ ‏ ‏كَفَافًا ‏","","",""],[21335,21335,"","সেই সময় একটা স্বপ্নের বিষয়ে আমরা কথা বলেছিলাম, যখন সেটা ঘটেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ الْكِبْرِ وَالدَّيْنِ وَالْغُلُولِ ‏","","",""],[21336,21336,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি, এমনকি আমাকে যেতে বলা পর্যন্ত আমরা কিছু সমস্যা নিয়ে অনেক কথা বলেছি। আমরা ঈশ্বরের কাছে প্রার্থনা করেছি এবং তিনি আমাকে আমার কাছে পাঠিয়ে দিতেন যে তিনি আমাকে দিতে পারতেন শুনেছি, সে বলছে যে, এটলাসকে যে খুঁজে পেয়েছে, তার কাছে ঈশ্বরের করুণা নেই অথবা তার উপর কোন সীমা নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَكْذِبُونَ عَلَيَّ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً أَوْ حَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[21337,21337,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি, আমরা ক্ষমার এক ইতিহাস খুঁজে পেয়েছি। তারপর তাকে ঈশ্বরের কাছে পাঠানো হয়েছিল, তার কাছে প্রার্থনা করলাম, আর তিনি ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করলেন। এবং তিনি ঈশ্বরের অনুগ্রহের জন্য তাঁর কাছে প্রার্থনা করলেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করলেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করলেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করলেন। এবং তিনি যেন তিনি তাঁর প্রতি অনুগ্রহ প্রকাশ করেন। এবং তিনি তাঁর প্রতি অনুগ্রহ প্রকাশ করেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করেন। এবং তিনি তাঁর প্রতি কৃতজ্ঞতা প্রকাশ করেন। এবং তিনি তাঁর প্রিয় জীবন-নিঃ আমাদের প্রিয়তম জীবন-নিঃ আমাদের জীবন-নিঃ আমাদের কাছে, এবং আমাদের জীবন-সত্ত্বে, আমাদের কাছে তাঁর প্রতি আমাদের প্রিয়তম। এবং আমাদের প্রিয়তমতমতমতমতমতমতমতম। এবং আমাদের কাছে তাঁর কাছে, এবং আমাদের কাছে তাঁর প্রতি আমাদের জীবন-সই যথেষ্ট। এবং আমাদের কাছে তাঁর নাম এবং আমাদের কাছে তাঁর কাছে তাঁর কাছে তাঁর নাম এবং আমাদের প্রিয়। ভিড় পাওয়া গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21338,21338,"","আমরা আমাদের বাবার শোকের কথা বলেছি, মানুষ বলছে আমরা হয়তো ঈশ্বরের দোহাই নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি ছিলেন। সকালের নাস্তার জন্য আত্মসমর্পণ করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْجُودِيِّ ‏ ‏عَنْ ‏ ‏بَلْجٍ ‏ ‏عَنْ ‏ ‏أَبِي شَيْبَةَ الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ قَاصَّ النَّاسِ ‏ ‏بِقُسْطَنْطِينِيَّةَ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏","","",""],[21339,21339,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমার বাবার রাজধানীর বিরুদ্ধে যুদ্ধ করেছে। লর্ডের কাছে যদি লোকটি প্রভুর কাছে ফিরে যায়, তাহলে ল্যাডারটা ভ্রূণের মাঝখানে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الرَّجُلُ الْمُسْلِمُ أَخَاهُ الْمُسْلِمَ فَهُوَ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ ‏","","",""],[21340,21340,"","আমরা বাবার প্রবল আবেগ নিয়ে কথা বলেছি, আর আমরা একটা রাজধানীর কথা বলেছি যেটা আমার বাবাকে বলেছিল বিশ্ব ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তিনি আমার কাছে আত্মসমর্পণ করবেন যে তার আছে। তার ইচ্ছা পেয়ে গেল, সেই অপরাধী বলেছে যে আমরা কখনো কিছু জিজ্ঞাসা করিনি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي الْعَالِيَةِ ‏ ‏مَا ‏ ‏ثَوْبَانُ ‏ ‏قَالَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَكَفَّلَ لِي أَنْ لَا يَسْأَلَ شَيْئًا وَأَتَكَفَّلُ لَهُ بِالْجَنَّةِ فَقَالَ ‏ ‏ثَوْبَانُ ‏ ‏أَنَا ‏ ‏فَكَانَ لَا يَسْأَلُ أَحَدًا شَيْئًا ‏","","",""],[21341,21341,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের বাবার ভালবাসার জন্য বহন করতে নিয়ে এসেছে। ঈশ্বরের দোহাই, আল্লাহ তা উদ্ধার করতে হবে এবং বলবে যে তিনি কারাগারে ফিরে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الرَّجُلُ أَخَاهُ فَإِنَّهُ فِي ‏ ‏أَخْرَافِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21342,21342,"","বাবা আমার প্রেমে ফিরে আসার পর আমি আমার বাবার কথা বলেছিলাম। আমি বলছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করে শুধু অন্ত্যেষ্টিক্রিয়ার অনুষ্ঠান পালন করে। সে বলেছে সে একটু কম পছন্দ করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَبِعَ جَنَازَةً فَلَهُ قِيرَاطٌ وَمَنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ قِيلَ وَمَا الْقِيرَاطَانِ قَالَ أَصْغَرُهُمَا مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21343,21343,"","আমরা লর্ড বেনের সাথে কথা বলেছি, আমি বলেছি যে আমার ছেলে ঈশ্বরের গৌরব কামনা করছে বলে যে আমি তার প্রভুর পরবর্তী পুত্র হতে আদেশ দিয়েছি এবং আমার কাছে আত্মসমর্পণ করতে চাই আল্লাহ আপনার উপর আস্থা রাখেন, অথবা আমি বলে দেই আমি ঈশ্বরের দোহাই করি, তাহলে আমি তাকে মেরে ফেলব। ঈশ্বর আপনাকে মেরে ফেলবে এবং সে আপনাকে মেরে ফেলবে, যাতে ঈশ্বর আপনাকে মেরে ফেলে। তারপর আমি বাবা রেডিং বাবাকে ছেড়ে দিলাম.","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ هِشَامٍ الْمُعَيْطِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مَعْدَانُ بْنُ أَبِي طَلْحَةَ الْيَعْمُرِيُّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَخْبِرْنِي بِعَمَلٍ أَعْمَلُهُ يُدْخِلُنِي اللَّهُ بِهِ الْجَنَّةَ ‏ ‏أَوْ قَالَ قُلْتُ بِأَحَبِّ الْأَعْمَالِ إِلَى اللَّهِ ‏ ‏فَسَكَتَ ثُمَّ سَأَلْتُهُ الثَّالِثَةَ فَقَالَ سَأَلْتُ عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَلَيْكَ بِكَثْرَةِ السُّجُودِ فَإِنَّكَ لَا تَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْكَ بِهَا خَطِيئَةً قَالَ ‏ ‏مَعْدَانُ ‏ ‏ثُمَّ لَقِيتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَسَأَلْتُهُ فَقَالَ لِي مِثْلَ مَا قَالَ لِي ‏ ‏ثَوْبَانُ ‏","","",""],[21344,21344,"","বাবার সাথে ঝগড়ার কথা বলেছিলাম, সে কী বলেছে, তুমি কখনোই জানবে না যে আমি প্রার্থনা করতে পারি, আর আলো দেখা যায় না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[21345,21345,"","আমরা পরের যে বিষয়টি নিয়ে কথা বলেছিলাম, সে বলল, \"আমি এটা করবো\" একজন মহিলা বন্য ভিত্তি থেকে তার মুখ ফিরিয়ে নেবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا الطَّلَاقَ مِنْ غَيْرِ مَا بَأْسٍ فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ ‏","","",""],[21346,21346,"","আমরা পরবর্তী যে কথা বলেছিলাম, সে বলল, \"বাবা,\" সে বলল, \"দুঃখিত, \"সে আমাকে বলে, \"সেভ, \"সে সংরক্ষণ, \"সে সংরক্ষণ,\" একজন ব্যক্তির কাজের জন্য অথবা তার ভদ্র কাজ অথবা ভদ্র আচরণ করার জন্য ঋণ পরিশোধ করা ভাল ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَفْضَلَ دِينَارٍ دِينَارٌ أَنْفَقَهُ رَجُلٌ عَلَى عِيَالِهِ أَوْ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ أَوْ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21347,21347,"","আমি যখন তাকে বলেছিলাম যে, আমি তাকে হত্যা করব, তখন তিনি আমাকে ক্ষমা করে দেবেন । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ قَالَ فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏فِي مَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ أَنَا صَبَبْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءَهُ ‏","","",""],[21348,21348,"","আমি বাবার মৃত্যুর ব্যাপারে কথা বলেছি, তারপর ভগবানের কাছে প্রার্থনা করলো যে এক মহিলাকে আত্মসমর্পণ করবে যে কিনা এক মহিলাকে আক্রমণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فِي رَمَضَانَ فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21349,21349,"","আমরা লর্ডের লর্ডের তৃতীয় দিনের জন্য এক সুখী ছেলের কথা বলেছি, তিনি যে জিতে গেছেন, আমি খুশি হব, যে লর্ডের কাছে আসবে এবং যিনি জিতবেন। যে তাকে কখনো শিক্ষা দিতে পারে নি, লাঠি এবং লাঠি মুছে ফেলতে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏فَأَصَابَهُمْ الْبَرْدُ فَلَمَّا قَدِمُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَكَوْا إِلَيْهِ مَا أَصَابَهُمْ مِنْ الْبَرْدِ ‏ ‏فَأَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى ‏ ‏الْعَصَائِبِ ‏ ‏وَالتَّسَاخِينِ ‏","","",""],[21350,21350,"","ঈশ্বর মৃত ব্যক্তিদের সমর্পণ করেছেন, যারা তার প্রতিরক্ষার জন্য প্রার্থনা করেছে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جِنَازَةٍ فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21351,21351,"","আমরা আমার বাবার ছেলের কথা বলছি, একজন যাজকের জন্য যিনি হয়ত বেঁচে গেছেন। ঈশ্বরের ইচ্ছা তার কাছে প্রার্থনা করবে এবং তাকে আত্মসমর্পণ করবে, যাকে আমি শুধু একজনই মেনে নেব ( ক) কেন যিশু তাঁর শিষ্যদের জন্য এক আদর্শ স্থাপন করেছিলেন?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَتَقَبَّلُ لِي بِوَاحِدَةٍ وَأَتَقَبَّلُ لَهُ بِالْجَنَّةِ قَالَ قُلْتُ أَنَا قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏فَكَانَ ‏ ‏ثَوْبَانُ ‏ ‏يَقَعُ سَوْطُهُ وَهُوَ رَاكِبٌ فَلَا يَقُولُ لِأَحَدٍ نَاوِلْنِيهِ حَتَّى يَنْزِلَ فَيَتَنَاوَلَهُ ‏","","",""],[21352,21352,"","আমরা ইতোমধ্যে বাবার ব্যাপারে দুই মাস কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে মানুষ লর্ডের শোকের দ্বারা পরাজিত হবে না। বন্য.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ وَلَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَلَا يَزِيدُ فِي الْعُمُرِ إِلَّا الْبِرُّ ‏","","",""],[21353,21353,"","আমরা আপনার ক্রেতার কথা বলেছি আমার বাবার সাথে ছেলের জন্ম দেয়ার কথা তিনি বললেন তিনি বলতে পারেন ঈশ্বর যদি বলেন তিনি ছেড়ে দিবেন, তিনি কালো পতাকাকে ছেড়ে দিবেন যদি তিনি দেখেন যে কাগোরাসরা থেকে আসা কালো পতাকাগুলো তারা মারা যেতে পারে, তারপর, সে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الرَّايَاتِ السُّودَ قَدْ جَاءَتْ مِنْ ‏ ‏خُرَاسَانَ ‏ ‏فَأْتُوهَا فَإِنَّ فِيهَا خَلِيفَةَ اللَّهِ ‏ ‏الْمَهْدِيَّ ‏","","",""],[21354,21354,"","আমরা কথা বলেছি পরবর্তী বিশ্বের জন্য বসবাসের জন্য, তিনি বলেছিলেন, \"ঈশ্বর তাকে জিজ্ঞাসা করেছেন এবং আত্মসমর্পণ করেছেন।\"","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا ‏ ‏لِقُرَيْشٍ ‏ ‏مَا اسْتَقَامُوا لَكُمْ ‏","","",""],[21355,21355,"","আমরা আমার ভাইয়ের বিষের জন্য ঈশ্বরের দুঃখ নিয়ে কথা বলেছি, তারপর দুই ছেলে তার কাছে প্রার্থনা করবে এবং আল্লাহ তার জন্য প্রার্থনা করবে। সে পরে যায় নি। অপরাধ বোমা হামলার ঘটনায় বলা হয়েছে যে অপরাধবাজ মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ قِيلَ وَمَا ‏ ‏خُرْفَةُ ‏ ‏الْجَنَّةِ قَالَ ‏ ‏جَنَاهَا ‏","","",""],[21356,21356,"","আমরা আমার বাবার সাথে ফিরে আসার পর আমার বাবা সালেমের শাসনের ব্যাপারে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আওস কে? তিন বার সন্তানের মৃত্যুর পর নির্দোষ ব্যক্তি মারা যায় ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ الْكِبْرِ وَالْغُلُولِ وَالدَّيْنِ فَهُوَ فِي الْجَنَّةِ ‏ ‏أَوْ وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[21357,21357,"","আমরা একজন পলাতকের সবচেয়ে ভালো ছেলে সম্পর্কে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি তাকে আলো দেব এবং এরপর বলবো, \"আমি এই পাপের জন্য প্রার্থনা করছি\"।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏ذَبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُضْحِيَّةً ثُمَّ قَالَ يَا ‏ ‏ثَوْبَانُ ‏ ‏أَصْلِحْ لَحْمَ هَذِهِ الشَّاةِ قَالَ فَمَا زِلْتُ أُطْعِمُهُ مِنْهَا ‏ ‏حَتَّى قَدِمَ ‏ ‏الْمَدِينَةَ ‏","","",""],[21358,21358,"","আমি যা বলছি তার চেয়ে ভালোর কথা বলেছি, আমি যা বলছি তা থেকে পালিয়ে যাবার চেষ্টা করছি। যারা প্রভুর সাথে যাবে তারা কখনো এটা ভাঙ্গবে না। আমি দুঃখিত, তিনি তার সাহস নিয়ে বলেছিলেন। আমরা যা কিছু জানি, তা যদি জানতাম, তা হলে আমরা যা করি, তাতে আমরা পড়ে গিয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏لَمَّا أُنْزِلَتْ ‏ { ‏الَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللَّهِ ‏} ‏قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فَقَالَ بَعْضُ أَصْحَابِهِ قَدْ نَزَلَ فِي الذَّهَبِ وَالْفِضَّةِ مَا نَزَلَ فَلَوْ أَنَّا عَلِمْنَا أَيُّ الْمَالِ خَيْرٌ اتَّخَذْنَاهُ فَقَالَ ‏ ‏أَفْضَلُهُ لِسَانًا ذَاكِرًا وَقَلْبًا شَاكِرًا وَزَوْجَةً مُؤْمِنَةً تُعِينُهُ عَلَى إِيمَانِهِ ‏","","",""],[21359,21359,"","আমরা বাবার সাথে আমার স্বপ্নের কথা বলেছি... ...তার কাছে প্রার্থনা করার সময় তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করবেন আর আমার মায়ের অনুমানে আমি ভয় পাব মায়ের মা ও মায়ের মা মা। মায়ের মায়ের মা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ ‏","","",""],[21360,21360,"","আমরা দুটো কথা বলেছি... ...আমার বাবা বলতে যাচ্ছিলেন যে ঈশ্বরের দোহাই আছে আর সে আত্মসমর্পণ করছে যখন আমি আমার মা মিস্টারের জন্য ভয় পাই.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ ‏","","",""],[21361,21361,"","আর তিনি ঈশ্বরের কাছে প্রার্থনা করতে বলেছিলেন, আর তিনি বলতে পারতেন যে ঈশ্বর জয়ী হয়েছেন কিনা এবং আমাকে জিজ্ঞেস করতে হবে যে, আমি যদি তার সঙ্গী এবং তার ঈর্ষা ও রাজার প্রতি আমার রাগ এবং রাজার মধ্যে তোমার রাজাও হতে চাই। আমি আমার মাকে অনুরোধ করব যেন তারা এক বছর পর্যন্ত যেতে না দেয়। ঈশ্বর, আমি দুঃখিত আমি দুঃখিত আমি দুঃখিত আমি দুঃখিত আমি বলতে চাইনি যে সে এটা বলতে চায় না যে আমি চাই না। তাদের জন্য এক বছরের জন্য পরোয়া করবেন না, আর আমার আর তাদের কাছে আর কিছু নেই। অথবা সে কি মনে করে যে তাদের কেউ কেউ কিছু ঝামেলা করবে, তারা টাকাও দেবে না। আমার মায়ের মিথ্যার মধ্যে এই দুই মিথ্যারই হবে, তারা আমার বাবার বাবা হতে যাচ্ছে আর আমি আমার মৃত্যুর ভয়ে ভীত। আমার মা সত্য থেকে, দুটো বিস্ময়কর বিষয় তাদের উত্তরাধিকারের ক্ষতি করবে না যতক্ষণ না আমি ঈশ্বর ও ম্যাগাজিন পার হই ।","‏ ‏وَبِهِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ ‏ ‏أَوْ قَالَ إِنَّ رَبِّي ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ ‏ ‏فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا وَإِنَّ مُلْكَ أُمَّتِي سَيَبْلُغُ مَا ‏ ‏زُوِيَ ‏ ‏لِي مِنْهَا وَإِنِّي أُعْطِيتُ الْكَنْزَيْنِ الْأَحْمَرَ وَالْأَبْيَضَ وَإِنِّي سَأَلْتُ رَبِّي لِأُمَّتِي أَنْ لَا يَهْلِكُوا بِسَنَةٍ بِعَامَّةٍ وَلَا يُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ سِوَى أَنْفُسِهِمْ يَسْتَبِيحُ ‏ ‏بَيْضَتَهُمْ ‏ ‏وَإِنَّ رَبِّي عَزَّ وَجَلَّ قَالَ ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي إِذَا قَضَيْتُ قَضَاءً فَإِنَّهُ لَا يُرَدُّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏لَا يُرَدُّ ‏ ‏وَإِنِّي أَعْطَيْتُكَ لِأُمَّتِكَ أَنْ لَا أُهْلِكَهُمْ بِسَنَةٍ بِعَامَّةٍ وَلَا أُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ سِوَى أَنْفُسِهِمْ يَسْتَبِيحُ ‏ ‏بَيْضَتَهُمْ ‏ ‏وَلَوْ اجْتَمَعَ عَلَيْهِمْ مَنْ بَيْنَ أَقْطَارِهَا ‏ ‏أَوْ قَالَ مَنْ بِأَقْطَارِهَا ‏ ‏حَتَّى يَكُونَ بَعْضُهُمْ ‏ ‏يَسْبِي بَعْضًا وَإِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ وَإِذَا وُضِعَ فِي أُمَّتِي السَّيْفُ لَمْ يُرْفَعْ عَنْهُمْ إِلَى يَوْمِ الْقِيَامَةِ وَلَا تَقُومُ السَّاعَةُ حَتَّى يَلْحَقَ قَبَائِلُ مِنْ أُمَّتِي بِالْمُشْرِكِينَ حَتَّى تَعْبُدَ قَبَائِلُ مِنْ أُمَّتِي الْأَوْثَانَ وَإِنَّهُ سَيَكُونُ فِي أُمَّتِي كَذَّابُونَ ثَلَاثُونَ كُلُّهُمْ يَزْعُمُ أَنَّهُ نَبِيٌّ وَأَنَا خَاتَمُ النَّبِيِّينَ لَا نَبِيَّ بَعْدِي وَلَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21362,21362,"","আমরা মাখন কীভাবে করব সে ব্যাপারে আমরা কথা বলেছি। আপনার পালনকর ্ তার সাথে আমার প্রভুর সাথে আপনার সম্পর্ক আছে। ঈশ্বর আদেশ দিয়েছেন, ঈশ্বর তাকে মাফ করে দিয়েছেন এবং প্রভুর কাছে নিজেকে সমর্পণ করেছেন। তাকে আদেশ দেওয়া হয়েছিল এবং ঈশ্বরের রাজ্যের বশীভূত হতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَالِمٍ ‏ ‏وَأَبُو بَكْرِ بْنُ الْوَلِيدِ الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْوَلِيدِ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏لُقْمَانَ بْنِ عَامِرٍ الْوُصَابِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى بْنِ عَدِيٍّ الْبَهْرَانِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عِصَابَتَانِ مِنْ أُمَّتِي أَحْرَزَهُمْ اللَّهُ مِنْ النَّارِ عِصَابَةٌ ‏ ‏تَغْزُو ‏ ‏الْهِنْدَ ‏ ‏وَعِصَابَةٌ تَكُونُ مَعَ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[21363,21363,"","আমরা ঐ পরিপক্ব বাবার সাথে কথা বলেছি, আমরা তোমার হারার ব্যাপারে কথা বলেছি কিন্তু আমি আমার শেষ সুযোগ নিয়ে কথা বলেছি। ঈশ্বর তাকে আশীর্বাদ করুন এবং বলেন ঈশ্বর তাকে আদেশ দিয়েছেন। আমি তোমার মায়ের কাছে অনুরোধ করছি। আমি আমার সব থেকে কিছু বলার। আমি আপনাদের মায়ের কাছে অনুরোধ করছি। আমি আপনাদের আমার মায়ের কাছে ক্ষমা প্রার্থনা করছি। আমি আপনাদের কাছে ক্ষমা চাই। আমি আপনাদের কাছে ক্ষমা চাই। আমি আমার জীবনের সব কিছু একটা গুরুত্বপূর্ণ বিষয় নিয়ে আলোচনা করেছি। আমি আপনাদের বলতে চাই। আমি আপনাদের কাছে বলতে চাই, আমি কি করতে চাই। আমি আপনাদের কাছে এটা একটা বিষয় নিয়ে কথা বলেছি। আমি আপনাদের কথা বলেছি, আমার মা-------------------------------------------------------------------------------------------------------------------------------------- সে যদি খায় তাহলে আমি খুব ক্লান্ত, কিন্তু তুমি একটা বোকা যে তোমার আত্মা নিয়ে চলে যাবে এবং তোমার সেবা করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْزُوقٌ أَبُو عَبْدِ اللَّهِ الْحِمْصِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَسْمَاءَ الرَّحَبِيُّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ تَدَاعَى عَلَيْكُمْ الْأُمَمُ مِنْ كُلِّ أُفُقٍ كَمَا تَدَاعَى الْأَكَلَةُ عَلَى ‏ ‏قَصْعَتِهَا ‏ ‏قَالَ قُلْنَا يَا رَسُولَ اللَّهِ أَمِنْ قِلَّةٍ بِنَا يَوْمَئِذٍ قَالَ أَنْتُمْ يَوْمَئِذٍ كَثِيرٌ وَلَكِنْ تَكُونُونَ ‏ ‏غُثَاءً ‏ ‏كَغُثَاءِ ‏ ‏السَّيْلِ يَنْتَزِعُ ‏ ‏الْمَهَابَةَ ‏ ‏مِنْ قُلُوبِ عَدُوِّكُمْ وَيَجْعَلُ فِي قُلُوبِكُمْ الْوَهْنَ قَالَ قُلْنَا وَمَا الْوَهْنُ قَالَ حُبُّ الْحَيَاةِ وَكَرَاهِيَةُ الْمَوْتِ ‏","","",""],[21364,21364,"","তিনি এমন একজন ছেলের কথা বলেছিলেন, যিনি ঈশ্বরের প্রতি অনুগত ছিলেন, তার কাছে প্রার্থনা করেছিলেন এবং এক মেয়ের মধ্যে পরিণত হয়েছিলেন, যিনি সেখানে যেতে যাচ্ছেন । আমার অনুগত ছেলেকে সমর্পণ করতে হবে । বলতেই হবে যে সে ঈশ্বরকে তার কাছে যেতে ব্যবহার করেছে। তার হাতে সে বলছে যে ঈশ্বর যেন তার হাতে পাপ তৈরি করেন। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি বলেছেন যে তিনি তাকে বলেছেন, তিনি যেন তিনি ঈশ্বরের কাছে ফিরে যান। ঈশ্বরের ইচ্ছার সাথে চলে গেছে, তিনি এটা করার আগে এটা করেছেন। দরজা বলেছিল, এটা দেখার জন্য তার কাছে একটা শপথ আছে। ভবিষ্যদ্বাণীতে বলা হয়েছে, তার কাছে প্রার্থনা করছে আর তা পৌঁছে যাবে। ( মথি ৬: ৯) তিনি সেই ছেলের কথা কখনো শোনেননি, তার কাছে প্রার্থনা করেছিলেন এবং তার মহান আশীর্বাদের জন্য প্রার্থনা করেছিলেন । তার জীবনের সসেজ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ سَلَّامٍ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا أَسْمَاءَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏ابْنَةَ هُبَيْرَةَ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي يَدِهَا خَوَاتِيمُ مِنْ ذَهَبٍ يُقَالُ لَهَا ‏ ‏الْفَتَخُ ‏ ‏فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَعُ يَدَهَا بِعُصَيَّةٍ مَعَهُ يَقُولُ لَهَا يَسُرُّكِ أَنْ يَجْعَلَ اللَّهُ فِي يَدِكِ خَوَاتِيمَ مِنْ نَارٍ فَأَتَتْ ‏ ‏فَاطِمَةَ ‏ ‏فَشَكَتْ إِلَيْهَا مَا صَنَعَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَانْطَلَقْتُ أَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ خَلْفَ الْبَابِ وَكَانَ إِذَا اسْتَأْذَنَ قَامَ خَلْفَ الْبَابِ ‏ ‏قَالَ فَقَالَتْ لَهَا ‏ ‏فَاطِمَةُ ‏ ‏انْظُرِي إِلَى هَذِهِ السِّلْسِلَةِ الَّتِي أَهْدَاهَا إِلَيَّ ‏ ‏أَبُو حَسَنٍ ‏ ‏قَالَ وَفِي يَدِهَا سِلْسِلَةٌ مِنْ ذَهَبٍ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ ‏ ‏بِالْعَدْلِ أَنْ يَقُولَ النَّاسُ ‏ ‏فَاطِمَةُ بِنْتُ مُحَمَّدٍ ‏ ‏وَفِي يَدِكِ سِلْسِلَةٌ مِنْ نَارٍ ثُمَّ ‏ ‏عَذَمَهَا ‏ ‏عَذْمًا ‏ ‏شَدِيدًا ثُمَّ خَرَجَ وَلَمْ يَقْعُدْ فَأَمَرَتْ بِالسِّلْسِلَةِ فَبِيعَتْ فَاشْتَرَتْ بِثَمَنِهَا عَبْدًا فَأَعْتَقَتْهُ فَلَمَّا سَمِعَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبَّرَ وَقَالَ الْحَمْدُ لِلَّهِ الَّذِي نَجَّى ‏ ‏فَاطِمَةَ ‏ ‏مِنْ النَّارِ ‏","","",""],[21365,21365,"","আমরা এক জীবন নিয়ে জন্মগ্রহণ করেছি, যে আমার বাবা আর ছেলের কথা বলে, তার মানে আমার বাবার জন্য জীবন যাপন করা। তারপর তিনি ঈশ্বরের কাছে প্রার্থনা করলেন এবং তার জন্য প্রার্থনা করলেন এবং তার প্রভুর কাছে প্রার্থনা করলেন। আমার পাপী হবে।","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاشِيَ وَالْمُرْتَشِيَ ‏ ‏وَالرَّائِشَ ‏ ‏يَعْنِي الَّذِي يَمْشِي بَيْنَهُمَا ‏","","",""],[21366,21366,"","আমরা এই বাপ্তাইজিত হয়েছি যে আমি মেমো্যান বা বাবার অন্ত্যেষ্টিক্রিয়ার ব্যাপারে কত কিছু বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَيْمُونٌ أَبُو مُحَمَّدٍ الْمُزَنِيُّ التَّمِيمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ الْمَخْزُومِيُّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ النَّسَاءُ فِي الْأَجَلِ وَالزِّيَادَةُ فِي الرِّزْقِ فَلْيَصِلْ رَحِمَهُ ‏","","",""],[21367,21367,"","আমরা আশীর্বাদ নিয়ে কথা বলেছি, কে কথা বলেছে, সে বলবে প্রভু ঈশ্বরের স্পর্শ করবে আর চলে যাবেন না, আমি সন্তুষ্ট নই যে আমার দয়া হচ্ছে ঈশ্বরের দয়া যেন হয়। সে বলল সে আকাশে থাকে আর তারপর সে এটার জন্য যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَيْمُونٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ الْعَبْدَ لَيَلْتَمِسُ ‏ ‏مَرْضَاةَ ‏ ‏اللَّهِ وَلَا يَزَالُ بِذَلِكَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنَّ فُلَانًا عَبْدِي يَلْتَمِسُ أَنْ يُرْضِيَنِي أَلَا وَإِنَّ رَحْمَتِي عَلَيْهِ فَيَقُولُ ‏ ‏جِبْرِيلُ ‏ ‏رَحْمَةُ اللَّهِ عَلَى فُلَانٍ وَيَقُولُهَا حَمَلَةُ الْعَرْشِ وَيَقُولُهَا مَنْ حَوْلَهُمْ حَتَّى يَقُولَهَا أَهْلُ السَّمَوَاتِ السَّبْعِ ثُمَّ تَهْبِطُ لَهُ إِلَى الْأَرْضِ ‏","","",""],[21368,21368,"","আমরা একটা আশীর্বাদের কথা বলেছি, আমরা কথা বলেছি, কিন্তু এটা প্রেম নিয়ে। সে তাদেরকে ছেড়ে দেবে না, আর সে তাদের মরতে বলবে না। বাড়ি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَيْمُونٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُؤْذُوا عِبَادَ اللَّهِ وَلَا تُعَيِّرُوهُمْ وَلَا تَطْلُبُوا عَوْرَاتِهِمْ فَإِنَّهُ مَنْ طَلَبَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ طَلَبَ اللَّهُ عَوْرَتَهُ حَتَّى يَفْضَحَهُ فِي بَيْتِهِ ‏","","",""],[21369,21369,"","আমার বাবা তার বাবার সঙ্গে কথা বলেছিলেন, যাতে তিনি ঈশ্বরের কাছে প্রার্থনা করতে পারেন এবং আমার মায়ের কাছ থেকে তার আত্মাকে হারাতে না পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21370,21370,"","আমরা আমার বাবার কথা বলেছিলাম যে পরবর্তী জিনিস তার নামে আমার বাবা রাখা হয়েছে, আমি জানি সে কয়েক বছর ধরে তাকে ধাক্কা দিয়েছে. ক্রিশ্চিয়ান পুত্র.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏لَا أَعْلَمُهُ إِلَّا قَدْ رَفَعَهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ ‏ ‏وَلَمْ يَشُكَّ فِيهِ ‏ ‏ابْنُ مَهْدِيٍّ ‏","","",""],[21371,21371,"","আমরা একটি বিশেষ হাত দিয়ে কথা বলেছি যে আমরা মঙ্গলভাবের প্রতিজ্ঞা নিয়ে দেখা করেছি। ঈশ্বরের কাছে প্রার্থনা করেছি যেন তিনি তাকে বলতে বলেন যে ঈশ্বর এসেছে। একজন মানুষ হবে। এই পাগলামির মধ্যে রয়েছে আমি সৃষ্টিকর্তা মানুষকে জিজ্ঞেস না করতে বলেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُثْمَانَ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْبَانُ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَضْمَنُ لِي وَاحِدَةً وَأَضْمَنُ لَهُ الْجَنَّةَ قَالَ قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏قَالَ ‏ ‏فَكَانَ سَوْطُ ‏ ‏ثَوْبَانَ ‏ ‏سَقَطَ وَهُوَ عَلَى بَعِيرِهِ ‏ ‏فَيُنِيخُ ‏ ‏حَتَّى يَأْخُذَهُ وَمَا يَقُولُ لِأَحَدٍ نَاوِلْنِيهِ ‏","","",""],[21372,21372,"","এরপর তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং এরপর তিনি তার ঈশ্বরের কাছে এক ঋণের কথা বলেছিলেন । ঈশ্বরের পথে চেষ্টা করার সময় বাবা বলেছিলেন, সে হয়ত খেলতে শুরু করবে এবং বলবে, \"শহীদ\"। আমি তার দরজায় একজন মানুষকে ব্যয় করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ عَلَى عِيَالِهِ ثُمَّ عَلَى نَفْسِهِ ثُمَّ فِي سَبِيلِ اللَّهِ ثُمَّ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏فَيَبْدَأُ بِالْعِيَالِ ‏ ‏و قَالَ ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏دِينَارٌ أَنْفَقَهُ رَجُلٌ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21373,21373,"","আমরা আমার বাবার সাথে কথা বলেছি যখন তিনি বলেছিলেন, \"ঈশ্বর, আল্লাহ তাকে আত্মসমর্পণ করতে হবে যদি তার ভাই শান্তি ফিরে আসে যতক্ষণ না তাকে কারাগারে পাঠানো হয়। সে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21374,21374,"","আমরা দেয়াল নিয়ে কথা বলেছি, কিন্তু আমি খুঁজে বের করার চেষ্টা করছি। আমি দুঃখিত, ঈশ্বর আমাকে বলেছেন, এটা ঈশ্বরের ইচ্ছা। তিনি বলেছিলেন, ঈশ্বর যেন তিন থেকে ৩ বার ক্ষমা করেন এবং তারপর তিনি তাদের বলেন। তুমি সিঁড়ির মধ্যে আছো আর তুমি পাহাড়ের ডাক.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أَسْمَاءَ الرَّحَبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْبَانُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنْصَرِفَ مِنْ صَلَاتِهِ قَالَ ‏ ‏أَسْتَغْفِرُ اللَّهَ ثَلَاثًا ثُمَّ يَقُولُ اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ ‏ ‏تَبَارَكْتَ ذَا الْجِلَالِ وَالْإِكْرَامِ ‏","","",""],[21375,21375,"","আমরা কথা বলেছিলাম দুই বাচ্চা তাঁর পথে আসছে, সে বলবে আমাদের সময় কাটাতে হবে যারা যুদ্ধ করবে তাদের সাথে সময় কাটাতে হবে। আমার নিজের ইট থেকে বলতে পারে, সে দুই শ্রেণীর শহরে গান গেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا ‏ ‏بِعُقْرِ ‏ ‏حَوْضِي يَوْمَ الْقِيَامَةِ أَذُودُ عَنْهُ النَّاسَ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏وَأَضْرِبُهُمْ بِعَصَايَ حَتَّى يَرْفَضَّ عَنْهُمْ قَالَ قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا سَعَتُهُ قَالَ مِنْ مَقَامِي إِلَى ‏ ‏عُمَانَ ‏ ‏يَغُتُّ ‏ ‏فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَمُدَّانِهِ ‏","","",""],[21376,21376,"","এরপর দুজন ছেলে ঈশ্বরকে অনুরোধ করবে এবং তাকে উদ্ধার করবে । যাদের প্রয়োজন তাদের হত্যা করা হবে এবং তাদের খুঁজে পাওয়া প্রয়োজন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَقِيعِ ‏ ‏فِي ثَمَانِ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ رَمَضَانَ بِرَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21377,21377,"","ঈশ্বর এই বিষয়ে শুনেছিলেন এবং ঈশ্বরের প্রতি ফিরে আসবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏مَعْدَانُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِثَوْبَانَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِّثْنَا حَدِيثًا يَنْفَعُنَا اللَّهُ بِهِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[21378,21378,"","আমরা একটা সৌভাগ্যের জন্য বিচার করেছি... ...যা আমার ভালবাসার জন্য হয়েছে তার জন্য... ...দুই ছেলে তার জন্য প্রার্থনা করেছে আর সে অন্ধকার শব্দ দিয়েছে আজকের বিখ্যাত মাস কে দেখেছে, বছরের এই সময়টা তুমি করছ।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ الذِّمَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ فَشَهْرٌ بِعَشَرَةِ أَشْهُرٍ وَصِيَامُ سِتَّةِ أَيَّامٍ بَعْدَ الْفِطْرِ فَذَلِكَ تَمَامُ صِيَامِ السَّنَةِ ‏","","",""],[21379,21379,"","আমরা ঈশ্বরের সেরাটার ব্যাপারে কথা বলেছি, কিন্তু আল্লাহ্ জানেন আমি কি করতে চাইছি। তারপর তিনি লর্ডকে প্রার্থনা করলেন এবং তাকে ঈশ্বরের কাছে পৌঁছে দেয়া হবে। চাঁদ, আলো না এবং আগুনের শিখাকে অস্বীকার করা যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَلَا يَزِيدُ فِي الْعُمُرِ إِلَّا الْبِرُّ وَإِنَّ الْعَبْدَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ ‏","","",""],[21380,21380,"","ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং ছায়ার ছায়ার ছায়ার ছায়ার ছায়ার কাছে আত্মসমর্পণ করেছিলেন । সে একটা রাজধানী বলেছিল, সে জেগে উঠবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏وَعِصَامُ بْنُ خَالِدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَقِيمُوا تُفْلِحُوا وَخَيْرُ أَعْمَالِكُمْ الصَّلَاةُ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏ ‏وَقَالَ ‏ ‏عِصَامٌ ‏ ‏وَلَا يُحَافِظُ ‏","","",""],[21381,21381,"","আমরা একজন বারবারের সাথে প্রেম-ভাল জীবনের কাহিনী শোনার মাধ্যমে বিচারকের বিচার করেছি। এমনকি লেখক তাকে উদ্ধার করতে চায় এবং তাকে জিজ্ঞেস করে যে, সে আর পারবে না পালানোর জন্য, যদি তুমি এটা ছেড়ে দাও, তাহলে আমরা দেখতে পাবো এটা চলে গেছে। এটাকে আমরা নিশ্চিতভাবে বলতে পারি যে, আমরা অপরিহার্যতার সবচেয়ে ভালোটা খুঁজে বের করার চেষ্টা করেছি। সে একজন মাতাল মানুষের চেয়ে বেশি। যার কথা তার সাথে ছিল.","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَيٍّ الْمُؤَذِّنِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لَامْرِئٍ مِنْ الْمُسْلِمِينَ أَنْ يَنْظُرَ فِي ‏ ‏جَوْفِ ‏ ‏بَيْتِ امْرِئٍ حَتَّى يَسْتَأْذِنَ فَإِنْ نَظَرَ فَقَدْ دَخَلَ وَلَا يَؤُمَّ قَوْمًا فَيَخْتَصَّ نَفْسَهُ بِدُعَاءٍ دُونَهُمْ فَإِنْ فَعَلَ فَقَدْ خَانَهُمْ وَلَا يُصَلِّ وَهُوَ ‏ ‏حَقِنٌ ‏ ‏حَتَّى ‏ ‏يَتَخَفَّفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ يَعْنِي الْخَطَّابِيَّ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ ‏ ‏فَذَكَرَ مَعْنَاهُ بِإِسْنَادِهِ ‏","","",""],[21382,21382,"","আমরা যে ভালো কাজ করেছি তার বিচারকের কাছে আমরা কথা বলেছি, ঈশ্বর তার পিতা, তার কাপুরুষ, ছেলে, প্রভু এবং তার প্রভুর জন্য আশীর্বাদ করুন। তিনি হাল ছেড়ে দেওয়ার চেয়ে দুই কি বেশি কিছু পাবেন।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُبَيْدٍ الْكَلَاعِيِّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ سَهْوٍ سَجْدَتَانِ بَعْدَ مَا يُسَلِّمُ ‏","","",""],[21383,21383,"","আমরা দুই জোড়া যমজের কথা বলেছি, তার সাথে ঈশ্বরের উদ্দেশ্যের উপর তার আস্থার কথা তিনি আমার মনের উপর দিয়ে বলেন, তিনি একটি পাহাড় মধ্যে যাওয়ার প্রতিজ্ঞা করেছেন। এবং তারপর আমি লিখে যাচ্ছি আমরা এটা করব। এবং আমি জানি যে আমরা কি করি। আমিও তাই বিশ্বাস করি যে ঈশ্বর একটা কুত্তার বাচ্চা হতে পারেন, সে চলে যাওয়ার পর সে আত্মসমর্পণ করবে আর তারপর সে নরকে চলে যাবে। সে বলেছিল আমরা তাকে নিয়ে যেতে পারব। এরপর তিনি ভিতরে গিয়ে ফিরে যান এবং এক ঘন্টা সময় নেন এবং তারপর তার সময় নেন । আর সে বলল, আমি তার কাছে প্রার্থনা করলাম, আর তার নাম শুনে শুনে শুনেছি যে সে তার মায়ের ভিতরে যাবে। আর হাজার হাজার সাহায্য পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏قَالَ ‏ ‏شُرَيْحُ بْنُ عُبَيْدٍ ‏ ‏مَرِضَ ‏ ‏ثَوْبَانُ ‏ ‏بِحِمْصَ ‏ ‏وَعَلَيْهَا ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ الْأَزْدِيُّ ‏ ‏فَلَمْ يَعُدْهُ فَدَخَلَ عَلَى ‏ ‏ثَوْبَانَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْكَلَاعِيِّينَ ‏ ‏عَائِدًا فَقَالَ لَهُ ‏ ‏ثَوْبَانُ ‏ ‏أَتَكْتُبُ فَقَالَ نَعَمْ فَقَالَ اكْتُبْ فَكَتَبَ لِلْأَمِينِ ‏ ‏عَبْدِ اللَّهِ بْنِ قُرْطٍ ‏ ‏مِنْ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا بَعْدُ فَإِنَّهُ لَوْ كَانَ ‏ ‏لِمُوسَى ‏ ‏وَعِيسَى ‏ ‏مَوْلًى بِحَضْرَتِكَ لَعُدْتَهُ ثُمَّ طَوَى الْكِتَابَ وَقَالَ لَهُ أَتُبَلِّغُهُ إِيَّاهُ فَقَالَ نَعَمْ فَانْطَلَقَ الرَّجُلُ بِكِتَابِهِ فَدَفَعَهُ إِلَى ‏ ‏ابْنِ قُرْطٍ ‏ ‏فَلَمَّا قَرَأَهُ قَامَ فَزِعًا فَقَالَ النَّاسُ مَا شَأْنُهُ أَحَدَثَ أَمْرٌ فَأَتَى ‏ ‏ثَوْبَانَ ‏ ‏حَتَّى دَخَلَ عَلَيْهِ ‏ ‏فَعَادَهُ ‏ ‏وَجَلَسَ عِنْدَهُ سَاعَةً ثُمَّ قَامَ فَأَخَذَ ‏ ‏ثَوْبَانُ ‏ ‏بِرِدَائِهِ وَقَالَ اجْلِسْ حَتَّى أُحَدِّثَكَ حَدِيثًا سَمِعْتُهُ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ وَلَا عَذَابَ مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا ‏","","",""],[21384,21384,"","বাবার মৃত্যুর পর থেকে আমরা অনেক ভালো কথা বলেছি। সাধারণ","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عُتْبَةَ أَبِي أُمَيَّةَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ وَعَلَى ‏ ‏الْخِمَارِ ‏ ‏ثُمَّ الْعِمَامَةِ ‏","","",""],[21385,21385,"","আমরা ঈশ্বরের কথা বলেছি, আর সে তোমাকে কাজে লাগাতে চেষ্টা করবে. খুশি যে আমার বাবার শপথের জন্য বাবার বাবার বাবার বাবার বাবার কাছে শপথের প্রতিজ্ঞার কথা। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং তিনি বলবেন যে, তার সম্বন্ধে গান গাওয়ার জন্য কাকেই বা বলতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَأَلَ مَسْأَلَةً وَهُوَ عَنْهَا غَنِيٌّ كَانَتْ شَيْئًا فِي وَجْهِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[21386,21386,"","দিনের ভালোবাসায় আমরা প্রেম বলেছি, যেদিন আমি ভাইয়ের সাথে কথা বলেছি, ঈশ্বরের প্রার্থনা আছে যেন তিনি ঈশ্বরের কাছে আত্মসমর্পণ করেন, যার কাছে আমি কার কাছে। আর আমি প্রার্থনা করব যেন এই দৈত্যটা বলে যে আমি তখনও তার কাছ থেকে এটা ফেলে দেই যতক্ষণ না সে ধ্বংস হয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذَبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُضْحِيَّةً لَهُ ثُمَّ قَالَ لِي يَا ‏ ‏ثَوْبَانُ ‏ ‏أَصْلِحْ لَحْمَ هَذِهِ الشَّاةِ قَالَ فَمَا زِلْتُ أُطْعِمُهُ مِنْهَا حَتَّى قَدِمَ ‏ ‏الْمَدِينَةَ ‏","","",""],[21387,21387,"","আমি ক্লান্ত হয়ে গেলে ঈশ্বরের ভালবাসা নিয়ে কথা বলেছি। ঈশ্বর আমাকে দু'জন ছেলে-জন ঈশ্বরের কাছে প্রার্থনা করে। সে বলে, \"ঈশ্বর\" অথবা নরক থেকে বেরিয়ে এসো। তার অপরাধ.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ يَعْنِي الْأَحْوَلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ يَعْنِي أَبَا قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ فَقِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏خُرْفَةُ ‏ ‏الْجَنَّةِ قَالَ ‏ ‏جَنَاهَا ‏","","",""],[21388,21388,"","ঈশ্বরের কাছে আমার বাবার ছেলেকে রক্ষা করার কথা বলেছিলাম। ঈশ্বরের দুই ছেলের জন্য যুদ্ধ করা হয়েছে এবং আল্লাহ তাকে রক্ষা করেছেন। আমি যদি বলি, আমি তাকে চুমু দিতে পারি, আমি শুধু তাকে চুমু দিতে চাই। তাহলে তার ক্রুশটা আছে, তাই আমি কাউকে তার হাত তুলে নিতে বলি, সে একটা ছেলের ভালোর জন্য ভাল কিছু খোঁজে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমাকে আত্মসমর্পণ করেছেন, যার একটি মোদ্দা আছে এবং স্বর্গ আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَتَقَبَّلُ لِي بِوَاحِدَةٍ أَتَقَبَّلُ لَهُ بِالْجَنَّةِ قَالَ قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏قَالَ ‏ ‏فَرُبَّمَا سَقَطَ سَوْطُ ‏ ‏ثَوْبَانَ ‏ ‏وَهُوَ عَلَى بَعِيرِهِ فَمَا يَسْأَلُ أَحَدًا أَنْ يُنَاوِلَهُ حَتَّى يَنْزِلَ إِلَيْهِ فَيَأْخُذَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَضْمَنُ لِي ‏ ‏خُلَّةً ‏ ‏وَأَضْمَنُ لَهُ الْجَنَّةَ فَذَكَرَ مَعْنَاهُ ‏","","",""],[21389,21389,"","আমরা একটা বাচ্চা থাকার কথা বলেছিলাম । ঈশ্বরের অনুগ্রহে, জল শক্তি আসার আগে... ...ঈশ্বর আপনার ক্ষতি করবেন... ...এবং আপনার রাজা হবেন। তিন দিনের মধ্যে সূর্য ফিসফিস করে কথা বলছে, যখন এটা ভালো হয় না। সে খুশি হবে যে সে সাহায্য করতে পারবে না কিন্তু ঈশ্বর তা করতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَرْزُوقٌ أَبُو عَبْدِ اللَّهِ الشَّامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْبَانُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَصَابَ أَحَدَكُمْ الْحُمَّى وَإِنَّ الْحُمَّى قِطْعَةٌ مِنْ النَّارِ فَلْيُطْفِئْهَا عَنْهُ بِالْمَاءِ الْبَارِدِ وَلْيَسْتَقْبِلْ نَهَرًا جَارِيًا يَسْتَقْبِلُ جِرْيَةَ الْمَاءِ فَيَقُولُ بِسْمِ اللَّهِ اللَّهُمَّ اشْفِ عَبْدَكَ وَصَدِّقْ رَسُولَكَ بَعْدَ صَلَاةِ الْفَجْرِ قَبْلَ طُلُوعِ الشَّمْسِ فَيَغْتَمِسُ فِيهِ ثَلَاثَ ‏ ‏غَمَسَاتٍ ثَلَاثَةَ أَيَّامٍ فَإِنْ لَمْ يَبْرَأْ فِي ثَلَاثٍ فَخَمْسٍ فَإِنْ لَمْ يَبْرَأْ فِي خَمْسٍ فَسَبْعٍ فَإِنْ لَمْ يَبْرَأْ فِي سَبْعٍ فَتِسْعٍ فَإِنَّهُ لَا يَكَادُ يُجَاوِزُ التِّسْعَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21390,21390,"","বাবার ভালবাসার পর আমার বাবার যে ভাল অভিজ্ঞতা হয়েছে, আমি তার কথা বলেছি। তারপর ঈশ্বরের কাছে প্রার্থনা করবো। আমি বলবো, আমি আমার হৃদয় বেছে নেব। এমনকি তাদেরকে আমার মৃত্যুও বলে দেব। আমার মনে হয় আমার দুই মাইলের অপরাধ করার রাস্তা আছে... ...আর অন্য কোথাও থেকে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي ‏ ‏لَبِعُقْرِ ‏ ‏حَوْضِي أَذُودُ عَنْهُ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏أَضْرِبُ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ فَسُئِلَ عَنْ عَرْضِهِ فَقَالَ مِنْ مُقَامِي إِلَى ‏ ‏عُمَانَ ‏ ‏وَسُئِلَ عَنْ شَرَابِهِ فَقَالَ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ يَنْشَعِبُ فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَمُدَّانِهِ ‏ ‏مِنْ الْجَنَّةِ أَحَدُهُمَا مِنْ ذَهَبٍ وَالْآخَرُ مِنْ وَرِقٍ ‏","","",""],[21391,21391,"","আমরা একটি মহান আশীর্বাদ সঙ্গে কথা করেছি এবং আমরা আমার প্রেমের সঙ্গে জন্ম গ্রহণ করার একটি সুখী প্রতিশ্রুতি সঙ্গে সঙ্গে সঙ্গে চলে. ঈশ্বরের কাছে আত্মসমর্পণ করা তাঁর কাছে এসেছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ ‏ ‏الْكِبْرِ ‏ ‏وَالْغُلُولِ وَالدَّيْنِ ‏","","",""],[21392,21392,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের একটা খুন সম্পর্কে একটা যুদ্ধ এনেছে। আমার বাবা বলেছিলেন, তিনি তার ইচ্ছার জন্য দু'মিনিটের একটা পৃথিবী চান। তার জন্য প্রার্থনা করো আর সে খুনিকে আত্মসমর্পণ করবে... ...যে পালিয়ে গেছে আর ৩ জনের মৃত্যু হয়েছে, আর বড়দের জন্য সে নির্দোষ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ الْغُلُولِ وَالدَّيْنِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَالْكِبْرِ ‏","","",""],[21393,21393,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যার ফলে আমরা ভালোবাসা নিয়ে খুশি হয়েছি। ঈশ্বরের অনুগ্রহে দুই সন্তানের জন্য তাকে আদেশ দেয়া হয়েছে এবং ঈশ্বরের অনুগ্রহে আত্মসমর্পণ করা হয়েছে এবং তার প্রভুর অনুগ্রহে আত্মসমর্পন করা হয়েছে। শান্তি আর ভিড় পাওয়া গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21394,21394,"","বাবা আমার সাথে কিভাবে সাহায্য করতে চাচ্ছেন, আমার বাবা টেবিলের উপর বলেছেন যে আমি তার কাছে প্রার্থনা করেছি যাতে আমি যেতে পারি, যতক্ষণ না তারা আমার লাঠি দিয়ে তাদের সাথে মারতে পারে আমার দৃষ্টি বা আমার পায়ের কি বলতে হবে তা নিয়ে যাওয়া আমার জন্য একমাত্র মূল্য।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ أَبِي السُّمَيْطِ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا عِنْدَ ‏ ‏عُقْرِ ‏ ‏حَوْضِي أَذُودُ النَّاسَ عَنْهُ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏إِنِّي لَأَضْرِبُهُمْ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ وَإِنَّهُ ‏ ‏لَيَغُتُّ ‏ ‏فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏أَحَدُهُمَا مِنْ وَرِقٍ وَالْآخَرُ مِنْ ذَهَبٍ مَا بَيْنَ ‏ ‏بُصْرَى ‏ ‏وَصَنْعَاءَ ‏ ‏أَوْ مَا بَيْنَ ‏ ‏أَيْلَةَ ‏ ‏وَمَكَّةَ ‏ ‏أَوْ قَالَ مِنْ مُقَامِي هَذَا إِلَى ‏ ‏عُمَانَ ‏","","",""],[21395,21395,"","আমরা সবচেয়ে ভালোটার বিষয়ে কথা বলেছিলাম, আমাদেরকে বলেছিলাম যে, আমরা একজন পিপপি পুত্র, যে আপনার ভাইয়ের সঙ্গে কথা বলেছিল । তিনি বলেছিলেন, প্রয়োজন এবং ভিড়ের কথা চিন্তা করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَكْحُولٌ ‏ ‏أَنَّ ‏ ‏شَيْخًا ‏ ‏مِنْ الْحَيِّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ثَوْبَانَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21396,21396,"","আমি আমার বাবার সবচেয়ে ভালো কথা বলেছি, কিন্তু ঈশ্বর আমার ব্যাপারে কথা বলেছেন। আমি আমার বাবার সাথে কথা বলেছি যে তিনি আমাকে বললেন আর তিনি বললেন না যে ঈশ্বর তাকে রক্ষা করেছেন। ( খ) কীভাবে আমরা জানি যে, যিহোবা তাঁর লোকেদের রক্ষা করবেন?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَوْبَانُ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي فِي ‏ ‏الْبَقِيعِ ‏ ‏فِي رَمَضَانَ رَأَى رَجُلًا ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21397,21397,"","আমরা লর্ড বেনের সাথে কথা বলেছি, থান এর ছেলে আর তার ছেলে আমার সাথে কথা বলেছে, যে আমার বাবার সাথে কথা বলেছে, আমি প্রার্থনা করি এবং নিরাপদ না হলে আলো জেগে উঠতে পারি না।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏حَدَّثَنِي ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَا كَبْشَةَ السَّلُولِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا وَاعْمَلُوا وَخَيِّرُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[21398,21398,"","সেই সময় একটা স্বপ্নের বিষয়ে আমরা কথা বলেছিলাম, যখন সেটা ঘটেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ ‏ ‏الْكِبْرِ ‏ ‏وَالدَّيْنِ وَالْغُلُولِ ‏","","",""],[21399,21399,"","আমরা একটি সুখী সেবা কথা বলেছি যে কিনা ঈশ্বরের জন্য গেরিলা হয়ে আসছে, তাকে আত্মসমর্পণ করতে হবে। তার ঘৃণা দেখে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21400,21400,"","আমরা আমার বাবার সালেম সম্পর্কে কথা বলেছি, আর সে বলেছে সে ভুলে গেছে যে ঈশ্বর জানে আমি তোমার প্রার্থনা আর স্বপ্নের কথা ভুলে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""]];
